COLLDATA("sh10272","ar",[[1,"ـ[الجامع في العلل ومعرفة الرجال لأحمد بن حنبل]ـ"],[2,"المؤلف: أبو عبد الله أحمد بن محمد بن حنبل بن هلال بن أسد الشيباني (المتوفى: ٢٤١هـ)"],[3,"رواية: المروذي وغيره"],[4,"المحقق: الدكتور وصى الله بن محمد عباس"],[5,"الناشر: الدار السلفية، بومباى - الهند"],[6,"الطبعة: الأولى، ١٤٠٨ هـ - ١٩٨٨ م"],[7,"عدد الأجزاء: ١"],[8,"[ترقيم الكتاب موافق للمطبوع]"],[9,"[المروذي]"],[10,"١"],[11,"- أخبرنَا أَبُو أَحْمد الْحُسَيْن بن عَليّ بن مُحَمَّد بن يحيى التَّمِيمِي النَّيْسَابُورِي، حَدثنَا أَبُو عوَانَة يَعْقُوب بن إِسْحَاق الإسفرائيني، بإسفرائين قَرْيَة فَوق نيسابور ثَلَاثِينَ فرسخا."],[12,"قَالَ: حَدثنَا أَحْمد بن مُحَمَّد الْحجَّاج الْمَرْوذِيّ أَبُو بكر، بطرسوس، قِرَاءَة علينا، قَالَ: وَذكر لَهُ التَّدْلِيس يَعْنِي لِأَحْمَد بن حَنْبَل، رحمه الله، فَقَالَ:"],[13,"قد دلّس قوم، وَذكر الْأَعْمَش، وَذكر لَهُ مُجَاهِد، وَسَعِيد بن جُبَير أَنه يروي عَنْهُمَا؟ فَقَالَ: نعم، ثمَّ قَالَ: كَانَ أَبُو حرَّة صَاحب تَدْلِيس، عَن الْحسن، إِلَّا أَن يحيى روى عَنهُ ثَلَاثَة أَحَادِيث، يَقُول فِي بَعْضهَا: حَدثنَا الْحسن، مِنْهَا حَدِيث سعد بن هِشَام، حَدِيث عَائِشَة فِي الرَّكْعَتَيْنِ."],[14,"وَقَالَ: كَانَ ابْن إِسْحَاق يُدَلس، إِلَّا أَن كتاب إِبْرَاهِيم بن"],[15,"سعد يبين إِذا كَانَ سَمَاعا، قَالَ: حَدثنِي، وَإِذا لم يكن قَالَ: قَالَ."],[16,"ثمَّ قَالَ: يَقُول قَالَ أَبُو الزِّنَاد، قَالَ فلَان، قَالَ: وَتنظر فِي كتاب يزِيد بن هَارُون عَن أبي الزِّنَاد كلهَا."],[17,"٢"],[18,"- وَقيل لَهُ: أَيّمَا أحب إِلَيْك مُوسَى بن عُبَيْدَة، أَو مُحَمَّد بن إِسْحَاق؟ فَقَالَ: مُحَمَّد بن إِسْحَاق."],[19,"٣"],[20,"- قَالَ: لَيْسَ أحد أثبت وَلَا أعرف بِحَدِيث ثَابت من حَمَّاد، ثمَّ"],[21,"قَالَ: وَسليمَان بن الْمُغيرَة، قلت: معمر؟ قَالَ: وَمعمر حسن الحَدِيث، عَن ثَابت."],[22,"٤"],[23,"- وَقَالَ: كَانَ ابْن أبي زَائِدَة، إِذا قَالَ: قَالَ ابْن جريج عَن فلَان، فَلم يسمعهُ، وَكَانَ يحدث عَن ابْن جريج، فَلَا يَجِيء بالألفاظ وَالْأَخْبَار، وَكَذَا كَانَ حَفْص بميزان يحيى، يَقُول: ابْن"],[24,"جريج سَمِعت أَبَا الزبير."],[25,"٥"],[26,"- وَسُئِلَ عَن عطاف بن خَالِد، فَقَالَ: لَيْسَ بِهِ بَأْس."],[27,"٦"],[28,"- وَسُئِلَ عَن يحيى بن حَمْزَة، فَقَالَ: لَيْسَ بِهِ بَأْس."],[29,"٧"],[30,"- سَأَلته. قلت: سمع ابْن عون من أنس شَيْئا؟ فَقَالَ: قد رَآهُ، وَأما سَماع فَلَا أعلم."],[31,"ثمَّ قَالَ: أَيُّوب قد رَآهُ، وَلم يسمع، قلت: وَيُونُس؟ قَالَ:"],[32,"لَا أَدْرِي."],[33,"٨"],[34,"- وَذُكِرَ حَدِيثُ سَالِمٍ، عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صلى الله عليه وآله وسلم، وَحَدِيثُ نَافِعٍ، عَنِ ابْنِ عُمَرَ، عَنْ عُمَرَ مَنْ بَاعَ عَبْدًا، قُلْتُ: فَأَيُّمَا الثَّبْتُ؟ فَتَبَسَّمَ، وَقَالَ: اللَّهُ أَعْلَمُ،"],[35,"قُلْتُ: مَا الَّذِي يُمِيلُ إِلَيْهِ قَلْبُكَ؟ قَالَ: أُرَى وَاللَّهُ أَعْلَمُ نَافِع"],[36,"٩"],[37,"- قلت: فَإِذا اخْتلف سَالم، وَنَافِع."],[38,"لمن تحكم؟ قَالَ: نَافِع."],[39,"قد قدم سالما على نَفسه، وَقد روى عَنهُ، وَكَانَ مشمرا، قلت: لم أرد الْفضل إِنَّمَا أردْت فِي الحَدِيث، إِذا اخْتلفَا، فقلبك إِلَى أَيهمَا أميل؟ قَالَ: جَمِيعًا عِنْدِي ثَبت، وَذهب إِلَى أَن لَا يقْضِي لأحد."],[40,"١٠"],[41,"- وَقَالَ: كَانَ يحيى الْقطَّان، وخَالِد بن الْحَارِث، ومعاذ بن معَاذ لَا يَكْتُبُونَ عِنْد شُعْبَة، كَانَ يحيى يحفظ، وَيذْهب إِلَى بَيته، فيكتبها، وَكَانَ فِي حَدِيثه بعض ترك الْأَخْبَار والألفاظ، وَكَانَ معَاذ يقْعد نَاحيَة فِي جَانب، فَيكْتب مَا حفظ، وَكَانَ فِي حَدِيثه شَيْء، وَكَانَ خَالِد أَيْضا يقْعد فِي نَاحيَة، فَيكْتب مَا حفظ لَا يَجْتَمعُونَ."],[42,"١١"],[43,"- وَسَأَلته عَن حَفْص الفرخ، فَقَالَ: لم أكتب عَنهُ، كَانَ يتتبع السُّلْطَان."],[44,"١٢"],[45,"- وَسَأَلته عَن سُلَيْمَان بن الحكم بن عوَانَة، فَقَالَ: هَذَا كَانَ ينزل ذَاك الْجَانِب، وَإِنَّمَا كَانَ عِنْده شَيْء، أَو قَالَ: لم أكتب عَنهُ شَيْئا."],[46,"١٣"],[47,"- وَقَالَ فِي مُحَمَّد بن حَمْزَة الْخُرَاسَانِي الَّذِي قَتله ابْن نهيك فِي الْأَمر بِالْمَعْرُوفِ لَا أعرفهُ."],[48,"١٤"],[49,"- وَقَالَ: أَبُو الْجمل اليمامي الَّذِي يروي، عَن يحيى بن أبي كثير لَا أَدْرِي كَيفَ هُوَ، أَو قَالَ: قَالَ لَا أعرفهُ."],[50,"١٥"],[51,"- قَالَ فِي أبي حَمَّاد الْحَنَفِيّ: اسْمه الْمفضل بن صَدَقَة، فَتكلم"],[52,"فِيهِ بِكَلَام ضَعِيف."],[53,"١٦"],[54,"- وَقَالَ لي: دَهْثَم بْن فَرّان اليمامي، ضُعَفة."],[55,"١٧"],[56,"- وَقَالَ فِي عَليّ بن حزور: فلينه."],[57,"١٨"],[58,"- وَقَالَ فِي مُسلم بن خَالِد الزنْجِي: فحرك يَده وَلينه."],[59,"١٩"],[60,"- وَقَالَ: عَليّ بن حَفْص أحب إِلَيّ من شَبابَة."],[61,"٢٠"],[62,"- وَذكر معمر، فَقَالَ: ذكر يَوْمًا حَدِيثا للثوري، فَأَخْطَأَ فِيهِ، فَقَالَ لَهُ سُفْيَان: نَعَست يَا أَبَا عُرْوَة؟ فَقَالَ لَهُ معمر كلَاما أكره أَن أحكيه، قلت: كَأَنَّهُ قَالَ لَهُ: كذبت، فَضَحِك."],[63,"٢١"],[64,"- وَذكر عباد، فَقَالَ حدث يَوْمًا بِحَدِيث، فَقَالَ: فُضَيْل بن يزِيد، وَإِنَّمَا هُوَ فُضَيْل بن زيد، فَرد عَلَيْهِ فَأبى، فجار."],[65,"٢٢"],[66,"- وَسَأَلته عَن أبي حَفْص الشَّامي، فَقَالَ: هَذَا كَانَت عِنْده"],[67,"أَحَادِيث كتبناها عَن سعيد بن عبد الْعَزِيز، ثمَّ تبين أمره بعد فَتَرَكُوهُ، حدث بِأَحَادِيث لسَعِيد بن أبي عرُوبَة."],[68,"٢٣"],[69,"- قلت: من أَصْحَاب أبي إِسْحَاق المتثبتون؟ قَالَ: شُعْبَة، وسُفْيَان."],[70,"٢٤"],[71,"- وَقَالَ: شريك حسن الرِّوَايَة عَن أبي إِسْحَاق."],[72,"٢٥"],[73,"- قلت: كَيفَ معمر فِي الحَدِيث؟ قَالَ: ثَبت إِلَّا أَن فِي بعضه حَدِيثه شَيْئا."],[74,"٢٦"],[75,"- وَقَالَ فِي ابْن وهب: كَانَ حَدِيثه بعضه سَماع، وَبَعضه عرض، وَبَعضه مناولة، وَكَانَ مَا لم يسمعهُ يَقُول: قَالَ حَيْوَة، قَالَ فلَان."],[76,"٢٧"],[77,"- وَقَالَ: قد رَأَيْت ابْن وهب وَلم أكتب عَنهُ، ثمَّ كتبت عَن رجل عَنهُ."],[78,"قَالَ وَأَخْبرنِي بعض أَصْحَابنَا أَنه رأى ابْن وهب عِنْد ابْن عُيَيْنَة، قفال لَهُ: الْكتب الَّتِي عرضهَا عَلَيْك ابْن أخي أرويها عَنْك؟"],[79,"ثمَّ قَالَ يحيى: أخبرنَا أَنه شهد بن وهب عِنْد ابْن عيينه."],[80,"٢٨"],[81,"- وَسَأَلت أَبَا عبد الله، عَن سُفْيَان بن حُسَيْن، فَقَالَ: لَيْسَ هُوَ بِذَاكَ، فِي حَدِيثه عَن الزُّهْرِيّ شَيْء."],[82,"٢٩"],[83,"- وَقَالَ: كَانَ خَالِد بن الْحَارِث يَجِيء بِالْحَدِيثِ كَمَا سمع، وَيَقُول يحيى: هَذَا أَو أشبه هَذَا، وَكَانَ ابْن مهْدي يَجِيء بِالْحَدِيثِ سمع، وَكَانَ وَكِيع يجْتَهد أَن يَجِيء بِالْحَدِيثِ كَمَا سمع، فَكَانَ رُبمَا قَالَ فِي الْحَرْف أَو الشَّيْء: يَعْنِي كَذَا."],[84,"٣٠"],[85,"- وَقَالَ: التَّدْلِيس من الرِّيبَة."],[86,"٣١"],[87,"- وَذكر هشيما، فَقَالَ: كَانَ يُدَلس تدليسا وحشا، وَرُبمَا جَاءَ بالحرف الَّذِي لم يسمعهُ، فيذكره فِي حَدِيث آخر، إِذا انْقَطع الْكَلَام يوصله."],[88,"٣٢"],[89,"- وسمعته يَقُول: معَاذ بن معَاذ قُرَّة عين فِي الحَدِيث."],[90,"٣٣"],[91,"- قيل لَهُ: عَطاء بن السَّائِب أحب إِلَيْك أَو حُصَيْن؟ فَقَالَ: كِلَاهُمَا ثبتان."],[92,"٣٤"],[93,"- وسمعته يَقُول: كَانَ يحيى بن سعيد يحمل على همام حَتَّى قدم"],[94,"٣٦"],[95,"- قَالَ أَبُو عبد الله: كَانَ شُعْبَة يتشدد فِي التَّدْلِيس."],[96,"٣٧"],[97,"- قيل لَهُ سمع أَيُّوب من الزُّهْرِيّ؟ قَالَ: نعم."],[98,"٣٨"],[99,"- وَسُئِلَ أَيهمَا أثبت، بهز أَو سُلَيْمَان بن حَرْب؟ فَقَالَ: بهز أثبت."],[100,"أَيْن يُقَاس سُلَيْمَان إِلَى بهز."],[101,"٣٩"],[102,"- وَسُئِلَ عَن عِيسَى بن يُونُس، وَأبي إِسْحَاق الْفَزارِيّ، ومروان بن مُعَاوِيَة، أَيهمْ أثبت؟ قَالَ: مَا فيهم إِلَّا ثَبت."],[103,"قيل لَهُ:"],[104,"فَمن تقدم؟ قَالَ: مَا فيهم إِلَّا ثِقَة، ثَبت، إِلَّا أَن أَبَا إِسْحَاق ومكانه من الْإِسْلَام."],[105,"٤٠"],[106,"- وَسُئِلَ عَن شُعْبَة، عَن أبي إِسْحَاق، عَن عمر بن أبي حُسَيْن."],[107,"قَالَ: لَيْسَ هُوَ عمر، كَانَ شُعْبَة يقلب أسامي الرِّجَال."],[108,"٤١"],[109,"- وَسُئِلَ عَن عمر بن هَارُون الْبَلْخِي."],[110,"فَقَالَ: مَا أقدر أَن أتعلق عَلَيْهِ بِشَيْء، كتبت عَنهُ حَدِيثا كثيرا، فَقيل لَهُ: قد كَانَت لَهُ قصَّة مَعَ ابْن مهْدي، قَالَ: بَلغنِي أَن عبد الرَّحْمَن، كَانَ يحمل عَلَيْهِ وَلَا أَدْرِي مَا كَانَت قصَّته؟ فَقَالَ لَهُ أَبُو جَعْفَر: إِنِّي سَمِعت من يَحْكِي عَن ابْن مهْدي، أَنه قدم عَلَيْهِم عمر بن هَارُون الْبَصْرَة، وَهُوَ شَاب، فذاكره عبد الرَّحْمَن، فَكتب عَنهُ ثَلَاثَة أَحَادِيث مِنْهَا:"],[111,"حَدِيث عَن يحيى بن أبي عَمْرو السيباني، عَن عَمْرو بن عبد الله الْحَضْرَمِيّ، عَن عبد الله بن عَمْرو فِي شرب الْعصير."],[112,"وَمِنْهَا: عَن عبد الْملك، عَن عَطاء فِي الحفار ينسى الفأس فِي الْقَبْر بعد مَا يفرغ مِنْهُ."],[113,"وَحَدِيث آخر، فَلَمَّا كَانَ بعد زمَان قدم عَلَيْهِم الْبَصْرَة، فَأتى رجل عبد الرَّحْمَن، فَقَالَ: إِنَّك كتبت عَن هَذَا شَيْئا؟، فَأعْطَاهُ الرقعة، فَذهب بهَا إِلَيْهِ، فَسَأَلَهُ عَن حَدِيث يحيى بن أبي عَمْرو، فَقَالَ: لم أسمع من يحيى بن أبي عَمْرو شَيْئا، إِنَّمَا كَانَ هَذَا مني فِي الحداثة."],[114,"وَسَأَلَهُ عَن حَدِيث عبد الْملك، فَقَالَ: لم أسمع من عبد الْملك، إِنَّمَا حَدَّثَنِيهِ فلَان، عَن عبد الْملك، فَأتى ابْن مهْدي، فَأخْبرهُ، فنال"],[115,"مِنْهُ وَتكلم، فَقَالَ أَبُو عبد الله: كَانَ أَكثر مَا يحدثنا عَن ابْن جريج، ويروى عَن الْأَوْزَاعِيّ، قيل لَهُ: فتروي عَنهُ؟ قَالَ: قد كنت رويت عَنهُ شَيْئا."],[116,"٤٢"],[117,"- وَقَالَ: قدم هَهُنَا رجل حَدثهمْ، عَن سُفْيَان بِحَدِيث، فألقوه على عبد الرَّحْمَن، فَقَالَ: هَذَا كذب، لَيْسَ من هَذَا بِشَيْء، فأنكروه عَلَيْهِ، فاستغاث بوكيع، فَكَتَبُوا إِلَيْهِ، فَإِذا الحَدِيث بَاطِل."],[118,"٤٣"],[119,"- وَقيل لَهُ: عبيد الله أثبت أَو مَالك فِي نَافِع؟ قَالَ: لَيْسَ أحد أثبت فِي نَافِع من عبيد الله."],[120,"٤٤"],[121,"- سُئِلَ عَن عقيل، وَيُونُس، فَقَالَ: عقيل، وَذَاكَ"],[122,"أَن يُونُس رُبمَا رفع الشَّيْء من رَأْي الزُّهْرِيّ، يصيره عَن ابْن الْمسيب، وَقَالَ: قد روى يُونُس، عَن عقيل."],[123,"٤٥"],[124,"- وَسُئِلَ أَبُو عبد الله عَن شُعَيْب."],[125,"فَقَالَ: مَا فيهم إِلَّا ثِقَة، وَجعل يَقُول: تَدْرِي من الثِّقَة؟ إِنَّمَا الثِّقَة يحيى الْقطَّان، تَدْرِي من الْحجَّة؟ شُعْبَة، وسُفْيَان حجَّة، وَمَالك حجَّة، قلت: وَيحيى؟ قَالَ: يحيى، وَعبد الرَّحْمَن، وَأَبُو نعيم الْحجَّة."],[126,"الثبت،"],[127,"كَانَ أَبُو نعيم ثبتا."],[128,"٤٦"],[129,"- وَذكر عَبدة بن سُلَيْمَان، فَقَالَ: كَانَ من خِيَار الْمُسلمين كَانَ رِوَايَة عَن سعيد، جِئْنَا، وَإِن عِنْده غُلَاما حَدثا يحدثه، فَكَانَ يَقُول للغلام: اقْرَأ عَليّ، فَإِذا أَخطَأ قَالَ لَهُ عَبدة: أعده حَتَّى أملي عَلَيْك."],[130,"٤٧"],[131,"- وَقَالَ: قد كَانَ ابْن بشر جيد الْكتاب، عَن سعيد، سماعهم مُتَقَدم، قلت: سعيد اخْتَلَط؟ قَالَ: نعم."],[132,"أما يحيى فَكَانَ يَقُول: من سمع قبل سنة خمس وَأَرْبَعين، وَأما عبد الْوَهَّاب فقد كَانَ خولط، يَعْنِي قبل سَمَاعه."],[133,"٤٨"],[134,"- قلت: عبد الْوَهَّاب ثِقَة؟ قَالَ: تَدْرِي من الثِّقَة؟ الثِّقَة يحيى الْقطَّان."],[135,"٤٩"],[136,"- سَأَلته عَن خلاس، فَقَالَ: مَا روى عَن غير عَليّ، فَلم ير بِهِ بَأْسا، وَأما مَا روى عَن عَليّ، فَلَيْسَ هِيَ عِنْدِي."],[137,"٥٠"],[138,"- سَأَلته عَن قَتَادَة سمع من خلاس؟ قَالَ: نعم."],[139,"٥١"],[140,"- سَأَلته عَن أبي عبد الله الجدلي، فَقَالَ قولا لينًا."],[141,"٥٢"],[142,"- قلت: من أَصْحَاب الثَّوْريّ؟ قَالَ: يحيى، ووكيع، وَعبد الرَّحْمَن، وَأَبُو نعيم."],[143,"قلت: قدمت وكيعا على عبد الرَّحْمَن؟ قَالَ: وَكِيع شيخ."],[144,"٥٣"],[145,"- قلت: يحيى بن يمَان، ومؤمل إِذا اخْتلفَا؟ قَالَ: دع ذَا، كَأَنَّهُ لين أَمرهمَا، ثمَّ قَالَ: مُؤَمل كَانَ يُخطئ."],[146,"٥٤"],[147,"- سَأَلته عَن مجَالد بن سعيد، كَيفَ هُوَ؟ فَقَالَ: كَذَا وَكَذَا، وَقَالَ: روى عَنهُ يحيى، قلت: يحْتَج بِهِ؟ فَتكلم بِكَلَام لين."],[148,"٥٥"],[149,"- سَأَلته عَن مُحَمَّد بن إِسْحَاق، كَيفَ هُوَ؟ فَقَالَ: هُوَ حسن الحَدِيث، وَلكنه إِذا جمع عَن رجلَيْنِ، قلت كَيفَ؟ قَالَ: يحدث عَن الزُّهْرِيّ، وَرجل آخر، فَيحمل حَدِيث هَذَا على هَذَا، ثمَّ قَالَ: قَالَ يَعْقُوب سَمِعت أبي، يَقُول: سَمِعت الْمَغَازِي مِنْهُ ثَلَاث مَرَّات ينقضها ويغيرها."],[150,"٥٦"],[151,"- وَقَالَ: قَالَ مَالك، وَذكره، فَقَالَ: دجال من الدجاجلة."],[152,"٥٧"],[153,"- وَقَالَ أَبُو عبد الله: قدم مُحَمَّد بن إِسْحَاق إِلَى بَغْدَاد، فَكَانَ لَا يُبَالِي عَمَّن يَحْكِي، عَن الْكَلْبِيّ، وَغَيره."],[154,"٥٨"],[155,"- سَأَلته عَن مُحَمَّد بن عَمْرو، فَقَالَ: قد روى عَنهُ يحيى، وَرُبمَا رفع"],[156,"أَحَادِيث يوقفها غَيره، وَهَذَا من قبله، قَالَ: وَقدم على الْأَعْمَش، فَلم يُكرمهُ."],[157,"٥٩"],[158,"- سَأَلته عَن ثَابت، وَحميد أَيهمَا أثبت فِي أنس؟ فَقَالَ: ثَابت، وَقَالَ: كَانَ حميد يذهب مَعَ ثَابت إِلَى الحَدِيث، وَلَقَد قَالَ أنس: إِن ثَابتا دويبة أحبها."],[159,"٦٠"],[160,"- وَسَأَلته عَن ابْن أبي ذِئْب، كَيفَ هُوَ؟ قَالَ: ثِقَة، قلت فِي الزُّهْرِيّ؟ قَالَ: كَذَا وَكَذَا."],[161,"حدث بِأَحَادِيث كَأَنَّهُ أَرَادَ"],[162,"خُولِفَ."],[163,"٦١"],[164,"- قلت لأبي عبد الله: فعبد الرَّحْمَن بن إِسْحَاق، كَيفَ هُوَ؟ قَالَ: أما مَا كتبنَا من حَدِيثه، فقد حدث عَن الزُّهْرِيّ بِأَحَادِيث، كَأَنَّهُ أَرَادَ تفرد بهَا، ثمَّ ذكر حَدِيث مُحَمَّد بن جُبَير فِي الْحلف."],[165,"حلف المطيبين، فَأنكرهُ أَبُو عبد الله، وَقَالَ: مَا رَوَاهُ غَيره."],[166,"٦٣"],[167,"- وَقلت لأبي عبد الله فِي سعد بن إِبْرَاهِيم: إِن مَالِكًا لم يرو عَنهُ، فكره أَبُو عبد الله مَا قلت، وَقَالَ: قد كَانَ سُفْيَان، يَقُول: إِن سَعْدا سعد، وَقَالَ: قَالَ الزُّهْرِيّ: من لَهُ أَب مثل سعد؟ وَذكر"],[168,"من فَضله، وَقَالَ: كَانَ يَأْمر بِالْمَعْرُوفِ، وَلَقَد احْتَاجَ فَدخل فِي الْقَضَاء، فَلَمَّا عزل كَانَ يهاب مثله، وَهُوَ قَاض."],[169,"قلت: فقد روى مَالك، عَن إِدْرِيس، عَن شُعْبَة، عَن سعد؟ فَقَالَ: نعم، وَعجب."],[170,"وَقَالَ: كَانَ مَالك ينْتَقد الرِّجَال."],[171,"٦٣"],[172,"- سَأَلته عَن السّديّ، فَقَالَ: لَيْسَ بِهِ بَأْس."],[173,"هُوَ عِنْدِي ثِقَة، إِلَّا أَن عبد الرَّحْمَن بن مهْدي، قَالَ: قَالَ لي شُعْبَة فِي حَدِيث حدث بِهِ عَن السّديّ: رَفعه وَأَنا لَا أرفعه، قَالَ ابْن مهْدي: قلت إِن إِسْرَائِيل حدث بِهِ مَرْفُوعا، فَأَوْمأ شُعْبَة بِرَأْسِهِ، أَي نعم."],[174,"٦٤"],[175,"- سَأَلت أَبَا عبد الله، عَن مطر الْوراق، فَقَالَ فِيهِ قولا لينًا، وَقَالَ: هُوَ مثل ابْن أبي ليلى."],[176,"٦٥"],[177,"- سَأَلت أَبَا عبد الله، عَن مُوسَى الْجُهَنِيّ، فَقَالَ: لَيْسَ بِهِ بَأْس، وَأحسن القَوْل فِيهِ."],[178,"٦٦"],[179,"- سَأَلت أَبَا عبد الله، عَن عَليّ بن الْمُبَارك، فَقَالَ: لَيْسَ بِهِ بَأْس،"],[180,"ثمَّ قَالَ: قد كَانَ يَرْمِي بالتشيع."],[181,"٦٧"],[182,"- سَأَلت أَبَا عبد الله، عَن أبي الزبير، فَقَالَ: قد روى عَنهُ قوم وَاحْتَمَلُوهُ، روى عَنهُ أَيُّوب، وَغير وَاحِد، إِلَّا أَن شُعْبَة لم يحدث عَنهُ، قلت: هُوَ لين الحَدِيث؟ فَكَأَنَّهُ لينه."],[183,"قلت: أَبُو الزبير أحب إِلَيْك أَو أَبُو نَضرة؟ قَالَ: أَبُو نَضرة أحب إِلَيّ."],[184,"٦٨"],[185,"- سَأَلته عَن جَعْفَر بن مُحَمَّد، فَقَالَ: قد روى عنته يحيى، وَلينه."],[186,"٦٩"],[187,"- سَأَلت أَبَا عبد الله، عَن صَالح مولى التوءمة، فَقَالَ قَالَ مَالك: قد رَأَيْته مختلطا، وَلم يحمل عَنهُ، ثمَّ قَالَ: من سمع مِنْهُ قبل الِاخْتِلَاط، فَكَأَنَّهُ."],[188,"٧٠"],[189,"- سَأَلت أَبَا عبد الله، عَن النَّضر بن عَرَبِيّ، فَقَالَ: لَيْسَ بِهِ بَأْس."],[190,"٧١"],[191,"- سَأَلت أَبَا عبد الله، عَن الْوَازِع بن نَافِع، فَقَالَ لَا أَدْرِي كَيفَ هُوَ؟ كَأَنَّهُ ضعفه."],[192,"٧٢"],[193,"- سَأَلته عَن معقل بن عبيد الله، فَقَالَ: ثِقَة."],[194,"٧٣"],[195,"- سَأَلت أَبَا عبد الله، عَن عَاصِم الْأَحْوَال، فَقَالَ: ثِقَة، قلت: إِن يحيى بن معِين تكلم فِيهِ، فَعجب، وَقَالَ: ثِقَة."],[196,"٧٤"],[197,"- سَأَلت أَبَا عبد الله، عَن عَاصِم بن أبي النجُود، فَقَالَ: هُوَ أستاذ أبي بكر بن عَيَّاش، لَيْسَ بِهِ بَأْس، وَكَأَنَّهُ لينه."],[198,"٧٥"],[199,"- وَسَأَلت عَن جَابر الْجعْفِيّ، فَقَالَ: قد كنت لَا أكتب حَدِيثه، ثمَّ كتبت أعتبر بِهِ."],[200,"٧٦"],[201,"- سَأَلت أَبَا عبد الله، عَن ابْن لَهِيعَة، فلين أمره، وَقَالَ: من سمع مِنْهُ مُتَقَدما."],[202,"٧٧"],[203,"- سَأَلته عَن مُحَمَّد بن عبد الله بن أبي يَعْقُوب، فَقَالَ: ثِقَة."],[204,"٧٨"],[205,"- سَأَلته عَن هِشَام بن حسان، فَقَالَ: أَيُّوب، وَابْن عون أحب إِلَيّ، وَحسن أَمر هِشَام، وَقَالَ: قد روى أَحَادِيث رَفعهَا أوقفوها، وَقد كَانَ مَذْهَبهم أَن يقصروا بِالْحَدِيثِ ويوقفوه."],[206,"٧٩"],[207,"- سَأَلت أَبَا عبد الله، عَن مبارك بن فضَالة، وَأبي هِلَال، فَقَالَ: هما متقاربان، لَيْسَ فيهمَا بِذَاكَ، وَقد كنت لَا أخرج عَن مبارك شَيْئا، ثمَّ بعد."],[208,"٨٠"],[209,"- سَأَلْتُهُ عَن أَبِي الْأَشْهب، فَقَالَ لَا يُخْتَلَف فِيهِ، إِنَّه ثِقةٌ."],[210,"٨١"],[211,"- سَأَلته عَن جرير بن حَازِم، فَقَالَ: فِي بعض حَدِيثه شَيْء، وَلَيْسَ بِهِ بَأْس."],[212,"٨٢"],[213,"- سَأَلته عَن يزِيد النَّحْوِيّ."],[214,"فَقَالَ: كَذَا وَكَذَا."],[215,"٨٣"],[216,"- سَأَلته عَن فرقد السبخي، فَقَالَ: رجل صَالح، وَحَدِيثه لَيْسَ بِذَاكَ."],[217,"٨٤"],[218,"- وَسَأَلته عَن الْمُغيرَة بن زِيَاد الْموصِلِي، فلين أمره."],[219,"٨٥"],[220,"- وَسَأَلته عَن إِبْرَاهِيم بن مهَاجر، فلين أمره."],[221,"٨٦"],[222,"- سمعته يَقُول: تكلم يحيى بن معِين، وَيحيى بِحَضْرَة عبد الرَّحْمَن بن مهْدي، فَقَالَ يحيى: إِبْرَاهِيم بن مهَاجر، وَذكر رجلا آخر ضعيفين مهينين، فَحمل عَلَيْهِ عبد الرَّحْمَن حملا شَدِيدا، وَجعل أَبُو عبد الله يعجب من هَذَا الْكَلَام، وَيَقُول: مهينين."],[223,"٨٧"],[224,"- وَقلت لَهُ: إِنِّي سَأَلت يحيى بن معِين، عَن الصَّائِم يحتجم، قَالَ: لَا شَيْء عَلَيْهِ، لَيْسَ يثبت فِيهَا خبر."],[225,"قَالَ أَبُو عبد الله: هَذَا كَلَام مجازفة."],[226,"٨٨"],[227,"- وَقَالَ: يزِيد الرقاشِي لَيْسَ مِمَّن يحْتَج بِهِ."],[228,"٨٩"],[229,"- وَقَالَ: أَشْعَث بن طلق، الَّذِي روى عَن ابْن عمر، تكلم فِيهِ بِكَلَام لين."],[230,"٩٠"],[231,"- وَقَالَ: فِي مُوسَى بن دهقان، فلين أمره."],[232,"٩١"],[233,"- وَقَالَ فِي أبي داد: نفيع، فلين أمره."],[234,"٩٢"],[235,"- وَقَالَ فِي الْخَزْرَج بن عُثْمَان السَّعْدِيّ، فَقَالَ: هَذَا ثِقَة."],[236,"٩٣"],[237,"- وَقَالَ فِي أبي عُبَيْدَة النَّاجِي، فضعف أمره."],[238,"٩٤"],[239,"- وَقَالَ فِي خصيب بن جحدر: مَتْرُوك الحَدِيث."],[240,"٩٥"],[241,"- وَقَالَ فِي أبي بكر الْهُذلِيّ، ضعف أمره."],[242,"٩٦"],[243,"- وَذكر الرّبيع بن صبيح، فَتكلم فِيهِ بِكَلَام لين."],[244,"٩٧"],[245,"- وَقَالَ فِي السّديّ، وَابْن مهَاجر: ثقتان، ثمَّ قَالَ: مَنْصُور"],[246,"، وَأَيوب أثبت مِنْهُمَا."],[247,"٩٨"],[248,"- سَأَلته عَن قطن، الَّذِي روى عَنهُ مُغيرَة، فَقَالَ لَا أعرفهُ، إِلَّا بِمَا روى عَنهُ مُغيرَة، قلت: إِن جَرِيرًا ذكره بِذكر سوء، قَالَ: لَا أَدْرِي، جَرِيرًا أعرف بِهِ وببلده."],[249,"٩٩"],[250,"- وَذكر عَامر بن شَقِيق، الَّذِي روى عَن أبي وَائِل، فَتكلم فِيهِ بِشَيْء."],[251,"١٠٠"],[252,"- وَقَالَ فِي ركين الضَّبِّيّ حَدثنَا عَنهُ أَبُو نعيم، وَلم يرضه."],[253,"وَقَالَ: قد روى عَنهُ الثَّوْريّ ثَلَاثَة أَحَادِيث."],[254,"١٠١"],[255,"- قلت: الْهَيْثَم الَّذِي روى عَنهُ مُغيرَة؟ قَالَ: لَا أعرفهُ، إِلَّا بِمَا روى عَنهُ مُغيرَة."],[256,"١٠٢"],[257,"- وَذكر عمر بن يعلى، فَلم يرضه."],[258,"وَقَالَ إِسْمَاعِيل بن سميع، لَيْسَ بِهِ بَأْس."],[259,"١٠٣"],[260,"- وَقَالَ: سلم بن عبد الرَّحْمَن، لَيْسَ هُوَ أَخُو حُصَيْن، وَلَيْسَ بِهِ بَأْس."],[261,"١٠٤"],[262,"- وَذكر عمَارَة بن الْقَعْقَاع، فَقَالَ: ثِقَة."],[263,"١٠٥"],[264,"- وَقَالَ: حبيب بن أبي عمْرَة، ثِقَة."],[265,"١٠٦"],[266,"- وَذكر عبد الله بن سعيد بن جُبَير، فَقَالَ: قد روى عَنهُ أَيُّوب، وَلَيْسَ بِهِ بَأْس."],[267,"١٠٧"],[268,"- وَذكر سُهَيْل بن أبي صَالح، فَقَالَ: لَيْسَ بِهِ بَأْس."],[269,"١٠٨"],[270,"- وَذكر يُونُس بن خباب، فَتكلم فِيهِ، وَلم يرضه، وَقَالَ: هَذَا"],[271,"كَانَ يَقع فِي عُثْمَان."],[272,"١٠٩"],[273,"- حَدثنَا أَبُو عوَانَة، قَالَ: سَمِعت على بن عبد الْعَزِيز، يَقُول: حَدثنَا إِبْرَاهِيم بن زِيَاد سبلان، قَالَ: سَمِعت عباد بن عباد،"],[274,"يَقُول: أتيت يَوْمًا يُونُس بن خباب بمنى، فَسَأَلته عَن حَدِيث الْقَبْر، فَحَدثني بِهِ، وَقَالَ فِيهِ شَيْء كتمته المرجئة، وَحَتَّى سُئِلَ عَن عَليّ."],[275,"١١٠"],[276,"- سَأَلته عَن همام بن مُنَبّه، فَقَالَ: ثِقَة."],[277,"١١١"],[278,"- وَقَالَ: يحيى بن سعيد بن سعيد، وَسعد بن سعيد، فضعف سَعْدا."],[279,"١١٢"],[280,"- وَسَأَلته عَن النُّعْمَان بن رَاشد، فَقَالَ: هُوَ جزري، لَيْسَ بِذَاكَ."],[281,"١١٣"],[282,"- سُئِلَ عَن عبد الله بن سعيد بن أبي سعيد، فَقَالَ: لَيْسَ هُوَ بِذَاكَ، وَقد روى عَنهُ سُفْيَان."],[283,"١١٤"],[284,"- وَسَأَلْتُهُ عَنْ عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ شَيْخٍ، رَوَى عَنْ عَطَاءٍ، عَنِ ابْنِ عَبَّاسٍ قَالَ: هَدَايَا الأُمَرَاءِ غُلُولٌ، قَالَ: لَا أَعْرِفُهُ، قُلْتُ: فَعُبَيْدُ اللَّهِ بْنُ أَبِي جَعْفَرٍ، قَالَ: كَانَ يُقَالُ: إِنَّهُ حَسَنُ الْفِقْهِ مِنْ أَهْلِ الْمَدِينَةِ، قُلْتُ: كَيْفَ هُوَ فِي الْحَدِيثِ؟ قَالَ: هَا"],[285,"١١٥"],[286,"- وَذكر ابْن سمْعَان، فَقَالَ: كَانَ مَتْرُوك الحَدِيث."],[287,"وَسُئِلَ عَن ابْن سمْعَان، فَقَالَ سَمِعت إِبْرَاهِيم بن سعد يحلف أَنه كَذَّاب، قَالَ: وَكَانَ يَقُول: سَمِعت مُجَاهدًا، فَيَقُول ابْن إِسْحَاق: أَنا وَالله أكبر مِنْهُ، وَمَا سَمِعت مِنْهُ."],[288,"١١٦"],[289,"- وَسُئِلَ عَن مُحَمَّد بن عَمْرو والْعَلَاء، فَقَالَ الْعَلَاء أحب إِلَيّ"],[290,"، وَذَاكَ أَن مُحَمَّد بن عَمْرو رُبمَا قَالَ الأشباح."],[291,"١١٧"],[292,"- وَسُئِلَ عَن خَارِجَة بن مُصعب، فضعفه، وَقَالَ: مَا روى عَنهُ ابْن الْمُبَارك شَيْئا فِي كتبه، فَقَالَ لَهُ ابْن أبي رزمة: بلَى، حَدِيث وَاحِد، وَقَالَ: قد قَالُوا لِابْنِ الْمُبَارك فِيهِ، فَقَالَ: كَيفَ أحدث عَن رجل حدث نكد الحَدِيث مُنكر؟"],[293,"١١٨"],[294,"- وَسَأَلته عَن زيد بن أبي أنيسَة، كَيفَ هُوَ؟ فحرك يَده وَقَالَ: صَالح، وَلَيْسَ هُوَ بذلك."],[295,"١٢٠"],[296,"- وَقَالَ لي أَبُو عبد الله: عَاصِم بن عبيد الله، كَانَ الشُّيُوخ يهابون حَدِيثه."],[297,"١٢١"],[298,"- سَأَلته عَن أبي حَمْزَة الْعَطَّار، فَقَالَ لَا أَدْرِي كَيفَ هُوَ؟"],[299,"١٢٢"],[300,"- سَأَلته عَن حَكِيم بن جُبَير، فَقَالَ: لَيْسَ بِذَاكَ."],[301,"١٢٣"],[302,"- سَأَلت أَبَا عبد الله، عَن عَمْرو بن عبد الله، الَّذِي روى عَن ٣ عِكْرِمَة، فَقَالَ: هَذَا يُقَال لَهُ: عَمْرو برق، كَانَ عِكْرِمَة نزل على أَبِيه، وَكَانَ سمع مِنْهُ كتابا، وَكَانَ أهل الْيمن لَا يرضونه، وَأَشَارَ أَبُو عبد الله بِيَدِهِ، أَي كَانَ يشرب، وَتَبَسم، وَكَانَ معمر يحدث عَنهُ، وَيَقُول عَن رجل لَا يُسَمِّيه، إِلَّا لِابْنِ الْمُبَارك، فَإِنَّهُ سَمَّاهُ قَالَ: برق."],[303,"١٢٤"],[304,"- وَذكر عبد الله الْعمريّ."],[305,"فَلم يرضه، وَقَالَ: لين الحَدِيث."],[306,"١٢٥"],[307,"- وَقَالَ فِي عَليّ بن عَليّ الرِّفَاعِي: لم يكن بِهَذَا الشَّيْخ بَأْس، إِلَّا أَنه رفع أَحَادِيث."],[308,"١٢٦"],[309,"- وَذكر مُحَمَّد بن أبي حَفْصَة، فَلم يرضه، وَأرَاهُ ذكر أَن لَهُ رَأْي سوء."],[310,"١٢٧"],[311,"- وَذكر جَعْفَر بن مَيْمُون، فَلم يرضه."],[312,"١٢٨"],[313,"- وَذكر حَمَّاد بن أبي سُلَيْمَان، فَقَالَ: ثِقَة."],[314,"١٢٩"],[315,"- وَذكر أَبَا الرّبيع السمان، فَقَالَ: لَيْسَ حَدِيثه بِشَيْء."],[316,"١٣٠"],[317,"- وَقَالَ: صَالح بن أبي الْأَخْضَر، لم يرضه، وَقَالَ: كَانَ يحيى لَا يحدث عَنهُ، وَقَالَ أَبُو عبد الله: حَدثهمْ بِأَحَادِيث، ثمَّ قَالَ:"],[318,"لم أسمعها."],[319,"١٣١"],[320,"- وَقَالَ: عبد الْملك بن عُمَيْر فِي حَدِيثه اضْطِرَاب."],[321,"١٣٢"],[322,"- وَقَالَ: قيس بن سعد ثِقَة."],[323,"١٣٣"],[324,"- وَقَالَ: أَبُو معشر، وَلم يرضه، وَيتَكَلَّم فِيهِ بِشَيْء."],[325,"١٣٤"],[326,"- وَسَأَلته عَن سَالم بن أبي حَفْصَة، فَقَالَ: لَيْسَ بِهِ بَأْس، إِلَّا أَنه كَانَ شِيعِيًّا."],[327,"١٣٥"],[328,"- وَقَالَ أَبُو عبد الله: أَبُو مَرْيَم مَتْرُوك الحَدِيث، وَقد كَانَ"],[329,"يَرْمِي بالتشيع، وَقد كتب عَنهُ شُعْبَة."],[330,"كَانَ يعرفهُ الشبيبة."],[331,"قَدِيما."],[332,"قَالَ شُعْبَة قَالَ أَبُو مَرْيَم لرجل حَدثَك يحيى بن، وثاب أَن مسروقا حَدثهمْ، أَن عبد الله حَدثهمْ؟ قَالَ: أَبُو مَرْيَم، وَلَو يَقُول لَهُ أحد: من حَدثَك أم كَيفَ سَمِعت؟ للطم عينه."],[333,"١٣٦"],[334,"- سَأَلته عَن الْمُغيرَة بن النُّعْمَان، فَقَالَ: هُوَ كَذَا وَكَذَا."],[335,"١٣٧"],[336,"- سَأَلت أَبَا عبد الله، عَن لَيْث بن أبي سليم، فَقَالَ: لَيْسَ هُوَ بِذَاكَ."],[337,"١٣٨"],[338,"- سَأَلته عَن الضَّحَّاك بن يسَار سمع من أبي عُثْمَان؟ قَالَ: لَا أَدْرِي، وَتكلم فِيهِ بِكَلَام لين."],[339,"١٣٩"],[340,"- سَأَلته عَن أبي بكر بن أبي سُبْرَة قَالَ: روى عَنهُ ابْن جريج، قَالَ حجاج قَالَ: عِنْدِي سَبْعُونَ ألفا فِي الْحَلَال وَالْحرَام."],[341,"١٤٠"],[342,"- قَالَ أَبُو عَبْدِ اللَّهِ: كُنَّا عِنْدَ إِسْمَاعِيلَ، فَذُكِرَ لَهُ حَدِيثُ مُحَمَّدِ بْنِ إِسْحَاقَ، عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قُلْتُ: \" يَا رَسُولَ اللَّهِ، أَكْتُبُ عَنْكَ مَا أَسْمَعُ؟ قَالَ: نَعَمْ \"، قُلْتُ: فِي الْغَضَبِ وَالرِّضَا؟، فَسَمِعْتُ إِسْمَاعِيلَ، يَقُولُ: أَعُوذُ بِاللَّهِ مِنَ الْكَذِبِ"],[343,"فَقلت: كَيفَ كَانَ حَال عَمْرو بن شُعَيْب عِنْد إِسْمَاعِيل، لم يكن يرضاه؟ قَالَ: قد روى عَنهُ، وَلَكِن كَانَ مَذْهَب مُحَمَّد بن سِيرِين، وَأَيوب، وَابْن عون، أَلا يكتبوا."],[344,"١٤١"],[345,"- قلت: سمع يحيى من عمر بن عَامر شَيْئا؟ قَالَ: لَا أعلم أَنه حدث عَنهُ بِشَيْء."],[346,"١٤٢"],[347,"- سَأَلته من أكبر، مَنْصُور بن الْمُعْتَمِر أَو ابْن زَاذَان؟ قَالَ: لَا أَدْرِي."],[348,"١٤٣"],[349,"- وَذكر جرير بن حَازِم، فَقَالَ: كَانَ حَافِظًا، وَقَالَ مرّة فِي بعض حَدِيثه شَيْء."],[350,"١٤٤"],[351,"- وَقَالَ أَبُو عبد الله، سَمِعت إِبْرَاهِيم بن سعد يحلف بِاللَّه، أَن ابْن سمْعَان كَذَّاب."],[352,"١٤٥"],[353,"- وَقَالَ فِي إِسْحَاق بن يحيى بن طَلْحَة: لَيْسَ حَدِيثه بِشَيْء."],[354,"١٤٦"],[355,"- وَذكر حُسَيْن بن وَاقد، فَقَالَ: لَيْسَ بِذَاكَ."],[356,"١٤٧"],[357,"- وَسُئِلَ عَن عَليّ بن غراب، فَقَالَ، كَانَ حَدِيثه، حَدِيث أهل الصدْق."],[358,"١٤٨"],[359,"- قلت لَهُ: سعيد بن عبد الْجَبَّار مكي؟ قَالَ: لَا هَذَا من أهل الشَّام، حَدثنَا أَبُو بدر عَنهُ بحديثين، وَقد ضربت عَلَيْهِمَا، قلت: وإيش حَاله؟ قَالَ: حدث بِأَحَادِيث مَنَاكِير."],[360,"١٤٩"],[361,"- سَأَلته عَن عسل بن سُفْيَان، فلين أمره."],[362,"١٥٠"],[363,"- سَأَلته عَن بشر بن حَرْب، فَقَالَ: نَحن صِيَام وَضَعفه."],[364,"١٥١"],[365,"- سَأَلته عَن دَاوُد بن يزِيد الأودي، فَقَالَ هَذَا الزعافري وَهُوَ عَم ابْن إِدْرِيس، سَأَلُوهُ عَن حَدِيث الشّعبِيّ لَا يكون الْمهْر أقل من عشرَة، فَلم يعرفهُ، فَسَأَلَهُ شريك فلقنه، فَحدث بِهِ وَضَعفه."],[366,"١٥٢"],[367,"- وَسَأَلته عَن أَزْهَر بن سِنَان، فلينه، وَقَالَ: حدث بِحَدِيث ذكره فِي الطَّلَاق."],[368,"١٥٣"],[369,"- سَأَلته عَن عبد الله بن ميسرَة، الَّذِي حدث عَنهُ يزِيد بن هَارُون، فلينه، وَقَالَ: نَحن نروي عَنهُ."],[370,"١٥٤"],[371,"- وَسَأَلته عَن دَاوُد بن فَرَاهِيجَ، فَقَالَ: هَذَا مديني، ولين أمره."],[372,"١٥٥"],[373,"- سَأَلته عَن أبي عَامر الخزاز، فَقَالَ: قد روى عَنهُ ولين أمره."],[374,"١٥٦"],[375,"- سَأَلته عَن عباد بن صُهَيْب، فَقَالَ: كَانَ يَرْمِي بِالْقدرِ، وَكَانَ أمره قَرِيبا من أبي عَامر الخزاز."],[376,"١٥٧"],[377,"- سَأَلته عَن الزبير بن سعيد، فلين أمره."],[378,"١٥٨"],[379,"- سَأَلته عَن عِيسَى بن الْمسيب، فَقَالَ: هَذَا كُوفِي وَلينه."],[380,"١٥٩"],[381,"- سَأَلته عَن أبي دَاوُد نفيع، وَعَن أبي الورقاء، فلين أَمر نفيع، وَضعف أَبَا الورقاء، وَقدم أَبَا دَاوُد عَلَيْهِ، وَقَالَ: هُوَ أمثل."],[382,"١٦٠"],[383,"- سَأَلته عَن حَارِثَة بن أبي الرِّجَال، فَقَالَ: لَيْسَ هُوَ بذالك."],[384,"١٦١"],[385,"- وَسَأَلته عَن أَخِيه عبد الرَّحْمَن، فَقَالَ: لَيْسَ بِهِ بَأْس."],[386,"١٦٢"],[387,"- سَأَلته عَن ابْن عجلَان، فَقَالَ: ثِقَة، قلت: إِن يحيى قد ضعفه، قَالَ: كَانَ ثِقَة، إِنَّمَا اضْطِرَاب عَلَيْهِ حَدِيث المَقْبُري كَانَ عَن رجل، جعل يصيره عَن أبي هُرَيْرَة."],[388,"١٦٣"],[389,"- سَأَلته عَن رشدين، قَالَ: لَيْسَ أخبر أمره، لَا أَدْرِي."],[390,"١٦٤"],[391,"- سَأَلته قلت: شُعْبَة، عَن عتاب مولى ابْن هُرْمُز، هُوَ عتاب ابْن من هُوَ؟ قَالَ: لَا أَدْرِي."],[392,"١٦٥"],[393,"- قلت: الحكم بن عَطِيَّة، كَيفَ هُوَ؟ قَالَ: الْبَصْرِيّ؟ قلت: نعم، الَّذِي روى عَن ثَابت، قَالَ: كَانَ عِنْدِي لَيْسَ بِهِ"],[394,"بَأْس، ثمَّ بَلغنِي أَنه حدث بِأَحَادِيث مَنَاكِير، وَكَأَنَّهُ ضعفه."],[395,"١٦٦"],[396,"- سَأَلته عَن عمرَان الْقطَّان، فَقَالَ: لَيْسَ بِذَاكَ وَضَعفه."],[397,"١٦٧"],[398,"- سَأَلته عَن إِسْمَاعِيل بن رَافع، قَالَ: لَا أَدْرِي، ابْن أبي مليكَة، عَن عبد الرَّحْمَن بن السَّائِب، فانتهر بِيَدِهِ، وَقَالَ: حَدِيث ذَا لَيْسَ بِشَيْء."],[399,"١٦٨"],[400,"- وَقَالَ فِي حَدِيث أبي النَّضر، عَن أبي جَعْفَر الرَّازِيّ، عَن يزِيد بن عبد الله، قَالَ: هَذَا شَامي، فَذكر حَدِيث وَاثِلَة قصَّة الْبَعِير، فَقَالَ: أَبُو جَعْفَر، لم يسمع من هَذَا، إِنَّمَا روى هَذَا عَن مُحَمَّد بن سعيد."],[401,"وَالله وَأعلم، فَترك مُحَمَّد بن سعيد، وَقَالَ: عَن زيد."],[402,"قلت: إيش حَال مُحَمَّد بن سعيد؟ قَالَ: يَقُولُونَ، وَالله أعلم: إِن أَبَا جَعْفَر صلبه على الزندقة، وَهُوَ مَتْرُوك الحَدِيث."],[403,"١٦٩"],[404,"- قلت: فَأَبُو جَابر البياضي، كَيفَ هُوَ؟ قَالَ: بَلغنِي عَن مَالك،،أَنه كَانَ يَقُول: كَانَ يكذب."],[405,"١٧٠"],[406,"- قلت: فَكيف الْحسن بن عمَارَة؟ قَالَ: مَتْرُوك الحَدِيث."],[407,"١٧١"],[408,"- سَأَلته عَن أبي هَارُون الْعَبْدي."],[409,"قَالَ: لَيْسَ هُوَ بِذَاكَ."],[410,"١٧٢"],[411,"- وَسَأَلته عَن عباد بن كثير، فَقَالَ: لَيْسَ هُوَ بِذَاكَ، قلت: كَانَ فِيهِ شَيْء من الْقدر؟ قَالَ: لَا، إِلَّا أَن حَدِيثه لَيْسَ بِذَاكَ."],[412,"١٧٣"],[413,"- قلت لَهُ: مَا تَقول فِي سعيد بن جمْهَان؟ فَقَالَ: ثِقَة، روى عَنهُ: الْعَوام بن حَوْشَب، وروى عَنهُ: حَمَّاد، وَأرَاهُ ذكر عبد الْوَارِث وَغَيره."],[414,"قلت: يروي عَن يحيى الْقطَّان،،أَنه سُئِلَ عَنهُ، فَلم يرضه، فَقَالَ: بَاطِل، وَغَضب، وَقَالَ: مَا قَالَ هَذَا أحد غير عَليّ بن الْمَدِينِيّ، مَا سَمِعت يحيى يتَكَلَّم فِيهِ بِشَيْء."],[415,"١٧٤"],[416,"- وَذكر عبد الله بن عُثْمَان بن خثيم، فَقَالَ: روى عَن عَطاء فِي الطَّلَاق نَاسِيا أَنه يلْزمه، وَقد روى عَن: ابْن جريج، عَن"],[417,"عَطاء."],[418,"خِلَافه."],[419,"قلت: فَكيف ابْن خثيم؟ قَالَ: ابْن جريج أثبت مِنْهُ."],[420,"١٧٥"],[421,"- حَدثنَا أَبُو عوَانَة، حَدثنَا أَبُو بكر، حَدثنَا أَبُو عبد الله أَحْمد بن مُحَمَّد بن حَنْبَل، قَالَ: سَمِعت مُحَمَّد بن جَعْفَر الْوَركَانِي، يَقُول: كُنَّا عِنْد هشيم، فَقَالَ لَهُ رجل، حَدثنَا سَلمَة الْأَحْمَر، عَن حَمَّاد، عَن إِبْرَاهِيم، قَالَ: كَانَ أَصْحَاب النَّبِي صلى الله عليه وآله وسلم يحرمُونَ فِي المورد، فَقَالَ هشيم: دَعونَا من حَدِيث الْكَذَّابين، فَتَبَسَّمَ أَبُو عبد الله، وَقَالَ: لَيْسَ من هَذَا شَيْء، وَقَالَ: قد رَأَيْت سَلمَة."],[422,"١٧٦"],[423,"- وَسَأَلت أَبَا عبد الله، عَن أبي السَّمْح، قلت: كَيفَ هُوَ؟ قَالَ: قد روى عَن أبي الْهَيْثَم، أَحَادِيث وَتَبَسم، قلت: كَيفَ هُوَ؟ قَالَ: مَا أَدْرِي مَا هُوَ."],[424,"قلت: فَأَبُو الْهَيْثَم؟ قَالَ: ثِقَة."],[425,"١٧٧"],[426,"- وَقَالَ: الْحسن بن ذكْوَان لَيْسَ بِذَاكَ، وَقد روى عَنهُ يحيى."],[427,"١٧٨"],[428,"- وَسَأَلته عَن سُفْيَان بن حُسَيْن كَيفَ هُوَ؟ قَالَ: لَيْسَ بِذَاكَ، وَضَعفه."],[429,"١٧٩"],[430,"- وَسَأَلته عَن إِسْحَاق بن رَاشد، فَقَالَ: ثِقَة."],[431,"١٨٠"],[432,"- وَقَالَ فِي سور بن مُصعب: لَيْسَ بِشَيْء."],[433,"١٨١"],[434,"- قلت لَهُ: يحْتَج بِحَدِيث أبي الزبير؟ فَقَالَ: أَبُو الزبير يروي عَنهُ، ويحتج بِهِ."],[435,"١٨٢"],[436,"- سَأَلته عَن مبارك بن فضَالة، قَالَ: مَا روى عَن الْحسن يحْتَج بِهِ، وَقَالَ: دخل على أبي جَعْفَر، فَجعل يَقُول: يَا أَمِير الْمُؤمنِينَ، سَمِعت الْحسن يَقُول، وَسمعت الْحسن يَقُول، ثمَّ قَالَ أَبُو عبد الله: كَانَ أَبُو جَعْفَر، يُعجبهُ أَمر الْحسن."],[437,"١٨٣"],[438,"- سَأَلته عَن مُحَمَّد بن جَابر، فَقَالَ: يروي عَنهُ، وَقَالَ: كَانَ ابْن مهْدي يحدث عَن مُحَمَّد بن جَابر، ثمَّ تَركه بعد."],[439,"١٨٤"],[440,"- وَسُئِلَ عَنِ الْأَعْمَشِ، عَنْ أَبِي أَيُّوبَ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنِ النَّبِيِّ صلى الله عليه وآله وسلم، «لَا تَقُومُ السَّاعَةُ حَتَّى يَظْهَرَ الْفُحْشُ، وَقَطِيعَةُ الرَّحِمِ»، قَالَ: لَا أَدْرِي مَنْ أَبُو أَيُّوبَ هَذَا؟ لَا أَعْرِفُهُ، قِيلَ لَهُ: هَذَا يَحْيَى بْنُ مَالِكٍ، الَّذِي رَوَى عَنْهُ قَتَادَةُ؟ قَالَ: لَا أَدْرِي"],[441,"١٨٥"],[442,"- سَأَلته عَن أُسَامَة بن زيد، قَالَ: اللَّيْثِيّ أقوى من ذَا،"],[443,"يُرِيد ابْن زيد بن أسلم."],[444,"١٨٦"],[445,"- قلت كَيفَ كَانَ إِسْمَاعِيل بن سَالم؟ قَالَ: لَيْسَ بِهِ بَأْس، قلت: إِنَّه حكى عَن أبي عوَانَة، عَن إِسْمَاعِيل بن سَالم، أَنه سمع زبيدا، يَقُول: كَانَ فِي قصَّة مُعَاوِيَة، قَالَ: وَمن سمع هَذَا من أبي عوَانَة؟ ثمَّ قَالَ: قد كَانَت عِنْده أَحَادِيث الشِّيعَة، وَقد نظر لَهُ شُعْبَة فِي كبته."],[446,"١٨٧"],[447,"- سُئِلَ: عَن الْحسن بن صَالح، فَقَالَ: ثِقَة، إِلَّا أَن مذْهبه ذَاك."],[448,"١٨٨"],[449,"- قلت: يزِيد بن عبد الله أَو عبد الْملك النَّوْفَلِي؟ قَالَ: مَا أَدْرِي، روى هَذَا حَدِيث أبي هُرَيْرَة."],[450,"قلت: فابنه؟ قَالَ: قدم إِلَى هَهُنَا وَضَعفه."],[451,"١٨٩"],[452,"- وَقَالَ فِي تليد بن سُلَيْمَان: كَانَ مذْهبه التَّشَيُّع، وَلم ير بِهِ بَأْسا."],[453,"١٩٠"],[454,"- وَقَالَ: ثَوْر بن يزِيد، ثِقَة، إِلَّا أَنه كَانَ يرى الْقدر."],[455,"١٩١"],[456,"- وَقَالَ: حَمْزَة الزيات ثِقَة فِي الحَدِيث، وَلَكِنِّي أكره قِرَاءَته."],[457,"١٩٢"],[458,"- وَقَالَ: زَكَرِيَّا بن مَنْظُور، شيخ وَلينه."],[459,"١٩٣"],[460,"- سألتُه عَن مُوسَى بْن عُقبة، وَإِبْرَاهِيم بْن عُقبة، وَمُحَمّد بْن"],[461,"عُقبة، فَقَالَ مُوسَى ثِقَة، وَقَالَ: لَيْسَ بهم بَأْس."],[462,"١٩٤"],[463,"- سَأَلته عَن الْأَشْعَث، والنعمان، وَسَعِيد بني أبي خَالِد، فَقَالَ: سعيد لَا أعرفهُ، وَقَالَ: قد روى إِسْمَاعِيل، عَن النُّعْمَان، والأشعث، قلت: كَيفَ هم؟ فَقَالَ: لَيْسَ بهم بَأْس، إِنَّمَا روى عَنْهُم حَدِيثا، أَو حديثين."],[464,"١٩٥"],[465,"- سَأَلته عَن عمر بن نَافِع، وَعبد الله بن نَافِع، فَقَالَ عمر لَا أعرفهُ، وَأَبُو بكر بن نَافِع تكلم بِشَيْء."],[466,"١٩٦"],[467,"- سَأَلته عَن ابْن أخي ابْن شهَاب، كَيفَ هُوَ؟ قَالَ: كَذَا وَكَذَا."],[468,"١٩٧"],[469,"- وَسُئِلَ أَبُو عبد الله عَن عبد الْملك بن عُمَيْر، فَقَالَ: مُضْطَرب الحَدِيث، قل من روى عَنهُ إِلَّا اخْتلف عَلَيْهِ."],[470,"قيل: فَهُوَ أحب إِلَيْك أَو عَاصِم؟ قَالَ: عَاصِم."],[471,"١٩٨"],[472,"- سُئِلَ عَن الْحسن بن دِينَار، فضعفه."],[473,"١٩٩"],[474,"- وَسُئِلَ عَن أبي شيبَة، فضعفه."],[475,"٢٠٠"],[476,"- سَأَلته عَن عبد الله بن مُسلم، الَّذِي روى عَن ابْن بُرَيْدَة، قلت: من عبد الله بن مُسلم؟ قَالَ: لَا أعرفهُ."],[477,"٢٠١"],[478,"- وَسَأَلته عَن صَالح بن حَيَّان، قَالَ: لَيْسَ هُوَ بِذَاكَ، وَأنكر حَدِيثه."],[479,"٢٠٢"],[480,"- سَأَلته سمع معمر من يحيى بن سعيد؟ قَالَ: لَا."],[481,"٢٠٣"],[482,"- وَقَالَ: صَدَقَة الدِّمَشْقِي، لَيْسَ بِشَيْء، ضَعِيف الحَدِيث."],[483,"٢٠٤"],[484,"- قيل لَهُ: يروي عَن الأفريقي؟ قَالَ: لَا، هُوَ مُنكر الحَدِيث، وَقد دخل عَليّ أبي جَعْفَر، فَتكلم بِكَلَام حسن، فَقَالَ"],[485,"لَهُ، وَأحسن، ووعظه."],[486,"٢٠٥"],[487,"- وسمعته يَقُول: مَالك بن أنس عِنْدِي إِمَام من أَئِمَّة الْمُسلمين."],[488,"٢٠٦"],[489,"- سَأَلته عَن قيس بن الرّبيع، فلينه، قلت: أَلَيْسَ قد روى عَنهُ شُعْبَة؟ قَالَ: بلَى."],[490,"٢٠٧"],[491,"- وَسُئِلَ عَن حديج، قَالَ: لَيْسَ أَدْرِي، كَيفَ هُوَ؟"],[492,"٢٠٨"],[493,"- سَأَلته عَن سعيد بن مُحَمَّد الْوراق، فلينه، وَتكلم بِشَيْء."],[494,"٢٠٩"],[495,"- وَقَالَ: الْحسن بن ذكْوَان لَيْسَ بِذَاكَ، وَقد روى عَنهُ يحيى."],[496,"٢١٠"],[497,"- سَأَلته عَن الدَّرَاورْدِي، فَقَالَ: مَا أَدْرِي مَا أَقُول لَك فِيهِ، أَحَادِيثه كَأَنَّهُ يُنكر بَعْضهَا"],[498,"٢١١"],[499,"- سَأَلته عَن ابْن أبي حَازِم، فَقَالَ: لَيْسَ بِهِ بَأْس، قلت: أعجب إِلَيْك من الدَّرَاورْدِي؟ فَقَالَ: نعم."],[500,"٢١٢"],[501,"- وَقَالَ: ابْن جبر، الَّذِي روى عَن ابْن عمر، لَا أعرفهُ"],[502,"وَلَا أَدْرِي من هُوَ؟"],[503,"٢١٣"],[504,"- سَأَلته عَن عبد الْمجِيد بن عبد الْعَزِيز بن أبي رواد، كَيفَ هُوَ؟ فَقَالَ: كَانَ مرجئا، قد كتبت عَنهُ، وَكَانُوا يَقُولُونَ: أفسد أَبَاهُ، وَكَانَ منافرا لِابْنِ عُيَيْنَة، وَكَانَ أَبُو عبد الله يحدث عَن المرجئ: إِذا لم يكن دَاعِيَة أَو مخاصما."],[505,"٢١٤"],[506,"- قلت: يحيى الْقطَّان، إيش كَانَ يَقُول فِي شريك؟ قَالَ: كَانَ لَا يرضاه وَمَا ذكر عَنهُ إِلَّا شَيْئا على المذاكرة حديثين."],[507,"٢١٥"],[508,"- قُلْتُ: فَأَبُو بكر بن عَيَّاش، كَيفَ كَانَ عِنْده؟ قَالَ: كَانَ لَا يرضاه، وَكَانَ يحيى لَا يرضى إِبْرَاهِيم بن سعد."],[509,"قلت: وإيش كَانَ حَاله عِنْده؟ قَالَ: كَانَ على بَيت المَال."],[510,"٢١٦"],[511,"- سَأَلته عَن إِبْرَاهِيم بن الحكم بن أبان، فَقَالَ: لَيْسَ بِذَاكَ، قد كتبت عَنهُ، وأقمت عَلَيْهِ أَيَّامًا."],[512,"٢١٧"],[513,"- سَأَلته عَن يزِيد بن أبي حَكِيم، فَقَالَ: قد كتبت عَنهُ أقل مِمَّا كتبت عَن إِبْرَاهِيم، اتكيت على إِبْرَاهِيم، ثمَّ حدث إِبْرَاهِيم بعد"],[514,"بِأَحَادِيث مُنكرَة، وَضعف أمره، وَقدم يزِيد بن أبي حَكِيم عَلَيْهِ."],[515,"٢١٨"],[516,"- وَسُئِلَ عَن النَّضر بن إِسْمَاعِيل أبي الْمُغيرَة، فَقَالَ: قد كتبنَا عَنهُ، لَيْسَ هُوَ بِقَوي، يعْتَبر بحَديثه، وَلَكِن مَا كَانَ من رقائق، وَكَانَ أَكثر حَدِيثا من ابْن السماك."],[517,"٢١٩"],[518,"- وَقَالَ: مَا يعجبنا مَذْهَب الْحسن بن صَالح، قد كَانَ قعد عَن الْجُمُعَة."],[519,"٢٢٠"],[520,"- قلت لَهُ: أَبُو بدر ثِقَة هُوَ؟ قَالَ: أَرْجُو أَن يكون صَدُوقًا."],[521,"قد جَالس قوما صالحين."],[522,"٢٢١"],[523,"- قلت لَهُ: مَا ترى فِي حَدِيث عبيد الله بن مُوسَى؟ فَقَالَ: قد كَانَ يحدث بِأَحَادِيث رَدِيئَة، وَقد كنت لَا أخرج عَنهُ شَيْئا، ثمَّ إِنِّي خرجت."],[524,"٢٢٢"],[525,"- وَسُئِلَ عَن أَيُّوب بن جَابر، فَقَالَ حَدثنِي بعض أَصْحَابنَا عَن عِيسَى بن يُونُس، أَنه كَانَ يرميه بِالْكَذِبِ، قيل لَهُ: فإيشٍ كَانَ حَاله، إيش أَنْكَرُوا عَلَيْهِ؟ قَالَ: رَأَوْا لُحوقًا فِي كِتَابه."],[526,"٢٢٣"],[527,"- قيل لَهُ: كَتبْتَ عَن أَحْمَد بْن إِسْحَاق الحَضْرمي؟ قَالَ: لَا، تركتُه على عَمْد، قيل لَهُ، إيش أنكرتَ عَلَيْهِ؟ قَالَ: كَانَ عِنْدِي،"],[528,"إِن شَاءَ الله، صَدُوقًا، وَلَكِن تركته من أجل ابْن أَكْثَم، وَدخل لَهُ فِي شَيْء."],[529,"٢٢٤"],[530,"- سُئِلَ عَن يحيى بن سعيد الْأمَوِي، فَقَالَ: لم تكن لَهُ حَرَكَة فِي الحَدِيث."],[531,"٢٢٥"],[532,"- قيل لَهُ: فعبد الصَّمد بن الْوَارِث؟ قَالَ: لم يكن بِهِ"],[533,"بَأْس، وَأَرْجُو أَن يكون كَانَ مُخَالفا لِأَبِيهِ فِي ذَلِك الرَّأْي."],[534,"٢٢٦"],[535,"- سَأَلته عَن يَعْقُوب بن إِسْحَاق الْحَضْرَمِيّ، فَقدم أَخَاهُ أَحْمد عَلَيْهِ، فَقَالَ: لم يكن بِأَحْمَد بَأْس، وَلَكِن تركته من أجل ابْن أَكْثَم، وَقَالَ: كنت عِنْد ابْن مهْدي، فجَاء يَعْقُوب بن إِسْحَاق، فَأَغْلَظ لَهُ، فَلم أكتب عَنهُ شَيْئا."],[536,"٢٢٧"],[537,"- سَأَلته عَن عَاصِم بن عَليّ، فَقلت: إِن يحيى قَالَ: كل عَاصِم فِي الدُّنْيَا ضَعِيف، قَالَ: مَا أعلم مِنْهُ إِلَّا خيرا، كَانَ حَدِيثه صَحِيحا، حَدِيث شُعْبَة والمسعودي، مَا كَانَ أَصَحهَا؟"],[538,"٢٢٨"],[539,"- وَقَالَ: كَانَ وَكِيع إِذا ذكر قَيس بْن الرَّبِيع، قَالَ: اللَّه الْمُسْتَعَان."],[540,"٢٢٩"],[541,"- وَقَالَ: كَانَ أَبُو حُذَيْفَة، الَّذِي بِالْبَصْرَةِ، من أَكثر النَّاس خطأ."],[542,"٢٣٠"],[543,"- وَذكر مُحَمَّد بن الْقَاسِم الْأَسدي، فَقَالَ: مَا يستأهل أَن يحدث عَنهُ بِشَيْء، روى أَحَادِيث مَنَاكِير."],[544,"٢٣١"],[545,"- وَقَالَ فِي رُحَيْلِ بْنِ مُعَاوِيَةَ أَخِي زُهَيْرٍ، قَالَ: هُوَ رَجُلٌ قَدِيمٌ، رَوَى عَنْهُ زُهَيْرٌ، وَلَيْسَ لِي بِحَدِيثِ حُدَيْجٍ عِلْمٌ، فَقِيلَ لَهُ: إِنَّهُ حَدَّثَ عَنْ أَبِي إِسْحَاقَ، عَنِ الْبَرَاءِ، أَنَّ النَّبِيَّ صلى الله عليه وآله وسلم، كَانَ يُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ، فَقَالَ: هَذَا مُنْكَرٌ ٢٣٢ - وَقَالَ أَبُو عبد الله: عَليّ بن مسْهر ولي قَضَاء الْموصل،"],[546,"فَلم يحمد فِي قَضَائِهِ، قلت: فَالنَّاس يشتهون حَدِيثه، قَالَ: لِأَن حَدِيثه حَدِيث أهل الصدْق."],[547,"٢٣٣"],[548,"- وَقَالَ: شُعَيْب بن أبي حَمْزَة كَانَ لَا يكَاد يحدث، فَلَمَّا حَضرته الْوَفَاة، قَالَ: اجْمَعُوا لي فلَانا وَفُلَانًا، فَاجْتمع بَقِيَّة، وَيَقُولُونَ أَبُو الْيَمَان، وَقد ذكرُوا عَليّ بن عَيَّاش، فَلَا أَدْرِي كَانَ أم لَا؟ فَقَالَ: هَذِه كتبي ارووها عني، فَكَانَ أَبُو الْيَمَان يَقُول: حَدثنِي شُعَيْب، وَلَا أَدْرِي كَانَ مَعَهم أم لَا؟"],[549,"٢٣٤"],[550,"- وَذَكَرَ الْحِمَّانِيَّ، فَقُلْتُ: إِنَّهُ رَوَى عَنْكَ حَدِيثَ إِسْحَاقَ الْأَزْرَقِ، حَدِيثَ الْمُغِيرَةِ بْنِ شُعْبَةَ: أَبْرِدُوا بِالصَّلَاةِ، وَزَعَمَ أَنَّهُ"],[551,"سَمِعَهُ عَلَى بَابِ ابْنِ عُلَيَّةَ، فَأَنْكَرَ أَنْ يَكُونَ سَمِعَهُ، وَقَالَ: لَيْسَ مِنْ ذَا شَيْءٌ."],[552,"قلت: إِنَّه ادّعى أَن هَذَا على المذاكرة، فَقَالَ: وَأَنا علمت فِي أَيَّام إِسْمَاعِيل أَن هَذَا كَانَ عِنْدِي، يَعْنِي إِنَّمَا أخرجته بِآخِرهِ."],[553,"وَقَالَ: قُولُوا لهارون الْحمال يضْرب على حَدِيث الْحمانِي."],[554,"٢٣٥"],[555,"- قيل لَهُ: فتمام بن نجيح مَا حَاله؟ قَالَ: لَا أَدْرِي."],[556,"٢٣٦"],[557,"- قيل لَهُ: فإسماعيل بن مجَالد؟ قَالَ: لَا أَدْرِي قد روى عَنهُ."],[558,"٢٣٧"],[559,"- وَقَالَ أَبُو عبد الله: كنت مَعَ يحيى بن معِين فلقي أَبَا بدر، فَقَالَ لَهُ: اتَّقِ الله يَا شيخ، وَانْظُر هَذِه الْأَحَادِيث لَا يكون ابْنك يعطيك، قَالَ أَبُو عبد الله: فَاسْتَحْيَيْت وتنحيت نَاحيَة، فبلغني أَنه قَالَ: إِن كنت كَاذِبًا فَفعل الله بك وَفعل."],[560,"٢٣٨"],[561,"- سَأَلته عَن عُثْمَان بن مطر، كَيفَ هُوَ؟ قَالَ: كَذَا وَكَذَا."],[562,"٢٣٩"],[563,"- سَأَلته عَن طَلْحَة بن يزِيد أَو ابْن زيد الْقرشِي، فَقَالَ: لَيْسَ بِذَاكَ، قد حدث بِأَحَادِيث مَنَاكِير."],[564,"٣٤٠"],[565,"- قلت لَهُ: أَيّمَا أحب إِلَيْك الحوضي أَو أَبُو الْوَلِيد؟ فَقَالَ: الحوضي أَكيس من أبي الْوَلِيد وَأثبت، كَانَ متيقظا، وَإِن كَانَ أَبُو الْوَلِيد حسن الحَدِيث عَن شُعْبَة."],[566,"٣٤١"],[567,"- وَقَالَ: قَالَ عَفَّان قَالَ حَمَّاد بن زيد لشعيب بن حَرْب،"],[568,"يَا أَبَا صَالح، قد دعينا إِلَى وَلِيمَة فَيَجِيء."],[569,"قَالَ أَبُو عبد الله: كَانَ فِي حَمَّاد مزاح."],[570,"٣٤٢"],[571,"- وسمعته يَقُول: سَمِعت مؤملا، يَقُول: شغب أَصْحَاب الحَدِيث بِمَكَّة على سُفْيَان، وَكَانَ فيهم شُعَيْب بن حَرْب، حَتَّى عزلوا الْمُسْتَمْلِي، وَقَالَ: كَانَ ابْن إِدْرِيس لَا يذهب إِلَى وَلِيمَة، حَتَّى يسْأَل فِيهَا، يَعْنِي نَبِيذ."],[572,"٢٤٣"],[573,"- وَذكر عبد الْوَهَّاب، قلت: كتب عَن يحيى بن سليم؟ قَالَ: قَالَ لنا: لم أكتب عَن يحيى بن سليم إِلَّا حَدِيثا أَو"],[574,"حديثين."],[575,"٢٤٤"],[576,"- فَقلت لَهُ: إِنَّه لم يكْتب عَن إِسْمَاعِيل بِحَال ذَاك الْكَلَام؟ قلت: وَقَالَ: كَانَ يدْخل دَاره أهل الْبدع، قَالَ: عافاه الله، لقد نظر فِيهِ بِنور الله، لم يكن يستأهل أَن يكْتب عَنهُ، أَقَامَهُ النَّاس على مسطبة، وارتجت عَلَيْهِ بَغْدَاد، وأذله أهل الحَدِيث، وَقَالَ: أَرْجُو أَن يرحم الله ابْن زبيدة."],[577,"لما أَدخل عَلَيْهِ إِسْمَاعِيل كَلمه بِكَلَام، وزحف من مَوْضِعه، فَجعل إِسْمَاعِيل يَقُول لَهُ: زلَّة من عَالم، زلَّة من عَالم."],[578,"قَالَ: وَكَانَ يحدث المريسي، إِلَّا أَنه الْخَبيث لم يكن يظْهر ذَاك تِلْكَ الْأَيَّام."],[579,"٢٤٥"],[580,"- قلت لَهُ: إِن خلفا حُكيَ أَن أَبَا أُسَامَة أَتَاك بِالْكُوفَةِ، فَقَالَ: كذب، لم يكن من ذَا شَيْء، لم نرْزق مِنْهُ أقل كتابي عَنهُ، وَلَكِن كتابي عَن ابْن نمير كتاب صَالح."],[581,"٢٤٦"],[582,"- وسمعته يثني على دُحَيْم، وَيَقُول: هُوَ عَاقل ركين."],[583,"٢٤٧"],[584,"- وَذكر هِشَام بن عمار، فَقَالَ: طياش، خَفِيف، وَقَالَ: كُنَّا بالثغر، وَكَانَ مَعنا شَاب، فَذهب إِلَى يُوسُف بن أَسْبَاط، فَكتب عَنهُ أَحَادِيث، فَكَانَ مِنْهَا عَن هِشَام، عَن الْحسن، فِي أهل الذِّمَّة، إِذا نقضوا الْعَهْد، قَالَ: لَا تسبي الذُّرِّيَّة."],[585,"وَحدث عَن مُغيرَة، عَن إِبْرَاهِيم، مثله، حدث بهما عَن سُفْيَان، فَقلت: لَيْسَ من مُغيرَة عَن إِبْرَاهِيم شَيْء فَلم أَنه، وَكَانَ قد اضْطربَ عَلَيْهِ حفظه."],[586,"٢٤٨"],[587,"- وسمعته سُئِلَ عَن الْوَاقِدِيّ، فَقيل لَهُ، قَالَ ابْن الْمُبَارك: دَعونَا من بَحر الْوَاقِدِيّ."],[588,"فَقَالَ: شهِدت وكيعا، وَقد سَأَلُوهُ عَن حَدِيث فِي مسح الْحَصَى، فَقَالَ لَو كنت عِنْد الْوَاقِدِيّ، لحدثك هَكَذَا."],[589,"٢٤٩"],[590,"- سَأَلته عَن إِسْمَاعِيل بن عَيَّاش، فَحسن رِوَايَته عَن الشامين، وَقَالَ: هُوَ عَنْهُم أحسن حَالا، مِمَّا روى عَن الْمَدَنِيين وَغَيرهم."],[591,"٢٥٠"],[592,"- قلت لَهُ فِي الْوَلِيد، فَقَالَ: هُوَ كثير الْخَطَأ، قد كتبتها عَن رجل عَنهُ، وَقدم إِلَى مَكَّة مرَّتَيْنِ، وكتبت عَنهُ فِي إِحْدَاهمَا قدر أَربع مائَة حَدِيث، وَقد كَانَ قوم سمعُوا مِنْهُ قدر ثَمَان مائَة."],[593,"٢٥١"],[594,"- قلت: كتبت عَن ابْن وهيب شَيْئا؟ قَالَ: لَا."],[595,"٢٥٢"],[596,"- قلت: فيحيى بن سليم؟ قَالَ: حَدِيثا أَو حديثين، كَانَ يكثر الْخَطَأ."],[597,"٢٥٣"],[598,"- وَقَالَ: مَا كنت أرى الْفرْيَابِيّ على كَثْرَة خطئه، تعلم، إِن الْأَخْذ كَانَ عِنْد سُفْيَان شَدِيدا."],[599,"٢٥٤"],[600,"- وَسَأَلته، قلت: سعيد بن أبي عرُوبَة حِين قدم الْكُوفَة سمعُوا مِنْهُ، وَهُوَ مختلط؟ قَالَ: لَا، سماعهم جيد، لم يكن مختلطا."],[601,"٢٥٥"],[602,"- وَسُئِلَ أَبُو عبد الله عَن: حَدِيثِ ابْنِ الْمُبَارَكِ، عَنْ مَالِكِ بْنِ أَنَسٍ، عَنِ ابْنِ الْمُنْكَدِرِ، عَنْ أَنَسٍ، عَنِ النَّبِيِّ صلى الله عليه وآله وسلم \" مَنْ جَلَسَ إِلَى قَيْنَةٍ صُبَّ فِي أُذُنِهِ الْآنُكُ يَوْمَ الْقِيَامَةِ."],[603,"وَقِيلَ لَهُ: رَوَاهُ رَجُلٌ بِحَلَبَ، وَحَسَّنُوا الثَّنَاءَ عَلَيْهِ، فَقَالَ: هَذَا بَاطِلٌ"],[604,"٢٥٦"],[605,"- وَنَظَرَ فِي حَدِيثِ عِسْلِ بْنِ سُفْيَانَ، عَنِ ابْنِ أَبِي مُلَيْكَةَ، عَنْ عَائِشَةَ، قَالَ النَّبِيُّ صلى الله عليه وآله وسلم: لَيْسَ مِنَّا مَنْ لَمْ يَتَغَنَّ بِالْقُرْآنِ \"،"],[606,"فَقَالَ: لَيْسَ مِنْ هَذَا شَيْءٌ، مَنْ قَالَ: عَنْ عَائِشَةَ، قَدْ أَخْطَأَ، ضَعَّفَ عِسْلَ بْنَ سُفْيَانَ"],[607,"٢٥٧"],[608,"- وَسَأَلته عَن حَدِيث إِسْمَاعِيل بن رَافع، قَالَ: حَدثنِي ابْن أبي مليكَة، عَن عبد الرَّحْمَن بن السَّائِب، فنفض يَده، وَقَالَ: لَيْسَ من هَذَا شَيْء وَضَعفه."],[609,"٢٥٨"],[610,"- قلت: مَا حَال مُحَمَّد بن سعيد؟ قَالَ: يَقُولُونَ، وَالله أعلم، إِن أَبَا جَعْفَر صلبه، على الزندقة."],[611,"٢٥٩"],[612,"- وَقَالَ فِي حَدِيثِ يَحْيَى بْنِ سُلَيْمٍ، عَنْ عُبَيْدِ اللَّهِ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، قَالَ: سَافَرْتُ مَعَ رَسُولِ اللَّهِ صلى الله عليه وآله وسلم، وَأَبِي بَكْرٍ، وَعُمَرَ، وَعُثْمَانَ، فَكَانُوا يُصَلُّونَ الظُّهْرَ وَالْعَصْرَ رَكْعَتَيْنِ رَكْعَتَيْنِ، لَا يُصَلُّونَ قَبْلَهَا وَلَا بَعْدَهَا، فَأَنْكَرَهُ إِنْكَارًا شَدِيدًا، وَقَالَ: هَذَا مِنْ قِبَلِ يَحْيَى بْنِ سُلَيْمٍ"],[613,"٢٦٠"],[614,"- وَقَالَ فِي حَدِيث وَرْقَاء، عَن أبي الزِّنَاد، عَن الْأَعْرَج، عَن أبي هُرَيْرَة: أعوادي وقف، فَقَالَ: أَخطَأ فِيهِ وَرْقَاء، وَأصَاب ابْن أبي الزِّنَاد، قَالَ: أعبدي وقف، ثمَّ قَالَ: ابْن أبي الزِّنَاد أحب إِلَيّ من وَرْقَاء."],[615,"٢٦١"],[616,"- قلت: فَكيف حسن بن عمَارَة؟ قَالَ: مَتْرُوك الحَدِيث."],[617,"٢٦٢"],[618,"- وَقَالَ فِي حَدِيث عبيد الله، عَن نَافِع، عَن ابْن عمر فِي مثل قصَّة ذِي الْيَدَيْنِ، فَقَالَ: كَانَ يَقُول يَعْنِي أُسَامَة، عَن هِشَام، عَن ابْن سِيرِين، عَن أبي هُرَيْرَة، ثمَّ يَقُول: عَن عُبَيْدِ اللَّهِ، عَنْ نَافِعٍ، عَنِ ابْن عمر، مثله."],[619,"وَقَالَ قَالَ يحيى بن سعيد: إِنَّمَا هُوَ فِي كتاب عبيد الله مُرْسل، وَمَا يَنْبَغِي إِلَّا كَمَا قَالَ يحيى، وَأنْكرهُ."],[620,"٢٦٣"],[621,"- وَقَالَ: كُنَّا عِنْدَ إِسْمَاعِيلَ بْنِ إِبْرَاهِيمَ، فَذُكِرَ لَهُ حَدِيثُ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قُلْتُ: يَا رَسُولَ اللَّهِ، أَكْتُبُ عَنْكَ مَا أَسْمَعُ؟ قَالَ: نَعَمْ، قَالَ: فِي الْغَضَبِ وَالرِّضَا؟، قَالَ أَبُو عَبْدِ اللَّهِ: فَسَمِعْتُ إِسْمَاعِيلَ، وَهُوَ يَقُولُ: أَعُوذُ بِاللَّهِ مِنَ الْكَذِبِ وَأَهْلِهِ"],[622,"قلت: كَأَنَّهُ لم يرض عَمْرو بن شُعَيْب، قَالَ: قد كَانَ يحدث بحَديثه، وَلَكِن كَانَ مَذْهَب ابْن سِيرِين، وَأَيوب، وَابْن عون أَلا يكتبوا."],[623,"٢٦٤"],[624,"- وَذكرت لَهُ حَدِيث الْحُسَيْن الْجعْفِيّ، عَن ابْن عُيَيْنَة، عَن عَمْرو بن دِينَار، عَن جَابر: أسلم سَالَمَهَا الله، فَأنكرهُ إنكارا شَدِيدا"],[625,"، وَقَالَ: هَذَا عبد الله بن دِينَار، عَن ابْن عمر، أنظر الْوَهم من قبل من هُوَ؟"],[626,"٢٦٥"],[627,"- وَذَكَرْتُ حَدِيثَ عَبَّادٍ، عَنِ ابْنِ أَبِي عَرُوبَةَ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ، \" أَنَّ صَفِيَّةَ حَاضَتْ بَعْدَ مَا طَافَتْ"],[628,"فَقَالَ: أَخْطَأَ فِيهِ عَبَّادٌ، إِنَّمَا هُوَ عَنْ قَتَادَةَ، عَنْ عِكْرِمَةَ"],[629,"٢٦٦"],[630,"- وَسَأَلْتُهُ عَنْ حَدِيثِ مَعْمَرٍ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ، أَنّ النَّبِيَّ صلى الله عليه وآله وسلم نَهَى عَنِ الشِّغَارِ فَقَالَ: هَذَا حَدِيثٌ مُنْكَرٌ، مِنْ حَدِيثِ ثَابِتٍ"],[631,"٢٦٧"],[632,"- وَسَأَلته عَن حَدِيث عَاصِم بن عبيد الله، الَّذِي يحدث عَنهُ ابْن جريج، فَقَالَ: كَانَ عَاصِم بن عبيد الله، الشُّيُوخ يهابون حَدِيثه."],[633,"٢٦٨"],[634,"- قُلْتُ لَهُ: فَتَعْرِفُ عَنِ الْوَلِيدِ، عَنِ الأَوْزَاعِيِّ، عَنْ يَحْيَى،"],[635,"عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وآله وسلم: مَتَى كُتِبْتَ نَبِيًّا، قَالَ: هَذَا مُنْكَرٌ، هَذَا مِنْ خَطَأِ الأَوْزَاعِيِّ، هُوَ كَثِيرًا مِمَّا يُخْطِئُ، عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ، كَانَ يَقُولُ: عَنْ أَبِي الْمُهَاجِرِ، وَإِنَّمَا"],[636,"هُوَ أَبُو الْمُهَلَّبِ"],[637,"٢٦٩"],[638,"- قُلْتُ: تَعْرِفُ عَنْ عَطَاءِ بْنِ مُسْلِمٍ الْخَفَّافِ، عَنْ مُحَمَّدِ بْنِ عَمْرٍو، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وآله وسلم: «يُحْشَرُ الْمُتَكَبِّرُونَ فِي صُوَرِ الذَّرِّ، يَطَؤُهُمُ النَّاسُ»"],[639,"، فَأَنْكَرَهُ، وَقَالَ: مَا أَعْرِفُهُ، عَطَاءُ بْنُ مُسْلِمٍ مُضْطَرِبُ الْحَدِيثِ"],[640,"٢٧٠"],[641,"- سَأَلْتُهُ عَنْ حَدِيثِ عَبْدِ الرَّزَّاقِ، عَنْ مَعْمَرٍ، عَنْ أَبِي إِسْحَاقَ، عَنْ عَاصِمِ بْنِ ضَمْرَةَ، عَنْ عَلِيٍّ، عَنِ النَّبِيِّ صلى الله عليه وآله وسلم: «أَنَّهُ مَسَحَ عَلَى الْجَبَائِرِ»، فَقَالَ: بَاطِلٌ، لَيْسَ مِنْ هَذَا شَيْءٌ، مَنْ حَدَّثَ بِهَذَا؟ قُلْتُ:"],[642,"ذَكَرُوهُ عَنْ صَاحِبِ الزُّهْرِيِّ، فَتَكَلَّمَ فِيهِ كَلامًا غَلِيظًا"],[643,"٢٧١"],[644,"- وَعَرَضْتُ عَلَيْهِ حَدِيثًا، رَوَوْهُ عَنْ مُحَمَّدِ بْنِ الْجَرَّاحِ، عَنْ شُعْبَةَ، عَنْ سُفْيَانَ الثَّوْرِيِّ، عَنْ عَلِيٍّ، مَرْفُوعًا: مَنْ صَلَّى كَذَا فَلَهُ كَذَا، وَمَنْ قَرَأَ كَذَا فَلَهُ كَذَا \"، فَقَالَ: هَذَا بَاطِلٌ مَوْضُوعٌ، قَدْ رَأَيْتُ ابْنَ الْجَرَّاحِ، فَرَأَيْتُ عِنْدَهُ أَحَادِيثَ، وُضِعَتْ لَهُ، لَمْ يَكُنْ يَدْرِي مَا الْحَدِيثُ"],[645,"٢٧٢"],[646,"- وَأَلْقَيْتُ عَلَى أَبِي عَبْدِ اللَّهِ حَدِيثًا، رَوَاهُ الْفَضْلُ بْنُ مُوسَى، عَنْ إِبْرَاهِيمَ بْنِ عَبْدِ الرَّحْمَنِ، عَن ابْن جريج، عَن عَطاء، عَنِ ابْنِ عَبَّاسٍ، قَالَ: «عَارَضَ رَسُولِ اللَّهِ صلى الله عليه وآله وسلم جِنَازَةَ أَبِي طَالِبٍ»، فَقَالَ: هَذَا مُنْكَرٌ، هَذَا رَجُلٌ مَجْهُولٌ"],[647,"٢٧٣"],[648,"- وَقُلْتُ لِأَبِي عَبْدِ اللَّهِ: إِنَّ عَلِيَّ بْنَ الْمَدِينِيِّ ١٧ حَدَّثَ، عَنِ الْوَلِيدِ بْنِ مُسْلِمٍ حَدِيثَ عُمَرَ: «كِلُوهُ إِلَى خَالِقِهِ»، فَقَالَ: هَذَا كَذِبٌ، ثُمّ قَالَ: هَذَا كَتَبْنَاهُ عَنِ الْوَلِيدِ، إِنَّمَا هُوَ"],[649,"فَكِلُوهُ إِلَى عَالِمِهِ، هَذَا كَذِبٌ"],[650,"٢٧٤"],[651,"- وَذَكَرْتُ لَهُ حَدِيثَ نَافِعٍ، عَنِ ابْنِ عُمَرَ، عَنْ عُمَرَ: \" مَنْ بَاعَ عَبْدًا وَلَهُ مَالٌ، فَمَالُهُ لِلْبَائِعِ، فَقَالَ: خَالَفَهُ سَالِمٌ، هَكَذَا رَوَاهُ الزُّهْرِيُّ، عَنْ سَالِمٍ، عَنِ ابْنِ عُمَرَ عَنِ النَّبِيِّ صلى الله عليه وآله وسلم"],[652,"قلت: فأيما الثَّبْتُ فَتَبَسَّمَ، وَقَالَ: اللَّهُ أَعْلَمُ، قُلْتُ: مَا الَّذِي يُمِيلُ إِلَيْهِ قَلْبك مِنْهُمَا؟ قَالَ: أرى، وَالله أعلم، إِلَى نَافِع."],[653,"٢٧٥"],[654,"- وَأَنْكَرَ حَدِيثَ طَلْحَةَ بْنِ زَيْدٍ، عَنْ مُوسَى بْنِ يَسَارٍ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وآله وسلم:"],[655,"فِي الْعَسَلِ الْعُشْرُ، فَقَالَ طَلْحَةُ بْنُ زَيْدٍ: كَانَ نَزَلَ عَلَى شُعْبَةَ، لَيْسَ بِشَيْءٍ، كَانَ يَضَعُ الْحَدِيثَ، وَبِشْرِ بْنِ نُمَيْرٍ هَذَيْنِ لَيْسَ بِشَيْءٍ"],[656,"٢٧٦"],[657,"- وَأَرَيْتُهُ حَدِيثًا عَنْ كَثِيرِ بْنِ هِشَامٍ، عَنْ عِيسَى بْنِ إِبْرَاهِيمَ،"],[658,"عَنْ سَعِيدِ بْنِ سِنَانٍ، عَنْ أَبِي الزَّاهِرِيَّةِ، عَنْ كَثِيرِ بْنِ مُرَّةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وآله وسلم: مَا الْتَقَى بَيِّعَانِ قَطُّ إِلَّا أَظَلَّتْهُمَا الْبَرَكَةُ، فَقَالَ: لَيْسَ مِنْ هَذَا شَيْءٌ، عِيسَى بْنُ إِبْرَاهِيمَ، وَسَعِيدُ بْنُ سِنَانٍ لَيْسَا بِشَيْءٍ"],[659,"٢٧٧"],[660,"- وَقَالَ فِي حَدِيث يعلى، عَن غَالب بن عبيد الله الْعقيلِيّ:"],[661,"لَيْسَ بِشَيْء."],[662,"٢٧٨"],[663,"- وَذَكَرْتُ لَهُ حَدِيثَ زُهَيْرِ بْنِ مُحَمَّدٍ، عَنِ الْعَلَاءِ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وآله وسلم: إِذَا كَانَ نِصْفُ شَعْبَانَ فَلَا صَوْمَ،"],[664,"فَأَنْكَرَهُ، وَقَالَ: سَأَلْتُ ابْنَ مَهْدِيٍّ عَنْهُ، فَلَمْ يُحَدِّثْنِي بِهِ، وَكَانَ يَتَوَقَّاهُ، ثُمَّ قَالَ أَبُو عَبْدِ اللَّهِ: هَذَا خِلافُ الأَحَادِيثِ الَّتِي رُوِيَتْ عَنِ النَّبِيِّ صلى الله عليه وآله وسلم"],[665,"٢٧٩"],[666,"- وَسُئِلَ أَو عبد الله، عَن سعيد الْوراق، فَقَالَ: لم يكن بِذَاكَ، وَقد حكوا عَنهُ حَدِيثا مُنْكرا، قلت: إيش هُوَ؟ قَالَ: عَن يحيى بن سعيد، عَن عُرْوَة، عَن عَائِشَة، شَيْء فِي السخاء."],[667,"٢٨٠"],[668,"- وَذكر لوينا، فَقَالَ: قد حدث حَدِيثا مُنْكرا، عَن ابْن عُيَيْنَة مَاله أصل، قلت: إيش هُوَ؟ قَالَ: عَن عَمْرو بن دِينَار، عَن أبي جَعْفَر، عَن إِبْرَاهِيم بن سعد، عَن أَبِيه قصَّة عَليّ، مَا أَنا الَّذِي أخرجتكم، وَلَكِن الله أخرجكم، فَأنكرهُ إنكارًا شَدِيدا، وَقَالَ:"],[669,"مَاله أصل."],[670,"٢٨١"],[671,"- وسمعته يَقُول: كَانَ ابْن وهب حَدِيثه بعضه سَماع، وَبَعضه عرض، وَبَعضه مناولة، كَانَ يَأْخُذ الْكتاب مِمَّا لم يسمعهُ، يَقُول: قَالَ حَيْوَة، قَالَ فلَان."],[672,"٢٨٢"],[673,"- وسمعته يَقُول: سَالم بْن نوح لَيْسَ بِهِ بَأْس، وَهُوَ من أَهْل الْبَصْرَة، قد كتبت عَنْهُ حَدِيثا وَاحِدًا."],[674,"٢٨٣"],[675,"- وسمعته يَقُول: مَا بِالْكُوفَةِ مثل هناد، وَهُوَ شيخهم."],[676,"٢٨٤"],[677,"- وَسمعت أَبَا عبد الله، يَقُول: كَانَ أَبُو بدر لَا يَقُول حَدثنَا، وَلَقَد أرادوه على أَن يَقُول حَدثنَا خصيف، فَأبى، وَقَالَ: أَلَيْسَ هُوَ ذَا أَقُول: خصيف."],[678,"٢٨٥"],[679,"- وسمعته يَقُول: وَقَالَ لَهُ ابْن أبي رزمة، لَك حَاجَة؟ قَالَ: نعم، تقري ابْن أبي عمر من السَّلَام يَعْنِي الْعَدنِي."],[680,"٢٨٦"],[681,"- سُئِل عَن لُوَين، فَقَالَ لَا أعرفة."],[682,"٢٨٧"],[683,"- وَذكر لَهُ الْفَوَائِد، فَقَالَ: الحَدِيث عَن الضُّعَفَاء قد يحْتَاج إِلَيْهِ فِي وَقت، وَالْمُنكر أَبَد مُنكر."],[684,"٢٨٨"],[685,"- سَأَلته عَن خلف المخرمي، فَقَالَ: نقموا عَلَيْهِ تتبعه هَذِه الْأَحَادِيث، قلت: هُوَ صَدُوق؟ قَالَ: مَا أعرفهُ بكذب، مَعَ أَنه قد دخل مَعَ الْأنْصَارِيّ فِي شَيْء، حكى عَنهُ أَمر بغيض كَانَ إِذا أَمر الْإِنْسَان بِشَيْء اشْتَرَاهُ، قلت: كَانَ يعين؟ قَالَ: الْعينَة أحسن من ذَا، ثمَّ قَالَ: كنت أعرفهُ عفيف الْبَطن، والفرج."],[686,"٢٨٩"],[687,"- سَأَلته عَن مَحْمُود بن غيلَان، فَقَالَ: ثِقَة، أعرفهُ بِالْحَدِيثِ، صَاحب سنة، قد حبس بِسَبَب الْقُرْآن."],[688,"٢٩٠"],[689,"- قلت: فَأَبُو بكر مستملي، وَكِيع تعرفه؟ قَالَ: نعم، قد كَانَ مَعنا يكْتب الحَدِيث."],[690,"كتب لي كتابا بِخَطِّهِ."],[691,"أَظُنهُ قَالَ: الطَّلَاق، قلت: إِنَّه، حدث بِحَدِيث أنكروه، مَا أقل من هُوَ عِنْده عَن عبد الرَّزَّاق هُوَ عنْدك، وَكَانَ عِنْد خلف، قَالَ: قد كَانَ مَعنا تِلْكَ السّنة، قلت: فأيما أعجب إِلَيْك هُوَ أَو مَحْمُود؟ قَالَ: لَا مَحْمُود غير هَذَا، مَحْمُود أعجب إِلَيّ."],[692,"٢٩١"],[693,"- وَذكر نوح بن حبيب القومسي، فَقَالَ: لم يكن يكاتبني، إِن الْخَيْر عَلَيْهِ لبين، قلت أكتب عَنهُ؟ قَالَ: نعم."],[694,"٢٩٢"],[695,"- سَأَلته عَن حُسَيْن بن الْأسود، فَقَالَ لَا أعرفهُ."],[696,"٢٩٣"],[697,"- وَعرضت على أبي عبد الله كتابا فِيهِ هَذِه الْأَسْمَاء."],[698,"الْإِخْوَة فِيهِ: عمرَان بن عُيَيْنَة، وَإِبْرَاهِيم بن عُيَيْنَة، وَمُحَمّد بن عُيَيْنَة، فَقَالَ: كَانَ مُحَمَّد شَيْئا عجبا، وَكَانَ بعد سُفْيَان، وَكَانَ يلبس الصُّوف، وَكَانَ إِبْرَاهِيم بن عُيَيْنَة حدث بِأَحَادِيث أنكرها، ولين القَوْل فِيهِ."],[699,"٢٩٤"],[700,"- وَسَأَلته عَن عمر بن عبيد، وَمُحَمّد بن عبيد، ويعلى"],[701,"بن عبيد، فوثقهم، ثمَّ قَالَ: كَانَ عمر لَا يَقُول حَدثنَا، وَلَا أخبرنَا."],[702,"٢٩٥"],[703,"- وَفِيه أَبُو بكر بن نَافِع، فَقَالَ: أَبُو بكر بن نَافِع، هُوَ عبد الله بن نَافِع، وَتكلم بِشَيْء."],[704,"٢٩٦"],[705,"- وَفِيه سُهَيْل، وَعبد الله بن أبي صَالح، وَعباد، فَقَالَ: سُهَيْل لَيْسَ بِهِ بَأْس، وَعبد الله هُوَ عباد."],[706,"٢٩٧"],[707,"- وَفِيه عبد الْحَكِيم بن عبد الله بن أبي فَرْوَة، وَعبد الْأَعْلَى بن"],[708,"عبد الله بن أبي فَرْوَة، وَإِسْحَاق بن عبد الله بن أبي فَرْوَة، فَقَالَ: لَيْسَ بهم بَأْس، إِلَّا إِسْحَاق، فَإِنَّهُ نقض يَده وَضَعفه، وَأنْكرهُ."],[709,"٢٩٨"],[710,"- وَيُونُس بن خباب، فَقَالَ: هَذَا قد حُكيَ عَنهُ، يَعْنِي فِي عُثْمَان، وَلينه."],[711,"٢٩٩"],[712,"- وَفِيه أَيُّوب بن خَالِد بن صَدَقَة، الْأنْصَارِيّ، فَقَالَ لَا أعرفهُ."],[713,"٣٠٠"],[714,"- وَأَيوب بن بشير، الْعَدوي، فَقَالَ لَا أعرفهُ."],[715,"٣٠١"],[716,"- وَفِيه أَيُّوب بن بشير، الْأنْصَارِيّ، وَأَيوب بن كيسَان، وَأَيوب بن ميسرَة بن حَلبس، وَأَيوب بن مرْثَد."],[717,"وَأَيوب بن"],[718,"عبد الرَّحْمَن بن صعصعة، وَأَيوب بن مُوسَى، الْقرشِي، فَقَالَ: أَيُّوب بن مُوسَى ثِقَة."],[719,"وَأَيوب بن ثَابت، وَأَيوب بن عباد، وَأَيوب بن نجيح، كَأَنَّهُ لم يعرف هَؤُلَاءِ."],[720,"٣٠٢"],[721,"- قيل لَهُ: مُحَمَّد بْن إِسْحَاق، وَابْن أخي الزُّهْرِيّ، فِي حَدِيث الزُّهْرِيّ؟ فَقَالَ: مَا أَدْرِي، وحرّك يدَه كَأَنَّهُ ضعّفهُما."],[722,"٣٠٣"],[723,"- قيل لَهُ: فحفص وَعَبدَة؟ قَالَ: أما عَبدة فصدوق ثَبت، وَأما حَفْص فنفض يَده، وَقَالَ: خله فِي حَدِيثه."],[724,"٣٠٤"],[725,"- قيل لَهُ: فزائده وَزُهَيْر؟ قَالَ: هَؤُلَاءِ وسُفْيَان، وَشعْبَة، وزائدة، وَزُهَيْر، هَؤُلَاءِ الثِّقَات."],[726,"٣٠٥"],[727,"- قيل لَهُ فبشر بن السّري؟ قَالَ: ثَبت."],[728,"٣٠٦"],[729,"- وَقَالَ: حَدثنَا شُعَيْب بن حَرْب، قَالَ: سَمِعت سُفْيَان، يَقُول: مَا أحب أَنِّي أوافقهم على الْحق، يَعْنِي أَبَا حنيفَة."],[730,"٣٠٧"],[731,"- قَالَ أَبُو عبد الله: إِسْمَاعِيل بن أُميَّة، وَأَيوب بن مُوسَى من أهل مَكَّة، وهما ابْنا عَم، وَكَانَ أَيُّوب بن مُوسَى أَنْفَع للنَّاس، إِلَّا أَن إِسْمَاعِيل أوثق مِنْهُ وَأثبت."],[732,"٣٠٨"],[733,"- وَسُئِلَ أَبُو عبد الله، عَن أبي الصَّلْت، فَقَالَ: روى أَحَادِيث"],[734,"مَنَاكِير، قيل لَهُ: روى حَدِيث مُجَاهِد عَن عَليّ: أَنا مَدِينَة الْعلم، وَعلي بَابهَا قَالَ: مَا سمعنَا بِهَذَا، قيل لَهُ: هَذَا الَّذِي تنكر عَلَيْهِ؟ قَالَ: غير هَذَا، أما هَذَا فَمَا سمعنَا بِهِ، وروى عَن عبد الرازق وَاحِدًا لَا نعرفها، وَلم نسمعها."],[735,"قيل لأبي عبد الله: قد عَن عبد الرازق من هَذِه الْأَحَادِيث الرَّديئَة؟ قَالَ: لم أسمع مِنْهَا شَيْئا."],[736,"٣٠٩"],[737,"- وَسَأَلْتُهُ عَنْ عُبَيْدِ اللَّهِ بْنِ مُوسَى أخرجت عَنهُ شَيْئا؟ قَالَ: رُبمَا أخرجت عَنهُ، وَرُبمَا ضربت عَلَيْهِ، حدث عَن قوم غير ثِقَات، فَإِن كَانَ من حَدِيث الْأَعْمَش فعلى ذَاك."],[738,"٣١٠"],[739,"- وَسَأَلته عَن أبي بكر الْأَثْرَم، قلت: نهيت أَن يكْتب عَنهُ؟ قَالَ: لم أقل إِنَّه لَا يكْتب عَنهُ الحَدِيث، إِنَّمَا أكره هَذِه الْمسَائِل."],[740,"إِلَى هَهُنَا عَن الْمَرْوذِيّ."],[741,"[صالح]"],[742,"٣١١"],[743,"- حَدثنَا أَبُو عوَانَة يَعْقُوب بن إِسْحَاق، قَالَ: حَدثنَا صَالح بن أَحْمد بن حَنْبَل أَبُو الْفضل، بِدِمَشْق، قَالَ: حَدثنَا أبي، قَالَ:"],[744,"حَدثنَا عَفَّان، قَالَ: حَدثنَا يحيى بن سعيد، قَالَ: سَأَلت شُعْبَة، وسُفْيَان بن سعيد، وسُفْيَان بن عُيَيْنَة، وَمَالك بن أنس، عَن الرجل الَّذِي لَا يحفظ، أويتهم فِي الحَدِيث؟ قَالُوا جَمِيعًا بَين أمره."],[745,"٣١٢"],[746,"- قَالَ حَدثنِي أبي، قَالَ: حَدثنَا يحيى بن آدم، قَالَ: قَالَ حَامِد بن يُونُس لَو شِئْت أَن يحدثني عِيسَى الحناط بِكُل مَا يصنع"],[747,"أهل الْمَدِينَة، حَدثنِي بِهِ."],[748,"٣١٣"],[749,"- قَالَ: حَدثنِي أبي، قَالَ: حَدثنَا يحيى بن آدم، قَالَ: حَدثنِي مُعلى بن خَالِد، قَالَ: قَالَ لي شُعْبَة لَو شِئْت لحدثني أَبُو هَارُون الْعَبْدي، عَن أبي سعيد الْخُدْرِيّ بِكُل شَيْء أرى أهل وَاسِط يضعونه، لفعل أَو لفَعَلت. ٣١٤ - قَالَ: حَدثنِي أبي، قَالَ: حَدثنَا يحية بن آدم، قَالَ: حَدثنِي ابْن إِدْرِيس، عَن زَكَرِيَّا بن أبي زَائِدَة، قَالَ: رَأَيْت الشّعبِيّ أَخذ"],[750,"بأذن أبي صَالح صَاحب الْكَلْبِيّ، فَقَالَ: أتفسر الْقُرْآن وَأَنت لَا تقْرَأ الْقُرْآن."],[751,"٣١٥"],[752,"- قَالَ: حَدثنِي أبي، قَالَ: حَدثنَا يحيى، قَالَ: حَدثنَا مفضل، عَن مُغيرَة، أَنه كَانَ يَقُول: إِنَّمَا كَانَ أَبُو صَالح صَاحب الْكَلْبِيّ، يعلم الصّبيان، ويضعف تَفْسِيره، قَالَ: كتبت أَصَابَهَا، قَالَ: نعجب مِمَّن روى عَنهُ."],[753,"٣١٦"],[754,"- حَدثنَا أَبُو عوَانَة، قَالَ: حَدثنَا صَالح بن أَحْمد، قَالَ: حَدثنِي أبي، قَالَ: حَدثنَا عَفَّان، قَالَ: حَدثنَا معَاذ، قَالَ: قَالَ الْأَشْعَث: مَا رَأَيْت هشاما عِنْد الْحسن قطّ، قَالَ: فَقيل لَهُ: إِن عمروا يَقُول هَذَا، وَأَنت إِن قلته قويته عَلَيْهِ أَو صدق أَو نَحوه هَذَا، قَالَ: لَا أَقُول هَذَا، وَلَا أَعُود لهَذَا."],[755,"٣١٧"],[756,"- قَالَ: حَدثنِي أبي، قَالَ: حَدثنَا عَفَّان، قَالَ: حَدثنَا همام، قَالَ: قدم علينا أَبُو دَاوُد الْأَعْمَى، فحدثنا عَن زيد بن أَرقم، وَعَن الْبَراء بن عَازِب، وَعَن أَصْحَاب رَسُول الله صلى الله عليه وآله وسلم، قَالَ:"],[757,"فَقُلْنَا لِقَتَادَة: إِن أَبَا دَاوُد يحدثنا، فَذكر هَؤُلَاءِ، فَقَالَ: هَذَا رجل كَذَّاب، إِنَّمَا كَانَ يَتَكَفَّف النَّاس قبل طاعون الجارف."],[758,"٣١٨"],[759,"- قَالَ: حَدثنِي أبي، قَالَ: حَدثنَا عَفَّان، قَالَ: حَدثنَا همام، قَالَ: حَدثنِي مطر، قَالَ: لَقِيَنِي عَمْرو بن عبيد، فَقَالَ: وَالله إِنِّي وَإِيَّاك لعلى أَمر وَاحِد، قَالَ: وَكذب وَالله، إِنَّمَا دَعْنِي على الأَرْض."],[760,"قَالَ: وَقَالَ مطر: وَالله مَا أصدقه فِي شَيْء."],[761,"٣١٩"],[762,"- قَالَ حَدثنِي أبي، قَالَ: حَدثنَا عَفَّان، قَالَ: حَدثنَا حَمَّاد بن سَلمَة، قَالَ: كَانَ حميد من أكفهم عَنهُ، قَالَ: فجَاء ذَات يَوْم إِلَى حميد، فحدثنا حميد بِحَدِيث، قَالَ: فَقَالَ لَهُ عَمْرو: كَانَ الْحسن يَقُوله، قَالَ: فَقَالَ لي حميد لَا تَأْخُذ عَن هَذَا شَيْئا، فَإِنَّهُ يكذب على الْحسن، كَانَ يَأْتِي الْحسن بَعْدَمَا أسن، فَيَقُول: يَا أَبَا سعيد، أَلَيْسَ تَقول كَذَا وَكَذَا؟ للشَّيْء الَّذِي لَيْسَ هُوَ من قَوْله، قَالَ: فَيَقُول الشَّيْخ: بِرَأْسِهِ هَكَذَا."],[763,"٣٢٠"],[764,"- قَالَ حَدثنِي أبي، قَالَ: حَدثنَا عَفَّان، قَالَ: حَدثنَا حَمَّاد بن سَلمَة، عَن عَليّ بن زيد، قَالَ: لم يسمع الْحسن من أبي هُرَيْرَة."],[765,"٣٢١"],[766,"- قَالَ حَدثنِي أبي، قَالَ: حَدثنَا عَفَّان، قَالَ: حَدثنَا وهيب، قَالَ: قَالَ أَيُّوب: لم يسمع الْحسن من أبي هُرَيْرَة."],[767,"٣٢٢"],[768,"- قَالَ حَدثنِي أبي، قَالَ: حَدثنَا أَبُو قطن، قَالَ: قَالَ المَسْعُودِيّ: مَا أدركنا أحدا كَانَ أَقُول بقول الشِّيعَة من عدي بن ثَابت."],[769,"٣٢٣"],[770,"- قَالَ حَدثنِي أبي، قَالَ حَدثنَا عَفَّان، قَالَ: حَدثنَا وهيب، قَالَ: لما مَاتَ عبد الْمجِيد، قَالَ لنا أَيُّوب: الزموا هَذَا الْفَتى، يَعْنِي عبد الْوَهَّاب الثَّقَفِيّ."],[771,"٣٢٤"],[772,"- قَالَ حَدثنِي أبي، قَالَ حَدثنَا عَفَّان، قَالَ: حَدثنَا بشر بن الْمفضل، قَالَ: حَدثنَا ابْن عون، قَالَ: لما مَاتَ مُحَمَّد، قُلْنَا: من لنا؟ قَالَ: فَقُلْنَا أَيُّوب."],[773,"٣٢٥"],[774,"- قَالَ حَدثنِي أبي، قَالَ: حَدثنَا معَاذ، قَالَ، حَدثنَا ابْن عون، قَالَ: ذكرت لإِبْرَاهِيم رجلَيْنِ من السبائية، يَعْنِي الْمُغيرَة بن سعيد، وَأَبا عبد الرَّحِيم، قد عرفهما، قَالَ: احذروهما، فَإِنَّهُمَا كذابان."],[775,"٣٢٦"],[776,"- قَالَ حَدثنِي أبي، قَالَ: حَدثنَا معَاذ، قَالَ: حَدثنَا إِسْمَاعِيل بن إِبْرَاهِيم، قَالَ: جَاءَنِي عبد الْعَزِيز الدّباغ، فَقَالَ: إِنِّي"],[777,"قد أنْكرت وَجه ابْن عون، فَلَا أَدْرِي مَا شَأْنه؟ قَالَ: فَذَهَبت مَعَه إِلَى ابْن عون، فَقلت: أَبَا عون، مَا شان عبد الْعَزِيز؟ قَالَ: أَخْبرنِي قُتَيْبَة صَاحب الْحَرِير، أَنه رَآهُ يمشي مَعَ عَمْرو بن عبيد فِي السُّوق، قَالَ: فَقَالَ لَهُ عبد الْعَزِيز: إِنَّمَا سَأَلته عَن شَيْء، وَالله مَا أحب رَأْيه، قَالَ، وَسَأَلَهُ أَيْضا."],[778,"٣٢٧"],[779,"- قَالَ: حَدثنِي أبي، قَالَ: حَدثنَا الْأسود بن عَامر، قَالَ: أخبرنَا أَبُو بكر يَعْنِي ابْن عَيَّاش، عَن عَاصِم، قَالَ: كَانَ أَبُو عبد الرَّحْمَن، يَقُول: لَا يجالسني حروري، وَلَا يجالسني رجل جَالس شقيقا الضَّبِّيّ، قَالَ أَبُو بكر وَكَانَ مخاصما، وَقَالَ:"],[780,"[*]"],[781,"وَلَا تجالسوا الْقصاص، إِلَّا أَبَا الْأَحْوَص، فَإِنَّهُ لَا يتهم من أَصْحَاب عبد الله."],[782,"إِلَى هَهُنَا عَن صَالح بن أَحْمد."],[783,"[*]"],[784,"٣٢٨"],[785,"- حَدَّثَنَا أَبُو عَوَانَةَ، قَالَ: حَدَّثَنَا يَعْقُوبُ بْنُ سُفْيَانَ الْفَارِسِيُّ، بِفَسَا، قَالَ: حَدَّثَنَا إِبْرَاهِيمُ أَبُو الْمُنْذِرِ الْحِزَامِيُّ، قَالَ: حَدَّثَنِي مَعْنُ بْنُ عِيسَى، قَالَ: كَانَ مَالِكٌ يَقُولُ: لَا يُؤْخَذُ الْعِلْمُ مِنْ أَرْبَعَةٍ، وَيُؤْخَذُ مِمَّنْ سِوى ذَلِكَ لَا يُؤْخَذُ مِنْ سَفِيهٍ مُعْلِنٍ بِالسَّفَهِ، وَإِنْ كَانَ أَرْوَى النَّاسِ، وَلَا يُؤْخَذُ مِنْ كَذَّابٍ يَكْذِبُ فِي أَحَادِيثِ"],[786,"النَّاسِ، إِذَا جُرِّبَ ذَلِكَ عَلَيْهِ، وَإِنْ كَانَ لَا يُتَّهَمُ أَنْ يَكْذِبَ عَلَى رَسُولِ اللَّهِ صلى الله عليه وآله وسلم، وَلَا مِنْ صَاحِبِ هَوَى يَدْعُو النَّاسَ إِلَى هَوَاهُ، وَلَا مِنْ شَيْخٍ لَهُ فَضْلٌ وَعِبَادَةٌ إِذَا كَانَ لَا يَعْرِفُ مَا يُحَدِّثُ بِهِ."],[787,"قَالَ إِبْرَاهِيمُ: فَذَكَرْتُ هَذَا الْحَدِيثَ لِمُطَّرِّفِ بْنِ عَبْدِ اللَّهِ الْيَسَارِيِّ، فَقَالَ: لَا أَدْرِي مَا هَذَا، وَلَكِنْ أَشْهَدُ لَسَمِعْتُ مَالِكَ بْنَ أَنَسٍ، يَقُولُ: لَقَدْ أَدْرَكْتُ بِهَذَا الْبَلَدِ، يَعْنِي الْمَدِينَةَ، مَشْيَخَةً لَهُمْ فَضْلٌ، وَصَلَاحٌ، وَعِبَادَةٌ، يُحَدِّثُونَ، مَا سَمِعْتُ مِنْ وَاحِدٍ مِنْهُمْ حَدِيثًا قَطُّ، فَقِيلَ لَهُ: وَلِمَ يَا أَبَا عَبْدِ اللَّهِ؟ قَالَ: لَمْ يَكُونُوا يَعْرِفُونَ مَا يُحَدِّثُونَ."],[788,"٣٢٩"],[789,"- سَمِعت يَعْقُوب، يَقُول: سَمِعت الْمَكِّيّ بن إِبْرَاهِيم، قَالَ: ضرب مَالك بن أنس فِي سنة سبع وَأَرْبَعين وَمِائَة، ضربه سُلَيْمَان بن جَعْفَر بن سُلَيْمَان بن عَليّ سبعين سَوْطًا."],[790,"٣٣٠"],[791,"- سَمِعت يَعْقُوب، قَالَ: وَسمعت الْمَكِّيّ بن إِبْرَاهِيم، يَقُول: جَلَست إِلَى مُحَمَّد بن إِسْحَاق، وَكَانَ يخضب بِالسَّوَادِ، فَذكر أَحَادِيث فِي الصّفة، فنفرت مِنْهَا، فَلم أعد إِلَيْهِ."],[792,"٣٣١"],[793,"- سَمِعت يَعْقُوب بن سُفْيَان، يَقُول: سَمِعت عبد الله بن أَحْمد بن ذكْوَان، قَالَ: قَالَ يحيى بن معِين: مُحَمَّد بن الْمُبَارك شيخ"],[794,"الْبَلَد بعد أبي مسْهر، قَالَ عبد الله: وَكَانَ لَا يحدث عَن عَمْرو بن وَاقد، حَتَّى مَاتَ مَرْوَان بن مُحَمَّد الطاطري، قَالَ: ومروان كَانَ يَقُول: عَمْرو بن وَاقد كَذَّاب."],[795,"٣٣٢"],[796,"- حَدثنَا يَعْقُوب، وَسَأَلت عبد الرَّحْمَن إِبْرَاهِيم، عَن عَمْرو بن وَاقد، قَالَ: لم يكن شُيُوخنَا يحدثُونَ عَنهُ، وَكَأَنَّهُ لم يشك أَنه كَانَ كذابا."],[797,"٣٣٣"],[798,"- سَمِعت يَعْقُوب، قَالَ: سَمِعت زيدا يَعْنِي ابْن الْمُبَارك،"],[799,"يَقُول: مَا التقيت مَعَ ابْن الْمَدِينِيّ."],[800,"إِلَّا يَقُول لي: مَا حَال غياث؟ كَأَنَّهُ كَانَ كذابا."],[801,"٣٣٤"],[802,"- سَمِعت يَعْقُوب، يَقُول: سَمِعت أَبَا الْأسود، وَقَالَ لَهُ رجل: إِن ابْن بكير يتَكَلَّم فِي أبي صَالح، فأيش تَقول فِيهِ؟ فَقَالَ: أَبُو صَالح إِذا قَالَ لكم بِمصْر، اكتبوا عَن فلَان، فَاكْتُبُوا واتركوا مَا سواهُ."],[803,"٣٣٥"],[804,"- سَمِعت يَعْقُوب، يَقُول: سَمِعت ابْن بكير، يَقُول: إِنَّمَا نُحدث عَن عَنْبَسَة مَجْنُون أَحمَق، قَالَ: وَكَانَ يجيئني، وَلم يكن موضعا للكتابة أَن يكْتب عَنهُ."],[805,"[الميموني]"],[806,"٣٣٦"],[807,"- حَدَّثَنَا أَبُو عوَانَة يَعْقُوب بن إِسْحَاق، قَالَ: حَدَّثَنَا عَبْدُ الْمَلِكِ بْنُ عَبْدِ الْحَمِيدِ بْنِ عَبْدِ الْحَمِيدِ بْنِ مَيْمُونِ بْنِ مِهْرَانَ أَبُو الْحَسَنِ الْمَيْمُونِيُّ، وَسَأَلْتُهُ، قَالَ: حَدَّثَنَا أَحْمَدُ بْنُ حَنْبَلٍ، قَالَ: حَدَّثَنَا عَبْدُ الرَّزَّاقِ، عَنْ مَعْمَرٍ، قَالَ: ذَكَرْتُ لِعَمْرِو بْنِ دِينَارٍ أَبَا الشَّعْثَاءِ، وَمَا تَنْتَحِلُهُ الْإِبَاضِيَّةُ، فَقَالَ: مَا سَمِعْتُ مِنْهُ فِي هَذَا شَيْئًا قَطُّ، قَالَ: فَجَاءَ رَجُلٌ، فَقَالَ: يَا أَبَا مُحَمَّدٍ، مَا كَانَ أَبُو الشَّعْثَاءِ يَقُولُ فِي كَذَا،"],[808,"فَنَظَرَ إِلَيَّ وَتَبَسَّمَ، فَقَالَ: إين أزين شان أست."],[809,"٣٣٧"],[810,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: حَدَّثَنَا أَحْمَدُ بْنُ حَنْبَلٍ، قَالَ: حَدثنَا إِبْرَاهِيم يَعْنِي ابْن خَالِد الصَّنْعَانِيّ، عَن أُميَّة بن شبْل، عَن معمر، عَن أَيُّوب، قَالَ: قدم علينا عِكْرِمَة، فَاجْتمع النَّاس عَلَيْهِ حَتَّى أصعد فَوق ظهر بَيت."],[811,"٣٣٨"],[812,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: حَدَّثَنَا أَحْمَدُ بْنُ حَنْبَلٍ، قَالَ: حَدثنَا إِبْرَاهِيم، عَن أُميَّة، عَن عَمْرو بن مُسلم، قَالَ: قدم عِكْرِمَة على"],[813,"طَاوُوس، فَحَمله على نجيب ثمن سِتِّينَ دِينَارا، وَقَالَ: أَلا أَشْتَرِي علم هَذَا العَبْد بستين دِينَارا؟"],[814,"٣٣٩"],[815,"- حَدثنَا الْمَيْمُونِيّ. قَالَ: حَدثنَا أَحْمد بن حَنْبَل، قَالَ: حَدثنَا حجاج، قَالَ: سَمِعت شُعْبَة، عَن خَالِد، قَالَ: قَالَ عِكْرِمَة، لرجل وَهُوَ يسْأَله: مَا لَك أجبلت؟ يَعْنِي نفيت، قَالَ شُعْبَة: ثمَّ حَدثنِي أَيُّوب، قَالَ: كَانَ خَالِد يسْأَل عِكْرِمَة، فَسكت خَالِد، فَقَالَ عِكْرِمَة: مَا لَك أجلبت؟ يَعْنِي نقيت."],[816,"٣٤٠"],[817,"- حَدثنَا الْمَيْمُونِيّ، حَدثنَا عَمْرو بن مَرْزُوق الْبَصْرِيّ، قَالَ: حَدثنَا شُعْبَة، عَن عَمْرو بن مرّة، عَن سعيد بن الْمسيب، قَالَ: سَأَلَهُ رجل عَن شَيْء من كتاب الله، فَلم يقل لَهُ فِيهِ شَيْئا، ثمَّ قَالَ لَهُ: سل عَن ذَاك، من يزْعم أَنه لَا يخفى عَلَيْهِ من كتاب الله شَيْء، يَعْنِي عِكْرِمَة."],[818,"٣٤١"],[819,"- حَدَّثَنَا الْمَيْمُونِيُّ، قَالَ: سَمِعْتُ أَحْمَدَ بْنَ حَنْبَلٍ، يَقُولُ: سَمِعْتُ يَحْيَى، قَالَ: حَدَّثَنِي سُفْيَانُ، بِالْكُوفَةِ، فِي حَيَاةِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عُمَرَ فِي بَيْضِ النَّعَامِ، قَالَ: لَيْسَ هَذَا من حَدِيثه الْعَتِيق"],[820,"٣٤٢"],[821,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: حَدثنَا أَحْمد بن حَنْبَل، قَالَ: حَدثنَا حجاج، قَالَ: قَالَ شُعْبَة: قد أدْرك رفيع عليا، وَلكنه لم يسمع مِنْهُ، يَعْنِي أَبَا الْعَالِيَة."],[822,"٣٤٣"],[823,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: حَدثنَا أَحْمد، قَالَ: حَدثنَا سُفْيَان، قَالَ: قَالَ ابْن شبْرمَة: لَيْسَ بِمَكَّة مثله، يَعْنِي هِشَام بن حُجَيْر."],[824,"٣٤٤"],[825,"- قَالَ حَدثنَا أَحْمد، قَالَ: حَدثنَا عبد الصَّمد، قَالَ: حَدثنَا حَرْب، قَالَ: قَالَ يحيى: كل شَيْء عَن أبي سَلام، فَإِنَّمَا هُوَ كتاب."],[826,"٣٤٥"],[827,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: وَحدثنَا أَبُو عبد الله بِحَدِيث استحسنه، عَن مُحَمَّد بن إِسْحَاق، فَقلت لَهُ: يَا أَبَا عبد الله، مَا أحسن هَذِه الْقَصَص الَّتِي يَجِيء بهَا ابْن إِسْحَاق؟ فَتَبَسَّمَ إِلَيّ مُتَعَجِّبا."],[828,"٣٤٦"],[829,"- وَسَأَلَ رجل أَبَا عبد الله عَن حَدِيث، فَقَالَ: هُوَ عَن صَالح بن أبي الْأَخْضَر، إيش تصنع بِهِ، أودعهُ إِحْدَى الْكَلِمَتَيْنِ."],[830,"٣٤٧"],[831,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: حَدثنَا أَبُو عبد الله، قَالَ: حَدثنَا عبد الحميد بن عبد الرَّحْمَن أَبُو يحيى، ثمَّ قَالَ لنا: كَانَ صَدُوقًا فِي الحَدِيث، إِن شَاءَ الله، وَلَكنَّا كُنَّا نأتيه بالكوفه، لَيْسَ عِنْده إِلَّا صبيان، وَكَانَ رُبمَا جَاءَ إِلَى أبي مُعَاوِيَة، فَقَالَ لَهُ أَبُو مُعَاوِيَة: الْكَلَام الَّذِي يمازحه، ثمَّ قَالَ أَبُو عبد الله: يفحش لَهُ أَن أَتكَلّم بِهِ، فَقلت لَهُ: فابنه هَذَا قَالَ: لَا أَدْرِي، ثمَّ نفض يَده فِي وَجْهي غير مرّة يَدْفَعهُ."],[832,"٣٤٨"],[833,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سَأَلُوهُ، يَعْنِي أَحْمد بن حَنْبَل، عَن"],[834,"ابْن تدرس، فَقَالَ لَا أعرفهُ."],[835,"٣٤٩"],[836,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سَأَلته فِيمَا بيني وَبَينه، واستفهمته واستثبته، قلت: يَا أَبَا عبد الله، قد بلينا لهَؤُلَاء الْجَهْمِية، مَا تَقول فِي من قَالَ: إِن الله لَيْسَ على الْعَرْش؟ قَالَ: كَلَامهم كلهم يَدُور على الْكفْر."],[837,"قلت: مَا تَقول فِيمَن قَالَ: إِن الله لم يكلم مُوسَى؟ قَالَ: كَافِر لَا يشك فِيهِ."],[838,"قلت: من قَالَ إِن أَسمَاء الله محدثة؟ قَالَ: كَافِر، ثمَّ قَالَ لي: الله من أَسْمَائِهِ، فَمن قَالَ: إِنَّهَا محدثة، فقد زعم أَن الله مَخْلُوق، وَأَقْبل يعظم أَمرهم، وَيكفر، وَقَرَأَ: ﴿وَاللَّهَ رَبَّكُمْ وَرَبَّ آبَائِكُمُ الأَوَّلِينَ﴾ [الصافات: ١٢٦] ."],[839,"وَذكر آيَة أُخْرَى، قلت: من قَالَ إِن الله كَانَ وَلَا علم فَتغير وَجهه فِي هَذَا كُله، وَكَانَ فِي هَذَا أَشد تغيرا، وَأكْثر غيظا."],[840,"ثمَّ قَالَ لي: كَافِر، وَقَالَ: فِي كل يَوْم أزداد فِي الْقَوْم بَصِيرَة."],[841,"٣٥٠"],[842,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: وَسمعت أَبَا عبد الله، يَقُول: قَالَ شُعْبَة: لم يلق قَتَادَة أَبَا رَافع، إِنَّمَا كتب عَن خلاس عَنهُ، وسمعته"],[843,"يَقُول: يَقُولُونَ إِن قَتَادَة لم يسمع من معَاذَة."],[844,"٣٥١"],[845,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: أكبر ظَنِّي أَن أَبَا عبد الله ذكر عبد الله بن رَجَاء، فوثقه وفضله، قلت: فَمَا قصَّته؟ قَالَ: كَانَ ثمَّ غلط، وَوهم وَقد حدث يَوْمًا بِحَدِيث، فَقيل لَهُ: غَلطت فِيهِ، فَقَالَ: الله الْمُسْتَعَان، على غلطنا فِي غَيره، أَيْضا أَو قد غلطنا."],[846,"قَالَ لي أَبُو عبد الله: فَإِذا كَانَ الشَّيْخ يقر بِهَذَا تعلم أَنه سليم، وَرُبمَا خرج الشَّيْء من الْإِنْسَان، فَيشْهد لَهُ الْقلب بِالصّدقِ."],[847,"٣٥٢"],[848,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سَأَلته عَن ابْني بُرَيْدَة، فَقَالَ:"],[849,"سُلَيْمَان أحلى فِي الْقلب، وَكَأَنَّهُ أصَحهمَا حَدِيثا، وَعبد الله لَهُ أَشْيَاء إِنَّا ننكرها من حسنها، وَهُوَ جَائِز الحَدِيث."],[850,"٣٥٣"],[851,"- والفرات بن السَّائِب قريب من مُحَمَّد بن زِيَاد الطَّحَّان فِي مَيْمُون، يتهم بِمَا يتهم بِهِ ذَلِك."],[852,"٣٥٤"],[853,"- والفرات بن سلمَان ثِقَة صَدُوق."],[854,"٣٥٥"],[855,"- وَأَبُو الْمليح، ثِقَة، ضَابِط لحديثه، صَدُوق، وَهُوَ عِنْدِي، أضبط من جَعْفَر بن برْقَان، وجعفر بن برْقَان، ثِقَة ضَابِط لحَدِيث مَيْمُون، وَحَدِيث يزِيد بن الْأَصَم، وَهُوَ فِي حَدِيث الزُّهْرِيّ يضطرب وَيخْتَلف فِيهِ."],[856,"٣٥٦"],[857,"- وَعَاصِم بن كُلَيْب، ثِقَة."],[858,"٣٥٧"],[859,"- وَعَاصِم بن بَهْدَلَة، ثِقَة، وَذكره بقرآن، وَصَلَاح، وَفضل، وَصَالح الحَدِيث، وَالْأَعْمَش عِنْد الْكُوفِيّين أكبر مِنْهُ."],[860,"٣٥٨"],[861,"- وَعَاصِم الْأَحْوَال، من الْحفاظ للْحَدِيث، ثِقَة."],[862,"٣٥٩"],[863,"- وَقَالَ: عبد الْوَهَّاب ضَعِيف الحَدِيث، مُضْطَرب."],[864,"٣٦٠"],[865,"- وجعفر بن مُحَمَّد ضَعِيف الحَدِيث."],[866,"مُضْطَرب."],[867,"٣٦١"],[868,"- وَأَبوهُ أَبُو جَعْفَر مُحَمَّد بن عَليّ بن حُسَيْن ثِقَة، قوي الحَدِيث."],[869,"٣٦٢"],[870,"- ومجالد عَن الشّعبِيّ وَغَيره، ضَعِيف الحَدِيث."],[871,"٣٦٣"],[872,"- وزَكَرِيا عَن الشّعبِيّ وَغَيره، جيد الحَدِيث، ثِقَة."],[873,"٣٦٤"],[874,"- وعلقمة بن مرْثَد كَانَ يتهم بالإرجاء، وَكَانَ ثِقَة فِي حَدِيثه، ضابطا."],[875,"٣٦٥"],[876,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: قَالَ لي أَبُو عبد الله: كَانَ ابْن مهْدي إِذا ذكر حَمَّاد بن زيد، قَالَ: شَيخنَا، وَشَيخنَا كَانَ ثبتا فِي السّنة."],[877,"قَالَ أَبُو عبد الله: وَلم يكن لَهُ كتاب، حَدِيثه حفظ كُله."],[878,"٣٦٦"],[879,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: وَسمعت أَبَا عبد الله، يَقُول: قَالَ جرير فِي حَدِيث الْأَعْمَش: كُنَّا نلزقها."],[880,"٣٦٧"],[881,"- قَالَ: سُلَيْمَان بن أبي مُسلم، الْأَحول، ثِقَة، جيد الحَدِيث، وَقد روى عَنهُ ابْن عُيَيْنَة."],[882,"٣٦٨"],[883,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: قَالَ لي: وَكَانَ يحيى، وَعبد الرَّحْمَن لَا يحدثان عَن جَابر الْجعْفِيّ بِشَيْء."],[884,"قَالَ أَبُو عبد الله: وَكَانَ جَابر أَهلا لذاك."],[885,"٣٦٩"],[886,"- قَالَ: وَأَبُو الزبير أعجب إِلَيّ فِي الحَدِيث من أبي سُفْيَان طَلْحَة بن نَافِع."],[887,"٣٧٠"],[888,"- وَقَالَ لي: الْأسود بن شَيبَان من خِيَار عباد الله، كَانَ يَقُول: إِذا اجْتَمعُوا عِنْده."],[889,"أما أَنا فلي حَاجَة، أُرِيد أَن أُصَلِّي، وَقَالَ: تعلم أَنه لم يكن فِي قلبه أَي رِيَاء."],[890,"٣٧١"],[891,"- قَالَ: وَكَانَ مَالك من أثبت النَّاس، وَقد كَانَ يُخطئ."],[892,"٣٧٢"],[893,"- قَالَ أَبُو عبد الله: المَسْعُودِيّ صَالح الحَدِيث، وَمن أَخذ عَنهُ أول."],[894,"فَهُوَ صَالح الْأَخْذ."],[895,"٣٧٣"],[896,"- وَسَأَلته عَن عقيل. فَقَالَ: صَالح الحَدِيث، رِوَايَته مثل رِوَايَة"],[897,"أَصْحَابه، لَا بَأْس بِهِ."],[898,"٣٧٤"],[899,"- عَليّ بن أبي طَلْحَة، لَهُ أَشْيَاء مُنكرَات، رجل من أهل حمص."],[900,"٣٧٥"],[901,"- على بن الْمُبَارك، مَا يحدثه بَأْس."],[902,"٣٧٦"],[903,"- سُلَيْمَان بن بِلَال صَالح الحَدِيث."],[904,"٣٧٧"],[905,"- شريك بن أبي نمر صَالح الحَدِيث."],[906,"٣٧٨"],[907,"- الزبير بن عبد الله، عَن جَعْفَر بن مُصعب، لَا نعرفهما جَمِيعًا."],[908,"٣٧٩"],[909,"- الْمِقْدَام بن شُرَيْح، ثِقَة."],[910,"٣٨٠"],[911,"- إِسْرَائِيل صَالح الحَدِيث."],[912,"٣٨١"],[913,"- وَأَشْعَث بن أبي الشعْثَاء وَهُوَ ابْن سليم، الْمحَاربي، وَأَبوهُ"],[914,"رجل من أَصْحَاب عبد الله، صَالح الحَدِيث."],[915,"٣٨٢"],[916,"- أَبُو عَطِيَّة. ثِقَة."],[917,"٣٨٣"],[918,"- ابْن الْأَصْبَهَانِيّ، صَالح الحَدِيث."],[919,"٣٨٤"],[920,"- مُجَاهِد بن وردان، لَهُ شَيْء يسير."],[921,"٣٨٥"],[922,"- أَبُو الرِّجَال، صَاحب عمْرَة، صَالح الحَدِيث."],[923,"٣٨٦"],[924,"- مُحَمَّد بن عبد الرَّحْمَن بن زُرَارَة، صَالح الحَدِيث."],[925,"٣٨٧"],[926,"- سَالم الدوسي، لَا أَدْرِي."],[927,"٣٨٨"],[928,"- مُعَاوِيَة بن صَالح، مَا أعلم إِلَّا خيرا."],[929,"٣٨٩"],[930,"- حبيب الْمعلم، ثِقَة."],[931,"٣٩٠"],[932,"- أَبُو المهزم يزِيد، أما شُعْبَة لم يرو عَنهُ، وَحَمَّاد بن سَلمَة يروي عَنهُ."],[933,"٣٩١"],[934,"- وَأَبُو بكر بن حَفْص، ثِقَة."],[935,"٣٩٢"],[936,"- وَإِبْرَاهِيم بن مَيْمُون، لَا نعرفه."],[937,"٣٩٣"],[938,"- طَلْحَة بن يحيى، صَالح الحَدِيث."],[939,"٣٩٤"],[940,"- يزِيد بن إِبْرَاهِيم، ثِقَة."],[941,"٣٩٥"],[942,"- مُغيرَة بن زِيَاد. مَا أَدْرِي."],[943,"٣٩٦"],[944,"- وَأُسَامَة بن زيد عَلَيْهِ عَام النَّاس، قد رووا عَنهُ، إِلَّا يحيى بن سعيد تَركه."],[945,"٣٩٧"],[946,"- إِبْرَاهِيم بن الْفضل، مَا أَدْرِي."],[947,"٣٩٨"],[948,"- دَاوُد الأودي، هاه."],[949,"٣٩٩"],[950,"- عمرَان بن حدير، ثِقَة."],[951,"٤٠٠"],[952,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: وسمعته يَقُول: لم أر أحدا أعلم بهَا من يحيى بن سعيد، يَعْنِي بالمناسك."],[953,"٤٠١"],[954,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سَأَلت خلفا، قلت: قعد أحد عَن جَابر الْجعْفِيّ، فَقَالَ: لَا أعلمهُ، كَانَ سُفْيَان بن عُيَيْنَة من أَشَّدهم قولا"],[955,"فِيهِ، وَقد حدث عَنهُ، وَإِنَّمَا كَانَت عِنْده ثَلَاثَة أَحَادِيث."],[956,"قلت: صَحَّ عَنهُ شَيْء، إِنَّه يُؤمن بالرجعة؟ قَالَ: لَا، وَلكنه من شيعَة عَليّ، وَشعْبَة، وَالثَّوْري، وَالنَّاس يحدثُونَ عَنهُ، إِلَّا هَؤُلَاءِ لَيْسَ يحدثُونَ عَنهُ بِتِلْكَ الْأَشْيَاء الَّتِي يجمع فِيهَا قاسما، وسالما، وَجَمَاعَة، هَكَذَا سَبْعَة، ثَمَانِيَة، بلَى، إيش يحدث عَنهُ بِهَذِهِ الْأَشْيَاء؟ ٤٠٢ - حَدثنَا الْمَيْمُونِيّ، قَالَ: سَمِعت هَارُون بن مَعْرُوف، قَالَ: سَمِعت عبد الله بن وهب: يَقُول: قَالَ لي عبد الرَّحْمَن بن مهْدي: أكتب لي من أَحَادِيث عَمْرو، فَكتبت لَهُ مِائَتي حَدِيث، حدثته بهَا."],[957,"٤٠٣"],[958,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: قلت ليحيى بن معِين: الْأَحَادِيث عَن النَّبِي صلى الله عليه وآله وسلم فِي كَرَاهَة الْحجامَة للصَّائِم، كَيفَ تَأْوِيلهَا؟ قَالَ: جِيَاد كلهَا، قُلْنَا فَمَا يَقُولُونَ: مضطربة؟ قَالَ."],[959,"أَن لَا أَقُول إِن هَذِه الْأَحَادِيث مضطربة."],[960,"٤٠٤"],[961,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سَمِعت يحيى، يَقُول: مُحَمَّد بن إِسْحَاق."],[962,"٤٠٥"],[963,"- سألناه عَن عبد الرَّحْمَن بن إِسْحَاق، قَالَ: الْكُوفِي؟ ضَعِيف."],[964,"٤٠٦"],[965,"- وَعبد الرَّحْمَن بن إِسْحَاق الْبَصْرِيّ، الَّذِي يروي عَن الزُّهْرِيّ لَيْسَ بِهِ بَأْس."],[966,"٤٠٧"],[967,"- حَدَّثَنَا الْمَيْمُونِيُّ، قَالَ قُلْتُ لأَبِي زَكَرِيَّا يَحْيَى، إِسْمَاعِيلَ بْنِ زَكَرِيَّا، عَنِ الأَعْمَشِ، عَنْ حَبِيبِ بْنِ أَبِي ثَابِتٍ، عَنْ سَعِيدِ بْنِ"],[968,"جُبَيْرٍ، عَنِ ابْنِ عُمَرَ، وَابْنِ عَبَّاسٍ، قَالا: «إِذَا آلَى الرَّجُلُ مِنَ امْرَأَتِهِ، فَمَضَتْ أَرْبَعَةُ أَشْهُرٍ، فَهِيَ تَطْلِيقَةٌ بَائِنَةٌ»"],[969,"قلت عَنْهُمَا خلاف ذَا؟ قَالَ: نعم، سُفْيَان، وَشعْبَة جَمِيعًا يرويان خلاف ذَا، وَذَا الحَدِيث خطأ."],[970,"قلت مِمَّن أُتِي، قَالَ: إِسْمَاعِيل بن زَكَرِيَّا، هُوَ ضَعِيف الحَدِيث."],[971,"قلت: فَمِنْهُ أُتِي؟ لَا هُوَ مَشْهُور عَن الْأَعْمَش."],[972,"قلت: فَمن الْأَعْمَش أُتِي؟ قَالَ: نعم، كَذَا أَظن، أَنه من الْأَعْمَش."],[973,"٤٠٨"],[974,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: ذكر اللَّيْث بن أبي سليم، قَالَ: ضَعِيف الحَدِيث، عَن طَاوُوس، وَإِذا جمع طَاوُوس وَغَيره زِيَادَة، هُوَ ضَعِيف."],[975,"٤٠٩"],[976,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سَمِعت أَبَا عبد الله بن حَنْبَل، قَالَ: حَدثنَا مَرْوَان بن شُجَاع، قَالَ أَبُو عبد الله: شيخ صَدُوق."],[977,"٤١٠"],[978,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: حَدثنَا الحصني، قَالَ: حَدثنَا معقل، قَالَ: أتيت مُحَمَّد بن إِسْحَاق فَسَمعته يتَكَلَّم فِي الْقدر، فَلم أعد إِلَيْهِ."],[979,"٤١١"],[980,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: وسمعته يَقُول: مدرك بن عمَارَة رجل مَعْرُوف، وَذكر مدرك رجل آخر، قَالَ: لَا يعرف."],[981,"٤١٢"],[982,"- قَالَ: سَأَلُوهُ عَن سَماع أبي سَلمَة، عَن أَبِيه، فَسَمعته يَقُول: مَاتَ أَبوهُ وَهُوَ صَغِير، كَانَ أَبُو سَلمَة من أحدثهم، ثمَّ قَالَ: لَيْسَ فِي الْقَوْم أَكثر من أبي سَلمَة، قلت: فِي كَثْرَة الرِّوَايَة؟ قَالَ: فِي كَثْرَة مَا يروي، وجالس ابْن عَبَّاس، وَكثر من شان أبي سَلمَة يَوْمئِذٍ."],[983,"٤١٣"],[984,"- سَمِعت الْمَيْمُونِيّ، قَالَ: سُئِلَ أَحْمد بن حَنْبَل، حَدثنَا بِحَدِيث عبد الْقَيْس، عَن القطيعاء، فَقَالَ: سلوا بعض أَصْحَاب الْغَرِيب."],[985,"فَإِنِّي أكره أَن أَتكَلّم فِي قَول رَسُول الله صلى الله عليه وآله وسلم بِالظَّنِّ فأخطئ."],[986,"٤١٤"],[987,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: وَذكر أَبُو عبد الله زَائِدَة فقدمه، وفضله فِي الثبت والضبط."],[988,"٤١٥"],[989,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سَأَلُوهُ من أَكثر فِي أَيُّوب؟ قَالَ: مَا عِنْدِي أحد أعلم بحَديثه من حَمَّاد يَعْنِي ابْن زيد، وَقد أَخطَأ فِي غير شَيْء."],[990,"٤١٦"],[991,"- سَمِعت الْمَيْمُونِيّ، يَقُول: وَصَحَّ عِنْدِي أَنه لم يحضر أَبَا نصر التمار حِين مَاتَ، فحسبت أَن ذَلِك لما كَانَ أجَاب فِي المحنة."],[992,"٤١٧"],[993,"- حَدَّثَنَا الْمَيْمُونِيُّ، قَالَ: سَمِعْتُ أَحْمَدَ بْنَ حَنْبَلٍ، وَسُئِلَ عَنْ حَدِيثِ أَبِي قَيْسٍ الْأَوْدِيِّ، مِمَّا رَوَى عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، عَنِ النَّبِيِّ صلى الله عليه وآله وسلم، أَنَّهُ مَسَحَ عَلَى النَّعْلَيْنِ، وَالْجَوْرَبَيْنِ، فَقَالَ لِي: الْمَعْرُوفُ عَنِ النَّبِيِّ صلى الله عليه وآله وسلم، أَنَّهُ مَسَحَ عَلَى الْخُفَّيْنِ، لَيْسَ هَذَا إِلَّا مِنْ أَبِي قَيْسٍ، إِنَّ لَهُ أَشْيَاءَ مَنَاكِيرَ"],[994,"٤١٨"],[995,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: حَدثنَا ابْن حَنْبَل، قَالَ: حَدثنَا يحيى، قَالَ: قَالَ زُهَيْر: رَأَيْت أَشْعَث بن سوار عِنْد أبي الزبير قَائِما دون النَّاس، وَأَبُو الزبير يحدث، فَيَقُول أَشْعَث: كَيفَ قَالَ، وَأي شَيْء قَالَ؟"],[996,"٤١٩"],[997,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: حَدثنَا ابْن حَنْبَل، قَالَ: حَدثنَا عَفَّان، قَالَ: حَدثنَا معَاذ، قَالَ: قَالَ أَشْعَث، مَا رَأَيْت هشاما يَعْنِي ابْن حسان، عَن الْحسن قطّ، فَقيل لَهُ: إِن عمروا يَقُول هَذَا، فَأَنت إِن قلته، قويته عَلَيْهِ أَو صدق أَو نَحْو هَذَا، قَالَ: لَا أَقُول هَذَا، وَلَا أَعُود لهَذَا."],[998,"٤٢٠"],[999,"- قَالَ حَدثنَا ابْن حَنْبَل، قَالَ: حَدثنَا عَفَّان، قَالَ: حَدثنَا معَاذ، قَالَ: قَالَ حميد للبتي: إِذا أَتَاك النَّاس تحملهم على أَمر وَاحِد؟ لَا، وَلَكِن خُذ من هَذَا، وَهَذَا وَأصْلح بَينهم، قَالَ: فَقَالَ البتي لَا أُطِيق سحرك، وَكَانَ حميد مصلح أهل الْبَصْرَة."],[1000,"٤٢١"],[1001,"- قَالَ حَدثنَا ابْن حَنْبَل، قَالَ: حَدثنَا عَفَّان، قَالَ: حَدثنِي يحيى بن سعيد، قَالَ: كنت أسأَل حميدا عَن الشَّيْء من فتيا الْحسن، فَيَقُول: قد نسيت."],[1002,"٤٢٢"],[1003,"- قَالَ حَدثنَا ابْن حَنْبَل، قَالَ: حَدثنَا إِسْمَاعِيل، قَالَ: حَدثنَا أَبُو رَجَاء، قَالَ: قلت لِلْحسنِ: متي عَهْدك بِالْمَدِينَةِ؟ قَالَ: ليَالِي صفّين، قَالَ: قلت: فَمَتَى احتملت؟ قَالَ: بعد"],[1004,"صفّين بعام."],[1005,"٤٢٣"],[1006,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سمعته، وَذكر عبد الْوَارِث، فَقَالَ: كَانَ أسن من إِسْمَاعِيل بن علية بِسنتَيْنِ، سمع من غير وَاحِد، لم يسمع مِنْهُ إِسْمَاعِيل، ثمَّ ذكر ضبط عبد الْوَارِث، وَأَنه كَانَ صَاحب نَحْو، ثمَّ قَالَ: وَقد غلط فِي غير شَيْء، ثمَّ قَالَ: روى عَن أَيُّوب أَحَادِيث لم يروها أحد من أَصْحَابه، وَهُوَ عِنْده مَعَ هَذَا ثَبت، ضَابِط."],[1007,"٤٢٤"],[1008,"- قَالَ وَسَمِعْتُ أَبَا عَبْدِ اللَّهِ أَحْمَدَ بْنَ حَنْبَلٍ، يَقُولُ: الْإِيمَانُ قَوْلٌ وَعَمَلٌ يَزِيدُ وَيَنْقُصُ قَالُوا لَهُ وَنِيَّةٌ، قَالَ:"],[1009,"النِّيَّةُ مُقَدَّمَةٌ فِي هَذَا الْمَوْضِعِ"],[1010,"٤٢٥"],[1011,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: حَدثنَا يحيى يَعْنِي ابْن أَيُّوب، قَالَ: سَمِعت حميدا الرُّؤَاسِي، يَقُول: كَانَ زُهَيْر إِذا سمع الحَدِيث من الْمُحدث، كتب عَلَيْهِ: قد فرغت."],[1012,"٤٢٦"],[1013,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: حَدثنَا يحيى، يَقُول: سَمِعت شُعَيْب بن حَرْب، وَذكر حَدِيثا عَن زُهَيْر، وَشعْبَة، فَقيل لَهُ: شُعْبَة، فَقَالَ: زُهَيْر أحفظ من عشْرين مثل شُعْبَة."],[1014,"٤٢٧"],[1015,"- قَالَ: حَدثنَا يحيى، قَالَ: سَمِعت معَاذ بن معَاذ، يَقُول: لَا وَالله، مَا كَانَ سُفْيَان بأثبت عِنْدِي من زُهَيْر."],[1016,"٤٢٨"],[1017,"- قَالَ حَدثنَا يحيى، قَالَ: سَمِعت معَاذ بن معَاذ، يَقُول: إِذا سَمِعت الحَدِيث من زُهَيْر لم أبال أَلا أسمعهُ من سُفْيَان."],[1018,"٤٢٩"],[1019,"- قَالَ حَدثنَا يحيى، قَالَ: سَمِعت أسود بن سَالم، يَقُول: سَمِعت هشيما، يَقُول: كُنَّا نَدع مجالسة شُعْبَة، لِأَنَّهُ كَانَ يدخلنا فِي الْغَيْبَة."],[1020,"٤٣٠"],[1021,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: وَقَالَ لي أَبُو عبد الله يَوْمًا: يَا أَبَا الْحسن، إِنِّي لأشبه ورع جدك مَيْمُون بورع ابْن سِيرِين."],[1022,"٤٣١"],[1023,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سَأَلت أَبَا عبد الله، عَن أَفْلح بن حميد، قَالَ: صَالح يحْتَمل."],[1024,"٤٣٢"],[1025,"- قلت: سَلمَة بن وردان، قَالَ لي: الَّذِي يروي عَن أنس؟"],[1026,"مَا أَدْرِي إيش حَدِيثه، لَهُ أَشْيَاء مَنَاكِير."],[1027,"٤٣٣"],[1028,"- قلت: دَاوُد بن قيس الْفراء، قَالَ: صَالح الحَدِيث."],[1029,"٤٣٤"],[1030,"- قلت: مُحَمَّد بن عبد الله ابْن أخي الزُّهْرِيّ؟ قَالَ: يحْتَمل أَيْضا."],[1031,"٤٣٥"],[1032,"- قلت أُسَامَة بن زيد يروي عَن الْقَاسِم؟ قَالَ: وَهَذَا أَيْضا يحْتَملهُ النَّاس."],[1033,"إِلَّا أَن يحيى الْقطَّان تَركه."],[1034,"٤٣٦"],[1035,"- عبد الرَّحْمَن بن أبي الموال؟ قَالَ: مَا أرى بحَديثه بَأْس، هُوَ مِمَّن يحْتَمل."],[1036,"٤٣٧"],[1037,"- قلت: فائد مولى عبيد الله؟ قَالَ: هَذَا الَّذِي ترك النَّاس حَدِيثه، أَبُو الورقاء، يُقَال لَهُ صَاحب ابْن أبي أوفى."],[1038,"٤٣٨"],[1039,"- قلت: هِشَام بن سعد الخشاب؟ قَالَ: هُوَ رجل قد احْتمل عَنهُ."],[1040,"٤٣٩"],[1041,"- قلت: عِيسَى بن عَاصِم؟ قَالَ: ثِقَة."],[1042,"٤٤٠"],[1043,"- قلت: سعيد بن مُسلم بن بانك؟ قَالَ: أرى أَيْضا، لَيْسَ بِهِ بَأْس."],[1044,"٤٤١"],[1045,"- قلت: إِبْرَاهِيم بن عبد الله بن الْحَارِث الجُمَحِي؟ قَالَ: أجدني أعرف ذَا."],[1046,"٤٤٢"],[1047,"- قلت: سُلَيْمَان بن أبي خَالِد، يروي عَن أَبِيه؟ قَالَ: مَا أعرفهُ."],[1048,"٤٤٣"],[1049,"- سَأَلته عَن عمر بن نبيه، الكعبي، قَالَ: لَيْسَ بِهِ بَأْس."],[1050,"٤٤٤"],[1051,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: قَالَ أَبُو عبد الله: حُسَيْن بن وَاقد لَهُ أَشْيَاء مَنَاكِير."],[1052,"٤٤٥"],[1053,"- سَأَلته عَن عبد الله بن سعيد بن أبي هِنْد، فَقَالَ: ثِقَة."],[1054,"٤٤٦"],[1055,"- سَأَلته عَن دَاوُد بن بكر بن أبي الْفُرَات، فَقَالَ لَا أعرفهُ."],[1056,"٤٤٧"],[1057,"- وَسَأَلته عَن عبد الله بن عَامر الْأَسْلَمِيّ، يروي عَن أبي الزبير، فَقَالَ: لَيْسَ بِقَوي فِي الحَدِيث."],[1058,"٤٤٨"],[1059,"- وَسَأَلته عَن نَافِع بن جُبَير بن مطعم، فَقَالَ لي: رجل من أنباء الصَّحَابَة، ثِقَة، لَا أعلم إِلَّا خيرا."],[1060,"٤٤٩"],[1061,"- سَأَلْتُهُ عَنْ مُحَمَّدِ بْنِ عَمْرٍو، عَنْ أَبِي سَلَمَةَ، فَقَالَ لِي: رُبَّمَا رَفَعَ بَعْضَ الْحَدِيثِ، وَرُبَّمَا قَصَّرَ بِهِ، وَهُوَ يُحْتَمَلُ."],[1062,"وَيَحْيَى بْنُ سَعِيدٍ أَثْبَتُ حَدِيثًا مِنْهُ،"],[1063,"٤٥٠"],[1064,"- وَسَأَلْتُهُ عَنْ عَبْدِ اللَّهِ بْنِ دِينَارٍ، عَنِ ابْنِ عُمَرَ، فَقَالَ لِي: ثِقَةٌ، إِلَّا حَدِيثًا وَاحِدًا، يَرْوِيهِ عَنِ ابْنِ عُمَرَ قَالَ: الْوَلَاءُ لَا تُبَاعُ"],[1065,"وَلَا تُوهَبُ، وَنَافِعٌ قَالَ فِي قِصَّةِ بَرِيرَةَ: الْوَلَاءُ لِمَنْ أَعْتَقَ \""],[1066,"٤٥١"],[1067,"- وَسَأَلته عَن كُلَيْب بن وَائِل، يروي عَن ابْن عمر، قَالَ: مَا أرى بِهِ بَأْسا."],[1068,"٤٥٢"],[1069,"- سَأَلته عَن عَمْرو بن دِينَار فِي ابْن عَبَّاس وَابْن عمر، فَقَالَ: من الثِّقَات يَحْكِي عَن شُعْبَة، أَنه قَالَ: مَا رَأَيْت أثبت من عَمْرو بن دِينَار."],[1070,"٤٥٣"],[1071,"- قلت لَهُ: أَشْيَاء يرسلها، قَالَ: إِذا قَالَ: سَمِعت أَو حَدثنَا، وَقد كَانَ يحدث بأَشْيَاء عَن رجل، عَن ابْن عَبَّاس."],[1072,"٤٥٤"],[1073,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: وَسمعت أَبَا عبد الله، يَقُول: عبد الله بن زيد بن أسلم أثبت من عبد الرَّحْمَن، قلت: أثبت؟ قلت: فعبد الرَّحْمَن؟ قَالَ: كَذَا، لَيْسَ مثله، وَضعف من أمره قَلِيلا."],[1074,"٤٥٥"],[1075,"- قَالَ وَسمعت أَبَا عبد الله، يَقُول: مهْدي ثِقَة، قلت مهْدي بن مَيْمُون؟ قَالَ: نعم، ثِقَة."],[1076,"٤٥٦"],[1077,"- قَالَ وسمعته يَقُول: كَانَ عبد الله بن وهب الْمصْرِيّ رجلا صَالحا، إيش كَانَ عِنْده من الحَدِيث؟ قد رَأَيْته إيش؟ فَأثْنى عَلَيْهِ، وَذكر أَبُو عبد الله تسهيله فِي الْأَخْذ."],[1078,"قلت لَهُ: كَذَا أَصْحَابه المصريون أَو عَامَّة أَصْحَابه فِي التسهيل فِي الْأَخْذ؟ قَالَ لي: نعم."],[1079,"٤٥٧"],[1080,"- وسمعته يَقُول: بشر بن رَافع، مَا أرَاهُ قَوِيا فِي الحَدِيث."],[1081,"٤٥٨"],[1082,"- وسمعته يَقُول: حَيْوَة بن شُرَيْح رجل صَالح، لَهُ أَشْيَاء حسان، وَزَاد قَول ابْن الْمُبَارك فِيهِ: مَا وصف لي أحد إِلَّا رَأَيْته"],[1083,"دون مَا وصف لي، إِلَّا حَيْوَة، فَإِنِّي رَأَيْته فَوق مَا وصف لي."],[1084,"٤٥٩"],[1085,"- سَأَلته عَن أبي عبد الله الشقري، قَالَ: لَيْسَ بِالْقَوِيّ عِنْدِي هُوَ ضَعِيف."],[1086,"٤٦٠"],[1087,"- وَذكر الْوَلِيد بن مُسلم، فَقَالَ: كَانَ صَاحب تسهيل."],[1088,"٤٦١"],[1089,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: قَالَ لنا خَالِد بن خِدَاش قَالَ لي"],[1090,"الدَّرَاورْدِي، ومعن، وَعَامة أهل الْمَدِينَة لَا ترد عبد الرَّحْمَن بن زيد بن أسلم، إِنَّه لَا يدْرِي مَا يَقُول، وَلَكِن عَلَيْك بِعَبْد الله بن زيد."],[1091,"٤٦٢"],[1092,"- سَأَلته عَن عَطاء السليمي، فَقَالَ لي: هَذَا لي: هَذَا من خِيَار عباد الله، لَيْسَ لَهُ حَدِيث، إِنَّمَا هُوَ رَأْيه وَكَلَامه."],[1093,"٤٦٣"],[1094,"- وَسلم الْعلوِي، قَالَ لي: مَا عملت إِلَّا خيرا، وَلَكِن شُعْبَة تكلم فِيهِ، قلت: من قصَّة الْهلَال؟ قَالَ لي: نعم."],[1095,"٤٦٤"],[1096,"- قلت: الرّبيع بن صبيح؟ قَالَ لي: هُوَ فِي بدنه رجل صَالح، وَلَيْسَ عِنْده حَدِيث يحْتَاج إِلَيْهِ فِيهِ، كَأَنَّهُ ضعف أمره."],[1097,"٤٦٥"],[1098,"- قلت: حَمَّاد بن أبي سُفْيَان؟ قَالَ: أما حَدِيث هَؤُلَاءِ الثِّقَات عَنهُ: شُعْبَة، وسُفْيَان، وَهِشَام فأحاديث أَكْثَرهَا مُتَقَارِبَة، وَلكنه أول من تكلم فِي الرَّأْي، قلت: كَانَ يرى الإرجاء؟ قَالَ لي: نعم، كَانَ يرى الإرجاء."],[1099,"٤٦٦"],[1100,"- قلت: جَابر الْجعْفِيّ؟ قَالَ لي: كَانَ يرى التَّشَيُّع، قلت يتهم فِي حَدِيثه بِالْكَذِبِ؟ فَقَالَ لي: من طعن فِيهِ، فَإِنَّمَا يطعن بِمَا يخَاف من الْكَذِب، قلت: الْكَذِب، فَقَالَ: إِي وَالله، وَذَاكَ فِي حَدِيثه بَين، إِذا نظرت إِلَيْهَا."],[1101,"٤٦٧"],[1102,"- قلت: حَنْظَلَة بن أبي سُفْيَان، فَقَالَ لي: ثِقَة، ثِقَة الجُمَحِي."],[1103,"٤٦٨"],[1104,"- قُلْتَ: فَحَنْظَلَةُ السَّدُوسِيُّ؟ قَالَ: لَهُ أَشْيَاءُ مَنَاكِيرُ، رَوَى حَدِيثَيْنِ كِلَاهُمَا عَنِ النَّبِيِّ صلى الله عليه وآله وسلم مُنْكَرَيْنِ، عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صلى الله عليه وآله وسلم قَنَتَ فِي الْوَتْرِ وَالْآخَرُ: أَمَرَنَا إِذَا الْتَقَيْنَا أَنْ يُصَافِحَ أَحَدُنَا صَاحِبَهُ، وَأَنْ يَنْحَنِيَ بَعْضُنَا لِبَعْضٍ وَأَنْ يَعْتَنِقَ بَعْضُنَا لِبَعْضٍ، كِلَاهُمَا مُنْكَرَانِ"],[1105,"٤٦٩"],[1106,"- قلت: يُوسُف الْمَاجشون؟ قَالَ لي: لَيْسَ بِهِ بَأْس، وَقد أدركناه نَحن، قلت: قد حَدَّثتنَا عَنهُ، وَيحدث عَن أَبِيه؟ قَالَ: نعم، قلت: فأبوه؟ قَالَ: لَا بَأْس بِهِ."],[1107,"٤٧٠"],[1108,"- وَذكر عبد الْعَزِيز، وَقَالَ: هُوَ ابْن عَم يُوسُف، فَذكر أَيْضا خيرا، وأكبر علمي ومعرفتي أَنه أَخا ليوسف، يُقَال لَهُ: عبد الله، فَقَالَ أَيْضا خيرا."],[1109,"٤٧١"],[1110,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: وَقَالَ، يَعْنِي أَحْمد بن حَنْبَل، وَقَالَ لي: يُوسُف تَأَخّر عمره، فقيناه نَحن."],[1111,"٤٧٢"],[1112,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: قَالَ لي أَبُو عبد الله: عُثْمَان بن حَكِيم شيخ، قلت: أَحَادِيثه؟ قَالَ: مُتَقَارِبَة."],[1113,"٤٧٣"],[1114,"- وَحدثنَا الميموين، قَالَ: وَذكروا أَشْيَاء عَن مجَالد، عَن الشّعبِيّ، فَقَالَ: كم من أعجوبة لمجالد."],[1115,"٤٧٤"],[1116,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: تَذَاكرنَا يَوْمًا شَيْئا، اخْتلفُوا فِيهِ، فَقَالَ: رجل ابْن أبي شيبَة، يَقُول عَن عَفَّان."],[1117,"قَالَ أَبُو عبد الله: دع ابْن أبي شيبَة فِي ذَا، انْظُر إيش يَقُول غَيره، يُرِيد أَبُو عبد الله، كَثْرَة خطأه."],[1118,"٤٧٥"],[1119,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: قلت: إِسْمَاعِيل بن زَكَرِيَّا كَيفَ هُوَ؟ قَالَ لي: أما الْأَحَادِيث الْمَشْهُورَة الَّتِي يَرْوِيهَا، فَهُوَ فِيهَا مقارب الحَدِيث، صَالح، وَلكنه لَيْسَ ينشرح الصَّدْر لَهُ، لَيْسَ يعرف، هَكَذَا عهد بِالطَّلَبِ."],[1120,"٤٧٦"],[1121,"- قَالَ: قلت لأبي عبد الله: الرّبيع بن صبيح؟ قَالَ: لَيْسَ لَهُ كثير شَيْء يسْندهُ لَهُ أَشْيَاء يَرْوِيهَا عَن عَطاء، وَالْحسن مسَائِل،"],[1122,"وَلَيْسَ بِهِ بَأْس، قلت: شَيْء يرويهِ عَن يزِيد، قَالَ لي: يرويهِ عَن يزِيد، عَن أنس فِي الرّفْع؟ قلت: نعم، فَتَبَسَّمَ أَبُو عبد الله إِلَيّ، قلت تذكره أَي شَيْء يفيه عَن يزِيد الرقاشِي؟ قَالَ لي: نعم، قلت: وَهَكَذَا يزِيد ضَعِيف؟ قَالَ: نعم، هُوَ ضَعِيف."],[1123,"٤٧٧"],[1124,"- وَذكر أَبُو عبد الله حَدِيث روح، عَن ابْن أبي حميد، قَالَ: لَو كَانَ غير ابْن أبي حميد."],[1125,"٤٧٨"],[1126,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سَمِعت أَبَا الْوَلِيد هِشَام بن عبد الْملك، يَقُول: كَانَ مَالك بن أنس سيئ الرَّأْي فِي ابْن إِسْحَاق."],[1127,"٤٧٩"],[1128,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: قَالَ أَبُو عبد الله: كَانَ ابْن جريج من أوعية الْعلم."],[1129,"٤٨٠"],[1130,"- وَقَالَ أَبُو عبد الله، وَذكر شعيبا الجبائي، قَالَ: رجل قَرَأَ الْكتب يشبه وهبا."],[1131,"٤٨١"],[1132,"- قَالَ لي أَبُو عبد الله: رشدين لَيْسَ بِهِ بَأْس، فِي الْأَحَادِيث الرقَاق."],[1133,"٤٨٢"],[1134,"- قَالَ: قَالَ ابْن حَنْبَل: زِيَاد جُبَير بن حَيَّة، رجل مَعْرُوف."],[1135,"٤٨٣"],[1136,"- قَالَ: وَلَا أعلم أحدا، روى عَن أبي عِيسَى الأسواري غير قَتَادَة."],[1137,"٤٨٤"],[1138,"- قَالَ: قَالَ ابْن حَنْبَل: لَيْسَ نجد أحدا يرفع غير زُهَيْر يَعْنِي فِي الْمحرم إِذا لم يجد نَعْلَيْه، وَكَانَ زُهَيْر من معادن الْعلم."],[1139,"٤٨٥"],[1140,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: قَالَ لي أَبُو عبد الله، عَن يحيى بن سعيد فِي حَدِيث شُعْبَة: لَيْسَ بِشَيْء عَن مُجَاهِد، قَالَ: سَمِعت عَائِشَة، وَأنكر أَن يكون سمع من عَائِشَة."],[1141,"٤٨٦"],[1142,"- قَالَ: قَالَ أَبُو عبد الله: ابْن أبي عرُوبَة، لم يسمع من يحيى بن سعيد، وَلَا معمر سمع من يحيى شَيْئا."],[1143,"قَالَ: ذَاك أَبُو عبد الله."],[1144,"٤٨٧"],[1145,"- وسمعته يَقُول: بِلَال بن سعد رجل صَالح."],[1146,"٤٨٨"],[1147,"- قَالَ: وَسمعت أَبَا عبد الله، يَقُول: مُحَمَّد بن عبد الرَّحْمَن بن عنج شيخ مُتَقَارب الحَدِيث، يروي عَنهُ اللَّيْث."],[1148,"٤٨٩"],[1149,"- قَالَ: وَذكر أَبُو عبد الله السّري بن إِسْمَاعِيل، فَقَالَ: ترك النَّاس حَدِيثه."],[1150,"٤٩٠"],[1151,"- والمسعودي من سمع مِنْهُ بِآخِرهِ، يطعن فِي سماعهم مِنْهُ."],[1152,"٤٩١"],[1153,"- وَسَأَلَهُ رجل عَن الْحجَّاج بن أَرْطَأَة، مَا شَأْنه؟ قَالَ: شَأْنه أَنه يزِيد فِي الْأَحَادِيث."],[1154,"٤٩٢"],[1155,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سَمِعت أبي، يَقُول: رُبمَا رَأَيْت الْحجَّاج يضع يَده على رَأسه، يَقُول: قتلني حب الشّرف."],[1156,"٤٩٣"],[1157,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: قَالَ رجل لأبي عبد الله: ابْن أبي ليلى؟ قَالَ: ضَعِيف، وَالْحجاج أَكثر فِي نَفسِي مِنْهُ إِلَّا أَنه يَعْنِي ابْن أبي ليلى، فِي حَدِيثه عَن الْمنْهَال، كَأَنَّهُ"],[1158,"قَالَ لَهُ رجل أَيْن مجَالد مِنْهُمَا؟ قَالَ: هَذَا تَمْيِيز شَدِيد."],[1159,"٤٩٤"],[1160,"- قَالَ: قَالَ عبد الله، فعجبت مِنْهُ فِي ذَاك الْموضع، كَيفَ كَانَ تحببه فِي مثل هَذَا؟ ثمَّ قَالَ لنا: وَلكنه كَانَ رجلا كثير النّظر فِي الرِّجَال وَالْكَلَام، وَإِنَّمَا ذكر أَبُو عبد الله بن الْمُبَارك فِي هَذِه الْقِصَّة، أَنه كره أَن يُجِيبهُمْ، فأخبروه بِمَا لَهُ من الآخر فِي معرفَة هَذَا فَذكر ابْن الْمُبَارك عِنْد ذَلِك."],[1161,"٤٩٥"],[1162,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سعيد بن بشير رَأَيْته يضعف أمره، قلت: الَّذِي يروي عَن قَتَادَة، قَالَ: قد روى عَن قَتَادَة أَشْيَاء."],[1163,"٤٩٦"],[1164,"- مُحَمَّد بن سَلمَة الْحَرَّانِي؟ قَالَ: هُوَ فِي بدنه، وَأَظنهُ قَالَ: لَيْسَ بحَديثه بَأْس."],[1165,"٤٩٧"],[1166,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سمعته يَقُول: ابْن أبي نجيح ثِقَة، وَكَانَ"],[1167,"أَبوهُ من خِيَار عباد الله."],[1168,"٤٩٨"],[1169,"- كثير بن جمْهَان؟ قَالَ: لَا أعرفهُ كثيرا."],[1170,"٤٩٩"],[1171,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سمعته يَقُول: لم يَصح لهشيم عَن الزُّهْرِيّ إِلَّا أَرْبَعَة أَحَادِيث."],[1172,"٥٠٠"],[1173,"- وَعلي بن صَالح، صَالح الحَدِيث، وَلَكِن حسن بن صَالح أَخُوهُ."],[1174,"٥٠١"],[1175,"- حَدثنَا الْمَيْمُونِيّ، حَدثنَا أَحْمد، قَالَ: حَدثنَا وَكِيع، قَالَ: حَدثنَا سعيد بن السَّائِب حسن الحَدِيث."],[1176,"٥٠٢"],[1177,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سمعته يَقُول: ابْن أبي لبيد ثَبت الحَدِيث."],[1178,"٥٠٣"],[1179,"- وَرَبِيعَة بن أبي عبد الرَّحْمَن، ثِقَة."],[1180,"٥٠٤"],[1181,"- قَالَ وسمعته يَقُول فِي غَسَّان بن مُضر: مَا كَانَ أعسره من شيخ."],[1182,"٥٠٥"],[1183,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: قَالَ: مَا رَأينَا أحدا أثبت فِي عَطاء من عَمْرو، وَابْن جريج."],[1184,"٥٠٦"],[1185,"- قَالَ حَدثنَا ابْن حَنْبَل، قَالَ: حَدثنَا يحيى، حَدثنَا مثنى، قَالَ: حَدثنَا قَتَادَة، قَالَ: مثنى ثِقَة."],[1186,"٥٠٧"],[1187,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سمعته يَقُول: أَبُو الزِّنَاد من أَصْحَاب الحَدِيث."],[1188,"٥٠٨"],[1189,"- وَابْن عجلَان ثِقَة، وَأَبوهُ صَالح الحَدِيث، لَقِي أَبَا هُرَيْرَة."],[1190,"٥٠٩"],[1191,"- وسمعته يَقُول: عمَارَة بن الْقَعْقَاع ثِقَة."],[1192,"٥١٠"],[1193,"- وَإِسْحَاق بن سُوَيْد ثَبت."],[1194,"٥١١"],[1195,"- حَدثنَا الْمَيْمُونِيّ، قَالَ: سمعته يَقُول، وَذكر الشاميين، فَقَالَ صَدَقَة بن خَالِد ثِقَة مَأْمُون، مَا بَلغنِي أَن أحدا من"],[1196,"الشاميين كَانَ يكْتب حَدِيثه بِيَدِهِ غَيره، فَذَاك بَين فِي حَدِيثه."],[1197,"٥١٢"],[1198,"- وَذكر صَدَقَة لسمين، فَقَالَ: ضَعِيف."],[1199,"٥١٣"],[1200,"- وتذاكرنا صَالح بن كيسَان، فَقلت لَهُ: كَيفَ هُوَ؟ قَالَ: صَالح."],[1201,"٥١٤"],[1202,"- قَالَ وسمعته يَقُول: مَا كَانَ عَمْرو بن عبيد بِأَهْل أَن يحدث عَنهُ."],[1203,"إِلَى هَهُنَا عَن الْمَيْمُونِيّ."],[1204,"٥١٥"],[1205,"- حَدثنَا أَبُو عوَانَة يَعْقُوب بن إِسْحَاقَ، قَالَ: حَدَّثَنَا يَزِيدُ بْنُ الْمُبَارَكِ أَبُو خَالِدٍ الْفَسَوِيُّ الْفَارِسِيُّ، قَالَ: حَدَّثَنَا سَلَمَةُ بْنُ الْفَضْلِ، قَالَ: حَدَّثَنَا أَبُو حَمْزَةَ السُّكَّرِيُّ، عَنْ سُلَيْمَانَ الشَّيْبَانِيِّ، عَنْ أَبِي الْأَحْوَصِ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وآله وسلم: لِلْجَنَّةِ بَابٌ يُقَالُ لَهُ: الرَّيَّانُ يَدْخُلُهُ الصَّائِمُونَ"],[1206,"٥١٦"],[1207,"- وَبِإِسْنَادِهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وآله وسلم:"],[1208,"لِلصَّائِمِ فَرْحَتَانِ: فَرْحَةٌ عِنْدَ إِفْطَارِهِ، وَفَرْحَةٌ عِنْدَ لِقَاءِ رَبِّهِ"],[1209,"٥١٧"],[1210,"- حَدثنَا يَعْقُوب بن سُفْيَان الْفَارِسِي، عَن يزِيد بن الْمُبَارك أبي خَالِد، هذَيْن الحديثيين، وهما مِمَّا سَأَلُونِي أَصْحَابنَا من الْحفاظ بِبَغْدَاد، وهما من حَدِيث الشَّيْبَانِيّ، عَن بَيَان."],[1211,"٥١٨"],[1212,"- حَدَّثَنَا يَزِيدُ بْنُ الْمُبَارَكِ، قَالَ: حَدَّثَنَا سَلَمَةُ بْنُ الْفَضْلِ، حَدَّثَنَا أَبُو جَعْفَرٍ الرَّازِيُّ، عَنْ أَيُّوبَ السِّخْتِيَانِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ، عَنْ عَائِشَةَ، قَالَتْ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وآله وسلم: مَا أَسْكَرَ الْفَرَقُ فَالْحَسْوَةُ مِنْهُ حَرَامٌ \""],[1213,"٥١٩"],[1214,"- حَدثنَا فضلك الرَّازِيّ، وسألوه أهل بَغْدَاد، عَن شيخ من أهل"],[1215,"الرّيّ، عَن سَلمَة بن الْفضل مثله."],[1216,"٥٢٠"],[1217,"- قَالَ أَبُو عوَانَة: هَذَا حَدِيث غَرِيب من حَدِيث أَيُّوب، لَا أَظن أَن أحدا رَوَاهُ عَن أَيُّوب غَيره."],[1218,"وَهُوَ الْمَعْرُوف من حَدِيث أبي عُثْمَان، عَن الْقَاسِم، عَن عَائِشَة."],[1219,"٥٢١"],[1220,"- سَأَلت أَبَا يُوسُف الْفَارِسِي، عَن يزِيد بن الْمُبَارك، فَقَالَ لي: هُوَ جاري مُنْذُ سِتِّينَ سنة، أعرفهُ بالاستقامة والصدق، وَقد سمع مِنْهُ يَعْقُوب."],[1221,"٥٢٢"],[1222,"- قَالَ سَمِعت مُحَمَّد بن عبد الله بن عبد الحكم، يَقُول: لم يكن الشَّافِعِي يرى أَن يكنى بِأبي الْقَاسِم أحد من خلق الله، لَا مُحَمَّد وَلَا غَيره."],[1223,"٥٢٣"],[1224,"- قَالَ حَدثنَا الرّبيع بن سُلَيْمَان، قَالَ: حَدثنَا ابْن وهب، قَالَ: أَخْبرنِي مَالك بن أنس، قَالَ: دعِي حُسَيْن بن رستم الْأَيْلِي إِلَى صَنِيع فَأتى وَكَانَ صَائِما، فَلَمَّا وضع الطَّعَام لم يَأْكُل، فَرَآهُ صَاحب الصَّنِيع، فَقَالَ: أَلا تَأْكُل؟ فَقَالَ: إِنِّي صَائِم، فَقَالَ: وَمَا عَلَيْك أَن تفطر وتصوم يَوْمًا مَكَانَهُ؟ قَالَ: إِنِّي وعدت الله بصيام هَذَا الْيَوْم، فأكره أَن أخلفه مَا وعدته."],[1225,"٥٢٤"],[1226,"- حَدَّثَنَا أَبُو عُبَيْدِ اللَّهِ مُعَاوِيَةُ بْنُ صَالِحٍ الدِّمَشْقِيُّ، قَالَ:"],[1227,"حَدَّثَنَا إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ الْبَغْدَادِيُّ ثِقَةٌ، عَنْ مُحَمَّدِ بْنِ حِمْيَرَ، عَنْ بَحِيرِ بْنِ سَعِيدٍ، عَنْ خَالِدِ بْنِ مَعْدَانَ، عَنْ كَثِيرِ بْنِ مُرَّةَ، عَنْ نُعَيْمِ بْنِ هَمَّارٍ، عَنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ، عَنْ أَبِي أَيُّوبَ، عَنْ عَوْفِ بْنِ مَالِكٍ، قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صلى الله عليه وآله وسلم بِالْهَجِيرِ وَهُوَ مَرْعُوبٌ، فَقَالَ: أَطِيعُونِي مَا كُنْتُ بَيْنَ أَظْهُرِكُمْ، وَعَلَيْكُمْ بِكِتَابِ اللَّهِ، أَحِلُّوا حَلالَهُ وَحَرِّمُوا حَرَامَهُ \""],[1228,"٥٢٥"],[1229,"- قَالَ: حَدثنَا أَبُو بكر الْجُعْفِيُّ مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بِدِمَشْقَ، قَالَ: حَدَّثَنَا جُنَادَةُ بْنُ مُحَمَّدٍ الْمُرِّيُّ، قَالَ: حَدَّثَنِي يَحْيَى بْنُ حَمْزَةَ الْحَضْرَمِيُّ، عَنِ الْأَوْزَاعِيِّ، عَن لَيْث بن أبي سليم، عَنْ أَبِي الزُّبْيَرِ، عَنْ جَابِرٍ، أَنّ رَسُولَ اللَّهُ صلى الله عليه وآله وسلم كَانَ لَا يَنَامُ حَتَّى يَقْرَأَ الم تَنْزِيلُ، السَّجْدَةُ، وتَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ"],[1230,"٥٢٦"],[1231,"- سَمِعت يُونُس بن عبد الْأَعْلَى، قَالَ: سَمِعت الشَّافِعِي، يَقُول: قيل لعمر بن عبد الْعَزِيز: مَا تَقول فِي أهل صفّين، قَالَ: تِلْكَ دِمَاء طهر الله يَدي مِنْهَا، فَمَا أحب أَن أخضب لساني مِنْهَا."],[1232,"٥٢٧"],[1233,"- وَسمعت يُونُس، يَقُول: وَقَالَ لي الشَّافِعِي: اعْلَم أَنه لَيْسَ إِلَى السَّلامَة من النَّاس سَبِيل، فَانْظُر مَا فِيهِ مصلحتك فالزمه."],[1234,"٥٢٨"],[1235,"- حَدثنَا مُحَمَّد بن يَعْقُوب الرَّمْلِيّ، حَدثنَا مُحَمَّد بن أَيُّوب بن المتَوَكل، قَالَ: حَدثنَا يحيى بن سعيد الْقطَّان، وَعلي بن الْمَدِينِيّ، عَن سُفْيَان بن عُيَيْنَة، قَالَ: قَالَ الْحسن بن مُحَمَّد: إِن أحسن رِدَاء ارتديت بِهِ رِدَاء الْحلم هُوَ وَالله أحسن عَلَيْك من بردي حبرَة، فَإِن لم تكن حَلِيمًا فتحالم."],[1236,"قَالَ مُحَمَّد: فَسَأَلت عَليّ بن الْمَدِينِيّ، فَحَدثني بِهِ."],[1237,"٥٢٩"],[1238,"- حَدَّثَنَا سَعِيدُ بْنُ عَمْرٍو السَّكُونِيُّ، حَدَّثَنِي بَقِيَّةُ، قَالَ: وَسَمِعْتُ الْمُعْتَمِرَ، عَنِ ابْنِ جُرَيْجٍ، عَنِ الزُّهْرِيِّ، عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ، عَن عبد الله بن عَمْرو، أَنّ رَسُولَ اللَّهُ صلى الله عليه وآله وسلم: نَهَى عَنِ الْجَمَّةِ لِلْحُرَّةِ، وَعَنِ الْعَقْصَةِ لِلْأَمَةِ"],[1239,"٥٣٠"],[1240,"- حَدَّثَنَا حُمَيْدُ بْنُ عَيَّاشٍ، قَالَ: حَدَّثَنَا مُؤَمَّلُ بْنُ إِسْمَاعِيلَ، حَدَّثَنَا حَمَّادُ بْنُ سَلَمَةَ، عَنْ سُهَيْلٍ، عَنْ أَخِيهِ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وآله وسلم قَالَ: مَنْ أَكْثَرَ مِنْ ذِكْرِ اللَّهِ تَعَالَى بَرِئَ مِنَ النِّفَاقِ"],[1241,"٥٣١"],[1242,"- حَدثنَا نصر بن مَرْزُوق، حَدثنَا إِسْمَاعِيل بن مسلمة القعْنبِي، قَالَ: رَأَيْت الْحسن بن أبي جَعْفَر فِي الْمَنَام بعد مَا مَاتَ"],[1243,"بعبادان، فَقَالَ لي: أَيُّوب، وَيُونُس، وَابْن عون فِي الْجنَّة، قَالَ: فَقلت فعمرو بن عبيد؟ قَالَ فِي النَّار، قَالَ إِسْمَاعِيل: ثمَّ رَأَيْت الْحسن بن أبي جَعْفَر فِي الْمَنَام، فَقَالَ: أَيُّوب، وَيُونُس، وَابْن عون فِي الْجنَّة، قَالَ إِسْمَاعِيل: فعمرو بن عبيد؟ قَالَ: فِي النَّار، كم أَقُول لَك."],[1244,"٥٣٢"],[1245,"- حَدَّثَنِي جَعْفَرُ بْنُ عَبْدِ الْوَاحِدِ الْهَاشِمِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ عَبَّادٍ الْهُنَائِيُّ، عَنْ شُعْبَةَ، عَنْ قَتَادَةَ، عَنِ الشَّعْبِيِّ، عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صلى الله عليه وآله وسلم صَلَّى عَلَى قَبْرٍ بَعْدَ مَا دُفِنَ"],[1246,"قَالَ شُعْبَةُ: فَقُلْتُ: لِقَتَادَةَ مِمَّنْ سَمِعْتَهُ؟ قَالَ: حَدَّثَنِي عَاصِمُ"],[1247,"بْنُ بَهْدَلَةَ، قَالَ شُعْبَةُ: فَسَأَلْتُ عَاصِمَ بْنَ بَهْدَلَةَ، مِمَّنْ سَمِعْتَهُ؟ فَقَالَ: حَدَّثَنِيهِ الشَّيْبَانِيُّ."],[1248,"قَالَ شُعْبَةُ: فَلَقِيتُ الشَّيْبَانِيَّ فَسَأَلْتُهُ مِمَّنْ سَمِعْتَهُ؟ فَقَالَ حَدَّثَنِي الشَّعْبِيُّ عَنِ ابْنِ عَبَّاسٍ أَنّ النَّبِيَّ صلى الله عليه وآله وسلم صَلَّى عَلَى قَبْرٍ"],[1249,"٥٣٣"],[1250,"- حَدَّثَنَا أَبُو جَعْفَرٍ مُحَمَّدُ بْنُ الْحَجَّاجِ الْحَضْرَمِيُّ مِصْرِيٌّ، قَالَ: حَدَّثَنَا الْخَصِيبُ بْنُ نَاصِحٍ، قَالَ: حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ عَبْدِ اللَّهِ بْنِ دَاوُدَ، عَنِ الْأَعْمَشِ، عَنْ ذَرٍّ، عَنْ يُسَيْعٍ،"],[1251,"عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، أَنّ رَسُولِ اللَّهِ صلى الله عليه وآله وسلم، قَالَ: ﴿إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِي﴾ [غَافِر: ٦٠]، قَالَ: عَنْ دُعَائِي، سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ"],[1252,"٥٣٤"],[1253,"- أَخْبرنِي الْعَبَّاس بن الْوَلِيد، قَالَ: حَدثنَا أَبُو مسْهر، قَالَ: سَمِعت مَالك بن أنس، يَقُول: من إِزَالَة الْعلم أَن تجيب كل من يسئلك."],[1254,"٥٣٥"],[1255,"- قَالَ قَرَأْتُ عَلَى أَبِي سَلَمَةَ الْمُسْلِمِ بْنِ مُحَمَّدٍ الْهَمْدَانِيِّ بِصَنْعَاءَ، وَأَخْبَرَنِي أَيْضًا، قَالَ: أَخْبَرَنِي عَبْدُ الْمَلِكِ بْنُ عَبْدِ الرَّحْمَنِ أَبُو هِشَامٍ الذِّمَارِيُّ، عَنْ سُفْيَانَ الثَّوْرِيِّ، عَنْ مَالِكِ بْنِ أَنَسٍ، عَنْ عَبْدِ اللَّهِ بْنِ الْفَضْلِ، عَن نَافِع بن جُبَير بن مُطْعِمٍ، عَنِ ابْنِ عَبَّاسٍ، أَنّ"],[1256,"رَسُولِ اللَّهِ صلى الله عليه وآله وسلم، قَالَ: «الْأَيِّمُ أَحَقُّ بِنَفْسِهَا دُونَ وَلِيِّهَا، وَالْبِكْرُ تُسْتَأْذَنُ، وَإِذْنُهَا صُمَاتُهَا»"],[1257,"٥٣٦"],[1258,"- قَالَ: سَمِعت الْعزي، يَقُول: سَمِعت الْفرْيَابِيّ، يَقُول: سَمِعت الثَّوْريّ، يَقُول: مَا أشبه خُرُوج الْمُؤمن من الدُّنْيَا إِلَّا مثل خُرُوج الْوَلَد من الْبَطن، يخرج إِلَى الرَّاحَة من الْغم."],[1259,"٥٣٧"],[1260,"- سَمِعت أَبَا أُميَّة، يَقُول: سَمِعت أَحْمد بن حَنْبَل، يثني على الْأَصْمَعِي فِي السّنة،"],[1261,"قَالَ: وَسمعت على بن الْمَدِينِيّ يثني عَلَيْهِ."],[1262,"٥٣٨"],[1263,"- سَمِعت يزِيد بن عبد الصَّمد، قَالَ: سَأَلت يحيى بن معِين، عَن خَالِد بن عبد الرَّحْمَن، فَقَالَ: ثِقَة."],[1264,"٥٣٩"],[1265,"- حَدثنَا أَحْمد بن مُحَمَّد بن أبي بكر الْمقدمِي، قَالَ: سَمِعت عَليّ بن الْمَدِينِيّ سنة عشْرين وَمِائَتَيْنِ، وَقد ذكر لَهُ سُلَيْمَان بن حَرْب فَجعل يكثره، فَقَالَ: حَدثنَا يحيى بن سعيد مُنْذُ ثَلَاثِينَ سنة، فَقَالَ حَدثنِي سُلَيْمَان بن حَرْب، عَن حَمَّاد بن زيد، قَالَ: أخوف مَا أَخَاف على أَيُّوب وَابْن عون إِلَّا الحَدِيث."],[1266,"٥٤٠"],[1267,"- حَدَّثَنَا أَحْمَدُ بْنُ عِصَامٍ، قَالَ، حَدَّثَنَا أَبُو بَكْرٍ الْحَنَفِيُّ،"],[1268,"قَالَ: حَدَّثَنَا سُفْيَانُ الثَّوْرِيُّ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، قَالَ: قَالَ النَّبِيُّ صلى الله عليه وآله وسلم: لَا يَضُرُّ الْمَرْأَةُ الْحَائِضُ وَلَا الْجُنُبُ، أَلَّا تَنْقُضَ شَعْرَهَا إِذَا بَلَغَ الْمَاءُ شُئُونَ رَأْسِهَا"],[1269,"٥٤١"],[1270,"- حَدَّثَنَا مُسْلِمُ بْنُ الْحَجَّاجِ، قَالَ: حَدَّثَنَا مَالِكُ بْنُ عَبْدِ الْوَاحِدِ أَبُو غَسَّانَ الْمِسْمَعِيُّ، قَالَ: حَدَّثَنَا مُعَاذٌ، قَالَ: حَدَّثَنَا أَبِي، عَنْ مَطَرٍ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ: كُنَّا فِي حَجَّةِ رَسُولِ اللَّهِ صلى الله عليه وآله وسلم، فَمِنَّا مَنْ أَهَلَّ بَحَجٍّ، وَمِنَّا مَنْ أَهَلَّ بِعُمْرَةٍ، وَكُنْتُ أَنَا مِمَّنْ أَهَلَّ بِعُمْرَةٍ"],[1271,"٥٤٢"],[1272,"- حَدَّثَنَا سَعِيدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ دَادُوَيْهِ، قَالَ:"],[1273,"قَرَأْتُ عَلَى أَبِي، عَنْ رَبَاحٍ، عَنْ مَعْمَرٍ، عَنِ ابْنِ جُرَيْجٍ، عَنْ عَبْدِ الْعَزِيزِ بْنِ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ، عَنِ الرَّبِيعِ بْنِ سَبْرَةَ، عَنْ أَبِيهِ، أَنَّهُ قَالَ: إِنَّ النَّبِيَّ صلى الله عليه وآله وسلم: قَالَ يَوْمَ حَجَّةِ الْوَدَاعِ قَبْلَ يَوْمِ التَّرْوِيَةِ بِيَوْمٍ: مَنْ أَحَبَّ بِأَنْ يَسْتَمْتِعَ عَلَى جِهَةِ النِّكَاحِ إِلَى أَجَلٍ مَعْلُومٍ فَلْيَفْعَلْ، وَذَكَرَ الْحَدِيثَ."],[1274,"فَلَمَّا كَانَ يَوْمُ التَّرْوِيَةِ، قَالَ النَّبِيُّ صلى الله عليه وآله وسلم: إِنِّي كُنْتُ أَحْلَلْتُ لَكُمْ نِكَاحَ الْمُتْعَةِ، فَمَنْ كَانَ نَكَحَ عَلَى ذَلِكَ فَهُوَ بَاطِلٌ، وَإِنِّي قَدْ حَرَّمْتُهَا، فَهِيَ حَرَامٌ إِلَى يَوْمِ الْقِيَامَةِ"],[1275,"٥٤٣"],[1276,"- حَدَّثَنَا حَمْدَانُ بْنُ مُوسَى، أَبُو سَعِيدٍ الْبَلْخِيُّ، قَالَ: حَدَّثَنَا"],[1277,"عِصَامُ بْنُ يُوسُفَ، قَالَ: حَدَّثَنَا وَرْقَاءُ، عَنْ عَمْرِو بْنِ دِينَارٍ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صلى الله عليه وآله وسلم، أَنَّهُ قَالَ: إِذَا كَانَ يَوْمُ الْقِيَامَةِ جَاءَ الْمَقْتُولُ بِالْقَاتِلِ، رَأْسُهُ بِيَدِهِ آخِذٌ بِنَاصِيَتِهِ، تَشْخُبُ أَوْدَاجُهُ دَمًا، فَيُدْنِيهِ مِنَ الْعَرْشِ، فَذَكَرَ ابْنُ عَبَّاسٍ التَّوْبَةَ، فَقَرَأَ هَذِهِ الْآيَةَ: ﴿وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا﴾ [النِّسَاء: ٩٣]"],[1278,"وَالله مَا نسختها مُنْذُ نزلت، وأنى لَهُ التَّوْبَة."],[1279,"٥٤٤"],[1280,"- حَدثنَا عبيد بن مُحَمَّد الكشوري، قَالَ: سَأَلت أَبَا مُصعب، عَن ابْن سمْعَان، قَالَ: كَانَ مرمدا."],[1281,"وَسَأَلت يحيى بن معِين، فَقَالَ: كَانَ كَاذِبًا."],[1282,"٥٤٥"],[1283,"- سَمِعت عباسا الدوري، يَقُول: سَمِعت يحيى بن معِين، يَقُول: جَابر الْجعْفِيّ، لَا يكْتب حَدِيثه، وَلَا كَرَامَة."],[1284,"٥٤٦"],[1285,"- حَدَّثَنَا أَحْمَدُ بْنُ يَحْيَى السَّابَرِيُّ، قَالَ: حَدَّثَنَا أَحْمَدُ بْنُ أَبِي طَيْبَةَ، عَنْ وَرْقَاءَ، عَنْ مَنْصُورٍ، عَنْ رَجُلٍ مِنْ أَهْلِ الْبَصْرَةِ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ، أَنّ النَّبِيَّ صلى الله عليه وآله وسلم أَعْتَقَ صَفِيَّةَ بِنْتَ حُيَيٍّ، وَجَعَلَ عِتْقَهَا صَدَاقَهَا، وَأَوْلَمَ لَهُمْ حَيْسًا عَلَى نِطَعٍ"],[1286,"٥٤٧"],[1287,"- حَدَّثَنَا عَطِيَّةُ بْنُ بَقِيَّةَ بْنِ الْوَلِيدِ الْحِمْصُيِّ، قَالَ: حَدَّثَنِي أَبِي، عَنْ زَيْدِ بْنِ وَاقِدٍ، عَنْ بُسْرِ بْنِ عُبَيْدِ اللَّهِ، عَنْ يَزِيدَ بْنِ خُمَيْرٍ، قَالَ: سَمِعْتُ عَوْفَ بْنَ مَالِكٍ، يَقُولُ: سَمِعْتُ رَسُولِ اللَّهِ صلى الله عليه وآله وسلم، يَقُولُ: الْقُصَّاصُ ثَلَاثَةٌ: أَمِيرٌ أَوْ مَأْمُورٌ، أَوْ مُخْتَالٌ"],[1288,"٥٤٨"],[1289,"- حَدثنَا زَكَرِيَّا بن يحيى، قَالَ: حَدثنَا ابْن عُيَيْنَة، عَن سُلَيْمَان"],[1290,"بْنِ مُسلم الْأَحول، قَالَ: كُنَّا بِمَكَّة ومعنا مقسم، وَأَنا مَعَ طَاوُوس، فَجعل يحدثه مقسم، فَجعل طَاوُوس يَقُول: إِنَّه مقسم، قَالَ: فَقلت: يَا أَبَا عبد الرَّحْمَن أَبَا الْقَاسِم؟ فَقَالَ: وَالله لَا أكنيه بهَا أبدا."],[1291,"٥٤٩"],[1292,"- حَدَّثَنَا مُحَمَّدُ بْنُ عَامِرٍ، قَالَ: حَدَّثَنَا مُحَمَّدُ بْنُ عِيسَى، قَالَ: حَدَّثَنَا الْقَاسِمُ بْنُ مُوسَى، عَنِ الْأَوْزَاعِيِّ، عَنْ عُمَرَ بن عبد الله بن"],[1293,"أَبِي طَلْحَةَ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: قَالَ النَّبِيُّ صلى الله عليه وآله وسلم: كُلُّ مُسْكِرٍ حَرَامٌ"],[1294,"٥٥٠"],[1295,"- حَدَّثَنَا مُسْلِمُ بْنُ الْحَجَّاجِ، قَالَ: حَدَّثَنِي أَبُو غَسَّانَ الْمِسْمَعِيُّ، قَالَ: حَدَّثَنَا مُعَاذُ بْنُ هِشَامٍ، قَالَ: حَدَّثَنِي أَبِي، عَنْ مَطَرٍ، عَنْ سَعْدِ بْنِ هِشَامٍ، عَنْ عَائِشَةَ، أَنَّ نَبِيَّ اللَّهِ صلى الله عليه وآله وسلم: كَانَ يُصَلِّي قَبْلَ الظُّهْرِ أَرْبَعًا"],[1296,"٥٥١"],[1297,"- قَالَ سَمِعت الْمُزنِيّ، يَقُول: سَمِعت الشَّافِعِي، يَقُول: لَيْسَ"],[1298,"من قوم لَا يخرجُون نِسَائِهِم إِلَى رجال غَيرهم، إِلَّا جَاءَ أَوْلَادهم حمقى."],[1299,"٥٥٢"],[1300,"- حَدثنَا أَبُو عُبَيْدَة ابْن أخي هناد، قَالَ: حَدثنَا عُثْمَان بن زفر، قَالَ: حَدثنَا حبَان بن عَليّ، عَن ابْن شبْرمَة، قَالَ: مَا لبس الرِّجَال لباسا أزين من الْعَرَبيَّة."],[1301,"٥٥٣"],[1302,"- حَدثنِي زَكَرِيَّا بن يحيى، الْبَصْرِيّ، قَالَ: سَمِعت الْأَصْمَعِي،"],[1303,"يَقُول: كَانَ على خَاتم أبي عَمْرو بن الْعَلَاء إِن أمرأ دُنْيَاهُ أكبر همه لمستمسك مِنْهَا بِحَبل غرور ٥٥٤ - حَدثنَا عبد الله بن مُحَمَّد الْقرشِي، قَالَ: حَدثنَا عبد الرَّحْمَن بن صَالح، قَالَ: حَدثنَا أَبُو تُمَيْلة، عَن أبي غَانِم، عَن أبي سهل كثير"],[1304,"بن زِيَاد."],[1305,"﴿وَثِيَابَكَ فَطَهِّرْ﴾ [المدثر: ٤]، قَالَ: خلقك فحسنه."],[1306,"٥٥٥"],[1307,"- حَدثنَا وهيب بن يزِيد، قَالَ: حَدثنَا ضَمرَة، عَن رَجَاء بن أبي سَلمَة، قَالَ: قَالَ خَالِد بن يزِيد بن مُعَاوِيَة: إِنِّي لأدع كثيرا من الْكَلَام مَخَافَة الْجَواب."],[1308,"٥٥٦"],[1309,"- حَدثنَا زَكَرِيَّا بن يحيى، الْبَصْرِيّ، قَالَ: حَدَّثتنَا أم مُحَمَّد"],[1310,"الحبطية، قَالَ: قَالَت عشيرة رَابِعَة لَهَا: كلمي الْأَمِير بِأَن يَشْتَرِي دَارا لعشيرتك يأوون إِلَيْهَا، فَقَالَت: وَالله إِنِّي لأستحيي أَن أسأَل الدُّنْيَا من يملكهَا، فَكيف أسألها من لَا يملكهَا."],[1311,"٥٥٧"],[1312,"- حَدَّثَنَا جَعْفَرُ بْنُ مُحَمَّدِ بْنِ نُوحٍ الأَذَنِيُّ، قَالَ: حَدَّثَنَا مُحَمَّدُ بْنُ عِيسَى، عَنْ مَالِكِ بْنِ أَنَسٍ، عَنِ يَحْيَى بْنِ سَعِيدٍ، عَنْ مُحَمَّدِ بْنِ يَحْيَى بْنِ حِبَّانَ، \" أَنَّ امْرَأَتَهُ فَاطِمَةَ عَاتَبَتْهُ فِي قِلَّةِ إِتْيَانِهِ إِيَّاهَا، فَقَالَ لَهَا: بَيْنِي وَبَيْنَكِ قَضَاءُ عُمَرَ بْنِ الْخَطَّابِ،"],[1313,"فَقُلْتُ: وَمَا قَضَاءُ عُمَرَ؟ قَالَ: فِي كُلِّ طُهْرٍ مَرَّةً، قَالَتْ: قَدْ تُرِكَ قَضَاءُ عُمَرَ فِي هَذَا، فَكَيْفَ آخُذُ بِهِ أَنَا وَأَنْتَ؟ \""],[1314,"٥٥٨"],[1315,"- حَدثنَا أَحْمد بن عبد الرَّحْمَن، قَالَ: سَمِعت الْأَصْمَعِي، يَقُول: أَخْبرنِي أَبُو عمر بن الْعَلَاء، قَالَ: مَا تشاتم رجلَانِ قطّ إِلَّا غلب ألأمهما."],[1316,"٥٥٩"],[1317,"- حَدثنَا الْعَبَّاس بن مُحَمَّد، قَالَ: حَدثنَا قراد أَبُو نوح، قَالَ: سَمِعت إِسْمَاعِيل بن علية، قَالَ: سَمِعت يُونُس بن عبيد، يَقُول: لما مَاتَ سعيد بن أبي الْحسن أَخُو الْحسن الْبَصْرِيّ، طَال"],[1318,"حزن الْحسن وبكاؤه عَلَيْهِ، فَقُلْنَا لَهُ: إِنَّك إِمَام من الْأَئِمَّة، يَقْتَدِي بك، فَلَو تركت بعض مَا أَنْت عَلَيْهِ، فَقَالَ: دَعونِي، فَمَا رَأَيْت الله تَعَالَى عَابَ على يَعْقُوب طول الْحزن على يُوسُف، فَمَا زَاده إِلَّا حزنا وبكاء."],[1319,"٥٦٠"],[1320,"- حَدثنَا زَكَرِيَّا بن يحيى، قَالَ: حَدثنَا الْأَصْمَعِي، قَالَ: حَدثنِي هِشَام بن الحكم الثَّقَفِيّ، قَالَ: كَانَ يُقَال خَمْسَة أَشْيَاء تقبح فِي الرجل: الفتوة فِي الشُّيُوخ، والحرص عِلّة الْقُرَّاء، وَقلة الْحَيَاة فِي ذَوي الْحساب وَالْبخل فِي ذَوي الْأَمْوَال، والحدة فِي السُّلْطَان."],[1321,"٥٦١"],[1322,"- قَالَ الْأَصْمَعِي وَقَالَ أَعْرَابِي لأبنه: يَا بني، إِن الْغَالِب بِالشَّرِّ هُوَ المغلوب."],[1323,"٥٦٢"],[1324,"- حَدثنَا أَبُو الكروش مُحَمَّد بن عَمْرو بن تَمام، قَالَ: سَمِعت نعيم بن حَمَّاد، يَقُول: سَمِعت هشيما، يَقُول: سَمِعت من أبي الزبير، فَأَخذه شُعْبَة فمزقه."],[1325,"٥٦٣"],[1326,"- حَدثنَا أَحْمد بن مُحَمَّد بن أبي رَجَاء المصِّيصِي، قَالَ: حَدثنَا وَكِيع، قَالَ: حَدثنَا أبي عبد الله الشَّامي، قَالَ: اسْتَأْذَنت على طَاوُوس لأسأله عَن مَسْأَلَة فَخرج عَليّ شيخ كَبِير، فَظَنَنْت أَنه طَاوس، قَالَ: قلت: أَنْت طَاوُوس، قَالَ: أَنا ابْنه، قلت: إِن كنت ابْنه، فقد خرف أَبوك."],[1327,"قَالَ: يَقُول ذَا لي: إِن الْعَالم لَا يخرف، قَالَ: فَاسْتَأْذن لي عَلَيْهِ، فَدخلت عَلَيْهِ،"],[1328,"فَقَالَ لي طَاوُوس: سل وأوجز، وَإِن شِئْت علمتك فِي مجلسك هَذَا الْقُرْآن والتوراة وَالْإِنْجِيل، قَالَ: قلت: لَو علمتني التَّوْرَاة وَالْإِنْجِيل لَا أَسأَلك عَن شَيْء، قَالَ: خف الله مَخَافَة لَا يكون شَيْء أخوف عنْدك مِنْهُ، وارجه رَجَاء هُوَ أَشد من خوفك إِيَّاه، وَأحب للنَّاس مَا تحب لنَفسك."],[1329,"٥٦٤"],[1330,"- قَالَ: حَدثنَا سَعْدَان بن يزِيد، قَالَ: حَدثنَا سنيد، قَالَ: حَدثنَا حجاج، عَن عقبَة بن سِنَان، قَالَ أَكْثَم بن صَيْفِي: لَيْسَ للمختال فِي حسن الثَّنَاء نصيب."],[1331,"٥٦٥"],[1332,"- حَدثنَا مُحَمَّد بن عبد الْملك الدقيقي، قَالَ: سَمِعت عَفَّان بن مُسلم يحدث، عَن حَمَّاد بن سَلمَة، قَالَ: قَالَ ثَابت: اللَّهُمَّ إِن كنت أَعْطَيْت أحدا الصَّلَاة فِي قَبره، فَأعْطِنِي الصَّلَاة فِي قَبْرِي."],[1333,"٥٦٦"],[1334,"- حَدثنَا الصَّنْعَانِيّ، قَالَ: حَدثنَا عبد الصَّمد بن حسان، قَالَ: رَأَيْت سُفْيَان الثَّوْريّ بِمَكَّة يشرب الخروع بالعسل، وَكَانَ قد رَجَعَ عَن رَأْيه فِي النَّبِيذ."],[1335,"٥٦٧"],[1336,"- حَدثنَا ابْن الفرحي، عَن أبي خَيْثَمَة، قَالَ: سُئِلَ يحيى بن سعيد، عَن شرب النَّبِيذ، فَقَالَ سَمِعت سُلَيْمَان التَّيْمِيّ، يَقُول مَا يَنْبَغِي للمرء الْمُسلم فِي شربه أَن يخاطر بِدِينِهِ."],[1337,"٥٦٨"],[1338,"- حَدثنِي الْحُسَيْن بن يزِيد الْقرشِي، قَالَ: حَدثنَا ابْن الْمُغيرَة الْكُوفِي، قَالَ: سَمِعت سُفْيَان الثَّوْريّ، يَقُول: طب على الْوحدَة نفسا وَارْضَ بالوحشة أنسا لم أجد فِي النَّاس من يسوى على الْخِبْرَة فلسًا."],[1339,"٥٦٩"],[1340,"- حَدثنَا إِسْحَاق بن الْجراح، قَالَ: سَمِعت يزِيد بن هَارُون، يَقُول لهارون الْمُسْتَمْلِي: اللَّهُمَّ لَا تجعلنا ثقلاء."],[1341,"٥٧٠"],[1342,"- سَمِعت مُحَمَّد بن إِسْمَاعِيل الصَّائِغ، يَقُول: سَمِعت يزِيد بن هَارُون، يَقُول: التَّغْيِير بِدعَة وضلالة."],[1343,"٥٧١"],[1344,"- حَدثنِي مضاء أَبُو الرِّضَا، عَن أَحْمد بن خَالِد الْخلال، قَالَ: كتب رجل إِلَى رجل فِي حَاجَة فمطله، فَكتب إِلَيْهِ: يَا أخي، إِن الْعذر الْجَمِيل أحسن من المطل الطَّوِيل، فَإِن كَانَت حاجتنا تهيأت فأنجح، وَإِن كَانَت تعدرت فأوضح."],[1345,"٥٧٢"],[1346,"- حَدثنَا إِبْرَاهِيم بن الْحُسَيْن الْكسَائي، قَالَ: حَدثنَا مُسَدّد، قَالَ: حَدثنَا أُميَّة بن خَالِد، قَالَ: حَدثنِي تسنيم بن الْحوَاري، قَالَ: حَدثنَا قَتَادَة، قَالَ: دَخَلنَا على امْرَأَة فأنشأت تَقول: الْمَرْء يَدْعُو بِالسَّلَامِ وَطول عَيْش قد يضرّهُ"],[1347,"تفنى بشاشته وَيبقى بعد حُلْو الْعَيْش مره وتتابع الحسرات حَتَّى لَا يرى شَيْئا يسره كم شامت بِي إِن هَلَكت وَقَائِل الله دره."],[1348,"٥٧٣"],[1349,"- حَدثنَا أَبُو دَاوُد الْحَرَّانِي. قَالَ: حَدثنَا أَبُو عتاب. قَالَ: سَمِعت سعيد بن أبي عرُوبَة. يَقُول: إِنِّي لأحب أَن يُقَال لي: هَذَا عثماني."],[1350,"٥٧٤"],[1351,"- حَدثنَا أَبُو حَاتِم، قَالَ: حَدثنَا عبد الْوَهَّاب بن قُرَّة"],[1352,"الوَاسِطِيّ، عَن هشيم، قَالَ: قلت لعَمْرو بن عبيد: صف لي الْحسن، قَالَ: كنت إِذا رَأَيْته كَأَنَّهُ جَاءَ من دفن أمه، وَإِذا جلس، جلس جُلُوس الْأَسير يضْرب عُنُقه، وَإِذا تكلم، تكلم كَلَام رجل قد أَمر بِهِ إِلَى النَّار."],[1353,"٥٧٥"],[1354,"- حَدثنَا إِبْرَاهِيم بن مُحَمَّد بن أبي الْجَحِيم الْبَصْرِيّ، قَالَ: حَدثنَا أَبُو عمر الحوضي، قَالَ: كَانَ شُعْبَة إِذا فرغ من الحَدِيث، قَالَ: انْقَطع الْوتر، صلى الله على مُحَمَّد."],[1355,"٥٧٦"],[1356,"- حَدثنَا ابْن أبي الْجَحِيم، قَالَ: حَدثنَا نصر بن عَليّ، قَالَ: حَدثنَا أَبُو دَاوُد، عَن شُعْبَة، قَالَ: أفادني عُثْمَان الْبري، حَدثنَا عَن قَتَادَة، فَأتيت قَتَادَة، فَسَأَلته عَنهُ، فَقَالَ: مَا حدثته بِهِ،"],[1357,"فَاجْتَمَعْنَا عِنْد قَتَادَة، فَقَالَ لَهُ عُثْمَان حَدثنِي بِحَدِيث كَذَا وَكَذَا، فَقَالَ مَا حدثتك قطّ بِهِ."],[1358,"قَالَ: بلَى، قد حَدَّثتنِي بِهِ، قَالَ قَتَادَة لعُثْمَان: تَدْرِي مَا جرأك عَليّ؟ لَك عَليّ مِائَتَا دِرْهَم."],[1359,"٥٧٧"],[1360,"- حَدثنَا عَبَّاس الدوري، قَالَ: حَدثنَا إِسْمَاعِيل بن دَاوُد الْجَزرِي، قَالَ: حَدثنَا يحيى بن مطر، عَن حَمَّاد بن سَلمَة، قَالَ: دخلت على إِيَاس بن مُعَاوِيَة، وَهُوَ يَأْكُل فالوذجًا، فَقَالَ لي: هَلُمَّ، فاطعم فَإِنَّهُ يزِيد فِي الْعقل، فَقلت ليحيى بن مطر: فِي كم يطعم الرجل عِيَاله الفالوذج؟ قَالَ: فِي كل جُمُعَة."],[1361,"٥٧٨"],[1362,"- حَدثنَا الصغاني، قَالَ: سَمِعت أَبَا النَّضر، يَقُول: كَانَ"],[1363,"سُفْيَان فاضح الْقُرَّاء."],[1364,"٥٧٩"],[1365,"- حَدثنَا الصغاني، قَالَ: حَدثنَا عبيد الله بن عَائِشَة، قَالَ: حَدثنَا حَمَّاد بن سَلمَة، عَن ثَابت، أَن عَامر بن عبد الله، قَالَ لَا بني عَم لَهُ: فوضا أمركما إِلَى الله، تسريحا."],[1366,"٥٨٠"],[1367,"- حَدَّثَنَا أَبُو هُبَيْرَةَ مُحَمَّدُ بْنُ الْوَلِيدِ الْقَلَانِسِيُّ الدِّمَشْقِيُّ مَوْلَى بَنِي هَاشِمٍ، قَالَ: حَدَّثَنَا أَبُو أَيُّوبَ سُلَيْمَانُ بْنُ شُرَحْبِيلَ، حَدَّثَنَا"],[1368,"أَبُو خُلَيْدٍ الْقَارِي عُتْبَةُ بْنُ حَمَّادٍ، قَالَ: حَدَّثَنَا الْأَوْزَاعِيُّ، قَالَ: بَعَثَ إِلَيَّ عَبْدُ اللَّهِ بْنُ عَلِيٍّ، فَأَعْظَمَنِي ذَلِكَ، وَاشْتَدَّ عَلَيَّ، قَالَ: فَقَدِمْتُ عَلَيْهِ، قَالَ: فَدَخَلْتُ وَالنَّاسُ سِمَاطَانِ قَائِمٌ فِي أَقْدَمِهِمُ الْكَافِرُ كوبات، قَالَ: فَأَدْنَانِي، ثُمَّ سَأَلَنِي، قَالَ: يَا عَبْدَ الرَّحْمَنِ، مَا تَقُولُ فِي مَخْرَجِنَا هَذَا، وَمَا نَحْنُ فِيهِ؟ قَالَ: قُلْتُ: أَصْلَحَ اللَّهُ الْأَمِيرَ، قَالَ: كَانَ بَيْنِي وَبَيْنَ دَاوُدَ بْنِ عَلِيٍّ مَوَدَّةٌ، قَالَ:"],[1369,"لِتُخْبِرْنِي، قَالَ: فَتَفَكَّرْتُ، ثُمَّ قُلْتُ: وَاللَّهِ لَأَصْدُقَنَّهُ، قَالَ: وَاسْتَسْلَمْتُ لِلْمَوْتِ، فَقُلْتُ حَدَّثَنِي يَحْيَى بْنُ سَعِيدٍ الْأَنْصَارِيُّ، عَنْ مُحَمَّدِ بْنِ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ بْنِ وَقَّاصٍ، قَالَ: سَمِعْتُ عُمَرَ بْنَ الْخَطَّابِ، َرِضَي اللَّهُ عَنْهُ، يَقُولُ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وآله وسلم: «الْأَعْمَالُ بِالنِّيَّةِ، وَإِنَّمَا لِامْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ إِلَى دُنْيَا يُصِيبُهَا أَوِ امْرَأَةٍ يَنْكِحُهَا، فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ» قَالَ: وَبِيَدِهِ قَضِيبٌ يَنْكُتُ فِي الْأَرْضِ، ثُمَّ قَالَ: يَا عَبْدَ الرَّحْمَنِ، مَا تَقُولُ فِي قَتْلِ أَهْلِ هَذَا الْبَيْتِ؟ قَالَ: فَوَرَدَ عَلَيَّ أَمْرٌ عَظِيمٌ، وَاسْتَسْلَمْتُ لِلَّهِ تَعَالَى."],[1370,"قَالَ: قُلْتُ وَاللَّهِ لَأَصْدُقَنَّهُ، قَالَ: ثُمَّ قُلْتُ: أَصْلَحَ اللَّهُ الْأَمِيرَ قَدْ كَانَ بَيْنِي وَبَيْنَ أَخِيكَ دَاوُدَ مَوَدَّةٌ، قَالَ: هِيهِ لِتُخْبِرْنِي"],[1371,"، قَالَ: فَقُلْتُ: حَدَّثَنِي مَرْوَانُ، عَنْ مُطَرِّفِ بْنِ الشِّخِّيرِ، عَنْ عَائِشَةَ، قَالَتْ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وآله وسلم:"],[1372,"\"لَا يَحِلُّ قَتْلُ الْمُسْلِمِ إِلَّا فِي ثَلَاثٍ: التَّارِكُ لِدِينِهِ، أَوْ رَجُلٌ قَتَلَ نَفْسًا فَيُقْتَلُ، أَوْ رَجُلٍ زَنَى بَعْدَ إِحْصَانٍ\" قَالَ: ثُمَّ أَطْرَقَ، وَهُوَ قَائِمٌ، قَالَ: أَخْبَرَنِي عَنِ الْخِلَافَةِ وَصِيَّةٌ لَنَا مِنْ رَسُولِ اللَّهِ صلى الله عليه وآله وسلم، قَالَ: فَوَرَدَ عَلَيَّ أَمْرٌ عَظِيمٌ، وَاسْتَسْلَمْتُ لِلْمَوْتِ، وَقُلْتُ: لَأَصْدُقَنَّهُ، فَقُلْتُ: أَصْلَحَ اللَّهُ الْأَمِيرَ، قَدْ كَانَ بَيْنِي وَبَيْنَ دَاوُدَ بْنِ عَلِيٍّ صَدَاقَةٌ، قَالَ: لِتُخْبِرْنِي، ثُمَّ قُلْتُ: لَوْ كَانَتْ وَصِيَّةٌ مِنْ رَسُولِ اللَّهِ صلى الله عليه وآله وسلم، مَا تَرَكَ عَلِيُّ بْنُ أَبِي طَالِبٍ أَحَدًا يَتَقَدَّمُهُ، ثُمَّ سَكَتَ سَكْتَةً، ثُمَّ قَالَ: مَا تَقُولُ فِي أَمْوَالِ بَنِي أُمَيَّةَ، أَحَلَالٌ لَنَا؟ قَالَ: فَاسْتَسْلَمْتُ لِلْمَوْتِ، وَقُلْتُ لَأَصْدُقَنَّهُ، قَالَ: قُلْتُ: أَصْلَحَ اللَّهُ الْأَمِيرَ، قَدْ كَانَ بَيْنِي وَبَيْنَ دَاوُدَ مَوَدَّةٌ، قَالَ: لِتُخْبِرْنِي، قَالَ: فَقُلْتُ لَهُ: إِنْ كَانَتْ لَهُمْ حَلَالًا، فَهِيَ عَلَيْكَ حَرَامٌ، وَإِنْ كَانَتْ عَلَيْهِمْ حَرَامًا، فَهِيَ عَلَيْكَ أحَرْمُ، قَالَ: ثُمَّ أَمَرَنِي فَأُخْرِجْتُ"],[1373,"٥٨١"],[1374,"- حَدثنَا مُحَمَّد بن أَحْمد الْبَصْرِيّ، عَن إِبْرَاهِيم بن مُحَمَّد، قَالَ: سَمِعت سُفْيَان بن عُيَيْنَة، يَقُول: دخل ملك الْمَوْت على دَاوُد، فَقَالَ: من أَنْت؟ قَالَ: من لَا يهاب الْمُلُوك، وَلَا يمْتَنع مِنْهُ الْقُصُور، وَلَا يقبل الرشى."],[1375,"٥٨٢"],[1376,"- حَدثنَا أَحْمد بن سعد أَبُو إِبْرَاهِيم الزُّهْرِيّ، قَالَ: حَدثنَا خالج بن حذاء، قَالَ: حَدثنَا معلي بن هِلَال الْوراق، عَن مَالك"],[1377,"ابْن دِينَار، قَالَ: دخلت على جَار لي وَهُوَ مَرِيض، فَقلت: عَاهَدَ الله تَعَالَى أَن تتوب، فَعَسَى أَن يشفيك، قَالَ: هَيْهَات يَا أَبَا يحيى، أَنا ميت، ذهبت أعَاهد كَمَا كنت أعَاهد، فَسمِعت قَائِلا من نَاحيَة الْبَيْت يَقُول: عاهدناك مرَارًا فوجدناك كذوبا."],[1378,"٥٨٣"],[1379,"- حَدثنَا أَحْمد بن عُثْمَان الأودي، قَالَ: حَدثنَا قَاسم بن قيس النَّخعِيّ، قَالَ: حَدثنَا حميد بن الْمثنى، عَن أبي جَعْفَر، قَالَ: إِذا امْتَلَأَ الْبَطن طَغى الْجَسَد."]]);
